(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("suetonius-caesars-1-b", [{"sp": "HDR", "t": "De Vita Caesarum (Divus Iulius – Tiberius)"}, {"sp": "HDR", "t": "Divus Iulius", "st": "Jul."}, {"sp": "N", "t": "… Annum agens sextum decimum patrem amisit; sequentibusque consulibus flamen Dialis destinatus dimissa Cossutia, quae familia equestri sed admodum diues praetextato desponsata fuerat, Corneliam Cinnae quater consulis filiam duxit uxorem, ex qua illi mox Iulia nata est; neque ut repudiaret compelli a dictatore Sulla ullo modo potuit. quare et sacerdotio et uxoris dote et gentilicis hereditatibus multatus diuersarum partium habebatur, ut etiam discedere e medio et quamquam morbo quartanae adgrauante prope per singulas noctes commutare latebras cogeretur seque ab inquisitoribus pecunia redimeret, donec per uirgines Vestales perque Mamercum Aemilium et Aurelium Cottam propinquos et adfines suos ueniam impetrauit. satis constat Sullam, cum deprecantibus amicissimis et ornatissimis uiris aliquamdiu denegasset atque illi pertinaciter contenderent, expugnatum tandem proclamasse siue diuinitus siue aliqua coniectura: 'uincerent ac sibi haberent, dum modo scirent eum, quem incolumem tanto opere cuperent, quandoque optimatium partibus, quas secum simul defendissent, exitio futurum; nam Caesari multos Marios inesse.'", "st": "Jul. 1"}, {"sp": "N", "t": "Stipendia prima in Asia fecit Marci Thermi praetoris contubernio; a quo ad accersendam classem in Bithyniam missus desedit apud Nicomeden, non sine rumore prostratae regi pudicitiae; quem rumorem auxit intra paucos rursus dies repetita Bithynia per causam exigendae pecuniae, quae deberetur cuidam libertino clienti suo. reliqua militia secundiore fama fuit et a Thermo in expugnatione Mytilenarum corona ciuica donatus est.", "st": "Jul. 2"}, {"sp": "N", "t": "meruit et sub Seruilio Isaurico in Cilicia, sed breui tempore. nam Sullae morte comperta, simul spe nouae dissensionis, quae per Marcum Lepidum mouebatur, Romam propere redit. et Lepidi quidem societate, quamquam magnis condicionibus inuitaretur, abstinuit, cum ingenio eius diffisus tum occasione, quam minorem opinione offenderat.", "st": "Jul. 3"}, {"sp": "N", "t": "ceterum composita seditione ciuili Cornelium Dolabellam consularem et triumphalem repetundarum postulauit; absolutoque Rhodum secedere statuit, et ad declinandam inuidiam et ut per otium ac requiem Apollonio Moloni clarissimo tunc dicendi magistro operam daret. huc dum hibernis iam mensibus traicit, circa Pharmacussam insulam a praedonibus captus est mansitque apud eos non sine summa indignatione prope quadraginta dies cum uno medico et cubicularis duobus. nam comites seruosque ceteros initio statim ad expediendas pecunias, quibus redimeretur, dimiserat. numeratis deinde quinquaginta talentis expositus in litore non distulit quin e uestigio classe deducta persequeretur abeuntis ac redactos in potestatem supplicio, quod saepe illis minatus inter iocum fuerat, adficeret. uastante regiones proximas Mithridate, ne desidere in discrimine sociorum uideretur, ab Rhodo, quo pertenderat, transiit in Asiam auxiliisque contractis et praefecto regis prouincia expulso nutantis ac dubias ciuitates retinuit in fide.", "st": "Jul. 4"}, {"sp": "N", "t": "Tribunatu militum, qui primus Romam reuerso per suffragia populi honor optigit, actores restituendae tribuniciae potestatis, cuius uim Sulla deminuerat, enixissime iuuit. L. etiam Cinnae uxoris fratri, et qui cum eo ciuili discordia Lepidum secuti post necem consulis ad Sertorium confugerant, reditum in ciuitatem rogatione Plotia confecit habuitque et ipse super ea re contionem.", "st": "Jul. 5"}, {"sp": "N", "t": "Quaestor Iuliam amitam uxoremque Corneliam defunctas laudauit e more pro rostris. [s]et in amitae quidem laudatione de eius ac patris sui utraque origine sic refert: 'Amitae meae Iuliae maternum genus ab regibus ortum, paternum cum diis inmortalibus coniunctum est. nam ab Anco Marcio sunt Marcii Reges, quo nomine fuit mater; a Venere Iulii, cuius gentis familia est nostra. est ergo in genere et sanctitas regum, qui plurimum inter homines pollent, et caerimonia deorum, quorum ipsi in potestate sunt reges.' In Corneliae autem locum Pompeiam duxit Quinti Pompei filiam, L. Sullae neptem; cum qua deinde diuortium fecit adulteratam opinatus a Publio Clodio, quem inter publicas caerimonias penetrasse ad eam muliebri ueste tam constans fama erat, ut senatus quaestionem de pollutis sacris decreuerit.", "st": "Jul. 6"}, {"sp": "N", "t": "Quaestori ulterior Hispania obuenit; ubi cum mandatu pr. iure dicundo conuentus circumiret Gadisque uenisset, animaduersa apud Herculis templum Magni Alexandri imagine ingemuit et quasi pertaesus ignauiam suam, quod nihil dum a se memorabile actum esset in aetate, qua iam Alexander orbem terrarum subegisset, missionem continuo efflagitauit ad captandas quam primum maiorum rerum occasiones in urbe. etiam confusum eum somnio proximae noctis—nam uisus erat per quietem stuprum matri intulisse—coiectores ad amplissimam spem incitauerunt arbitrium terrarum orbis portendi interpretantes, quando mater, quam subiectam sibi uidisset, non alia esset quam terra, quae omnium parens haberetur.", "st": "Jul. 7"}, {"sp": "N", "t": "decedens ergo ante tempus colonias Latinas de petenda ciuitate agitantes adiit, et ad audendum aliquid concitasset, nisi consules conscriptas in Ciliciam legiones paulisper ob id ipsum retinuissent.", "st": "Jul. 8"}, {"sp": "N", "t": "Nec eo setius maiora mox in urbe molitus est: siquidem ante paucos dies quam aedilitatem iniret, uenit in suspicionem conspirasse cum Marco Crasso consulari, item Publio Sulla et L. Autronio post designationem consulatus ambitus condemnatis, ut principio anni senatum adorirentur, et trucidatis quos placitum esset, dictaturam Crassus inuaderet, ipse ab eo magister equitum diceretur constitutaque ad arbitrium re publica Sullae et Autronio consulatus restitueretur. meminerunt huius coniurationis Tanusius Geminus in historia, Marcus Bibulus in edictis, C. Curio pater in orationibus. de hac significare uidetur et Cicero in quadam ad Axium epistula referens Caesarem in consulatu confirmasse regnum, de quo aedilis cogitarat. Tanusius adicit Crassum paenitentia uel metu diem caedi destinatum non obisse et idcirco ne Caesarem quidem signum, quod ab eo dari conuenerat, dedisse; conuenisse autem Curio ait, ut togam de umero deiceret. idem Curio sed et M. Actorius Naso auctores sunt conspirasse eum etiam cum Gnaeo Pisone adulescente, cui ob suspicionem urbanae coniurationis prouincia Hispania ultro extra ordinem data sit; pactumque ut simul foris ille, ipse Romae ad res nouas consurgerent, per †Ambranos et Transpadanos; destitutum utriusque consilium morte Pisonis.", "st": "Jul. 9"}, {"sp": "N", "t": "Aedilis praeter comitium ac forum basilicasque etiam Capitolium ornauit porticibus ad tempus extructis, in quibus abundante rerum copia pars apparatus exponeretur. uenationes autem ludosque et cum collega et separatim edidit, quo factum est, ut communium quoque inpensarum solus gratiam caperet nec dissimularet collega eius Marcus Bibulus, 'euenisse sibi quod Polluci: ut enim geminis fratribus aedes in foro constituta tantum Castoris uocaretur, ita suam Caesarisque munificentiam unius Caesaris' dici. adiecit insuper Caesar etiam gladiatorium munus, sed aliquanto paucioribus quam destinauerat paribus; nam cum multiplici undique familia conparata inimicos exterruisset, cautum est de numero gladiatorum, quo ne maiorem cuiquam habere Romae liceret.", "st": "Jul. 10"}, {"sp": "N", "t": "Conciliato populi fauore temptauit per partem tribunorum, ut sibi Aegyptus prouincia plebi scito daretur, nanctus extraordinarii imperii occasionem, quod Alexandrini regem suum socium atque amicum a senatu appellatum expulerant resque uulgo inprobabatur. nec obtinuit aduersante optimatium factione: quorum auctoritatem ut quibus posset modis in uicem deminueret, tropaea Gai Mari de Iugurtha deque Cimbris atque Teutonis olim a Sulla disiecta restituit atque in exercenda de sicaris quaestione eos quoque sicariorum numero habuit, qui proscriptione ob relata ciuium Romanorum capita pecunias ex aerario acceperant, quamquam exceptos Cornelis legibus.", "st": "Jul. 11"}, {"sp": "N", "t": "subornauit etiam qui Gaio Rabirio perduellionis diem diceret, quo praecipuo adiutore aliquot ante annos Luci Saturnini seditiosum tribunatum senatus coercuerat, ac sorte iudex in reum ductus tam cupide condemnauit, ut ad populum prouocanti nihil aeque ac iudicis acerbitas profuerit.", "st": "Jul. 12"}, {"sp": "N", "t": "deposita prouinciae spe pontificatum maximum petit non sine profusissima largitione; in qua reputans magnitudinem aeris alieni, cum mane ad comitia descenderet, praedixisse matri osculanti fertur domum se nisi pontificem non reuersurum. atque ita potentissimos duos competitores multumque et aetate et dignitate antecedentes superauit, ut plura ipse in eorum tribubus suffragia quam uterque in omnibus tulerit.", "st": "Jul. 13"}, {"sp": "N", "t": "Praetor creatus, detecta coniuratione Catilinae senatuque uniuerso in socios facinoris ultimam statuente poenam, solus municipatim diuidendos custodiendosque publicatis bonis censuit. quin et tantum metum iniecit asperiora suadentibus, identidem ostentans quanta eos in posterum a plebe Romana maneret inuidia, ut Decimum Silanum consulem designatum non piguerit sententiam suam, quia mutare turpe erat, interpretatione lenire, uelut grauius atque ipse sensisset exceptam. obtinuisset adeo transductis iam ad se pluribus et in his Cicerone consulis fratre, nisi labantem ordinem confirmasset M. Catonis oratio. ac ne sic quidem impedire rem destitit, quoad manus equitum Romanorum, quae armata praesidii causa circumstabat, inmoderatius perseueranti necem comminata est, etiam strictos gladios usque eo intentans, ut sedentem una proximi deseruerint, uix pauci complexu togaque obiecta protexerint. tunc plane deterritus non modo cessit, sed et in reliquum anni tempus curia abstinuit.", "st": "Jul. 14"}, {"sp": "N", "t": "Primo praeturae die Quintum Catulum de refectione Capitoli ad disquisitionem populi uocauit rogatione promulgata, qua curationem eam in alium transferebat; uerum impar optimatium conspirationi, quos relicto statim nouorum consulum officio frequentes obstinatosque ad resistendum concucurrisse cernebat, hanc quidem actionem deposuit.", "st": "Jul. 15"}, {"sp": "N", "t": "ceterum Caecilio Metello tribuno plebis turbulentissimas leges aduersus collegarum intercessionem ferenti auctorem propugnatoremque se pertinacissime praestitit, donec ambo administratione rei publicae decreto patrum submouerentur. ac nihilo minus permanere in magistratu et ius dicere ausus, ut comperit paratos, qui ui ac per arma prohiberent, dimissis lictoribus abiectaque praetexta domum clam refugit pro condicione temporum quieturus. multitudinem quoque biduo post sponte et ultro confluentem operamque sibi in adserenda dignitate tumultuosius pollicentem conpescuit. quod cum praeter opinionem euenisset, senatus ob eundem coetum festinato coactus gratias ei per primores uiros egit accitumque in curiam et amplissimis uerbis conlaudatum in integrum restituit inducto priore decreto.", "st": "Jul. 16"}, {"sp": "N", "t": "Recidit rursus in discrimen aliud inter socios Catilinae nominatus et apud Nouium Nigrum quaestorem a Lucio Vettio indice et in senatu a Quinto Curio, cui, quod primus consilia coniuratorum detexerat, constituta erant publice praemia. Curius e Catilina se cognouisse dicebat, Vettius etiam chirographum eius Catilinae datum pollicebatur. id uero Caesar nullo modo tolerandum existimans, cum inplorato Ciceronis testimonio quaedam se de coniuratione ultro ad eum detulisse docuisset, ne Curio praemia darentur effecit; Vettium pignoribus captis et direpta supellectile male mulcatum ac pro rostris in contione paene discerptum coiecit in carcerem; eodem Nouium quaestorem, quod compellari apud se maiorem potestatem passus esset.", "st": "Jul. 17"}, {"sp": "N", "t": "Ex praetura ulteriorem sortitus Hispaniam retinentes creditores interuentu sponsorum remouit ac neque more neque iure, ante quam prouinciae or[di]narentur, profectus est: incertum metune iudicii, quod priuato parabatur, an quo maturius sociis inplorantibus subueniret; pacataque prouincia pari festinatione, non expectato successore ad triumphum simul consulatumque decessit. sed cum edictis iam comitis ratio eius haberi non posset nisi priuatus introisset urbem, et ambienti ut legibus solueretur multi contra dicerent, coactus est triumphum, ne consulatu excluderetur, dimittere.", "st": "Jul. 18"}, {"sp": "N", "t": "e duobus consulatus competitoribus, Lucio Lucceio Marcoque Bibulo, Lucceium sibi adiunxit, pactus ut is, quoniam inferior gratia esset pecuniaque polleret, nummos de suo communi nomine per centurias pronuntiaret. qua cognita re optimates, quos metus ceperat nihil non ausurum eum in summo magistratu concordi et consentiente collega, auctores Bibulo fuerunt tantundem pollicendi, ac plerique pecunias contulerunt, ne Catone quidem abnuente eam largitionem e re publica fieri. Igitur cum Bibulo consul creatur. eandem ob causam opera ab optimatibus data est, ut prouinciae futuris consulibus minimi negotii, id est siluae callesque, decernerentur. qua maxime iniuria instinctus omnibus officiis Gnaeum Pompeium adsectatus est offensum patribus, quod Mithridate rege uicto cunctantius confirmarentur acta sua; Pompeioque Marcum Crassum reconciliauit ueterem inimicum ex consulatu, quem summa discordia simul gesserant; ac societatem cum utroque iniit, ne quid ageretur in re publica, quod displicuisset ulli e tribus.", "st": "Jul. 19"}, {"sp": "N", "t": "inito honore primus omnium instituit, ut tam senatus quam populi diurna acta confierent et publicarentur. antiquum etiam rettulit morem, ut quo mense fasces non haberet, accensus ante eum iret, lictores pone sequerentur. lege autem agraria promulgata obnuntiantem collegam armis foro expulit ac postero die in senatu conquestum nec quoquam reperto, qui super tali consternatione referre aut censere aliquid auderet, qualia multa saepe in leuioribus turbis decreta erant, in eam coegit desperationem, ut, quoad potestate abiret, domo abditus nihil aliud quam per edicta obnuntiaret. Vnus ex eo tempore omnia in re publica et ad arbitrium administrauit, ut nonnulli urbanorum, cum quid per iocum testandi gratia signarent, non Caesare et Bibulo, sed Iulio et Caesare consulibus actum scriberent bis eundem praeponentes nomine atque cognomine, utque uulgo mox ferrentur hi uersus:<br>non Bibulo quiddam nuper sed Caesare factum est:<br>nam Bibulo fieri consule nil memini.<br>campum Stellatem maioribus consecratum agrumque Campanum ad subsidia rei publicae uectigalem relictum diuisit extra sortem ad uiginti milibus ciuium, quibus terni pluresue liberi essent. publicanos remissionem petentis tertia mercedum parte releuauit ac, ne in locatione nouorum uectigalium inmoderatius licerentur, propalam monuit. cetera item, quae cuique libuissent, dilargitus est contra dicente nullo ac, si conaretur quis, absterrito. Marcum Catonem interpellantem extrahi curia per lictorem ducique in carcerem iussit. Lucio Lucullo liberius resistenti tantum calumniarum metum iniecit, ut ad genua ultro sibi accideret. Cicerone in iudicio quodam deplorante temporum statum Publium Clodium inimicum eius, frustra iam pridem a patribus ad plebem transire nitentem, eodem die horaque nona transduxit. postremo in uniuersos diuersae factionis ⟨indicem …⟩ inductum praemiis, ut se de inferenda Pompeio nece sollicitatum a quibusdam profiteretur productusque pro rostris auctores ex conpacto nominaret; sed uno atque altero frustra nec sine suspicione fraudis nominatis desperans tam praecipitis consilii euentum intercepisse ueneno indicem creditur.", "st": "Jul. 20"}, {"sp": "N", "t": "Sub idem tempus Calpurniam L. Pisonis filiam successuri sibi in consulatu duxit uxorem suamque, Iuliam, Gnaeo Pompeio conlocauit repudiato priore sponso Seruilio Caepione, cuius uel praecipua opera paulo ante Bibulum inpugnauerat. ac post nouam adfinitatem Pompeium primum rogare sententiam coepit, cum Crassum soleret essetque consuetudo, ut quem ordinem interrogandi sententias consul Kal. Ianuariis instituisset, eum toto anno conseruaret.", "st": "Jul. 21"}, {"sp": "N", "t": "Socero igitur generoque suffragantibus ex omni prouinciarum copia Gallias potissimum elegit, †cuius emolumento et oportunitate idonea sit materia triumphorum. et initio quidem Galliam Cisalpinam Illyrico adiecto lege Vatinia accepit; mox per senatum Comatam quoque, ueritis patribus ne, si ipsi negassent, populus et hanc daret. quo gaudio elatus non temperauit, quin paucos post dies frequenti curia iactaret, inuitis et gementibus aduersaris adeptum se quae concupisset, proinde ex eo insultaturum omnium capitibus; ac negante quodam per contumeliam facile hoc ulli feminae fore, responderit quasi adludens: in Suria quoque regnasse Sameramin magnamque Asiae partem Amazonas tenuisse quondam.", "st": "Jul. 22"}, {"sp": "N", "t": "Functus consulatu Gaio Memmio Lucioque Domitio praetoribus de superioris anni actis referentibus cognitionem senatui detulit; nec illo suscipiente triduoque per inritas altercationes absumpto in prouinciam abiit. et statim quaestor eius in praeiudicium aliquot criminibus arreptus est. mox et ipse a Lucio Antistio tr. pl. postulatus appellato demum collegio optinuit, cum rei publicae causa abesset reus ne fieret. ad securitatem ergo posteri temporis in magno negotio habuit obligare semper annuos magistratus et e petitoribus non alios adiuuare aut ad honorem pati peruenire, quam qui sibi recepissent propugnaturos absentiam suam; cuius pacti non dubitauit a quibusdam ius iurandum atque etiam syngrapham exigere.", "st": "Jul. 23"}, {"sp": "N", "t": "sed cum Lucius Domitius consulatus candidatus palam minaretur consulem se effecturum quod praetor nequisset adempturumque ei exercitus, Crassum Pompeiumque in urbem prouinciae suae Lucam extractos conpulit, ut detrudendi Domitii causa consulatum alterum peterent, perfecitque †utrumque, ut in quinquennium sibi imperium prorogaretur. qua fiducia ad legiones, quas a re publica acceperat, alias priuato sumptu addidit, unam etiam ex Transalpinis conscriptam, uocabulo quoque Gallico—Alauda enim appellabatur—, quam disciplina cultuque Romano institutam et ornatam postea uniuersam ciuitate donauit. nec deinde ulla belli occasione, ⟨ne⟩ iniusti quidem ac periculosi abstinuit, tam foederatis quam infestis ac feris gentibus ultro lacessitis, adeo ut senatus quondam legatos ad explorandum statum Galliarum mittendos decreuerit ac nonnulli dedendum eum hostibus censuerint. sed prospere [de]cedentibus rebus et saepius et plurium quam quisquam umquam dierum supplicationes impetrauit.", "st": "Jul. 24"}, {"sp": "N", "t": "gessit autem nouem annis, quibus in imperio fuit, haec fere. Omnem Galliam, quae saltu Pyrenaeo Alpibusque et monte Cebenna, fluminibus Rheno ac Rhodano continetur patetque circuitu ad bis et tricies centum milia passuum, praeter socias ac bene meritas ciuitates in prouinciae formam redegit, eique |CCCC| in singulos annos stipendii nomine inposuit. Germanos, qui trans Rhenum incolunt, primus Romanorum ponte fabricato adgressus maximis adfecit cladibus; adgressus est et Britannos ignotos antea superatisque pecunias et obsides imperauit; per tot successus ter nec amplius aduersum casum expertus: in Britannia classe ui tempestatis prope absumpta et in Gallia ad Gergouiam legione fusa et in Germanorum finibus Titurio et Aurunculeio legatis per insidias caesis.", "st": "Jul. 25"}, {"sp": "N", "t": "Eodem temporis spatio matrem primo, deinde filiam, nec multo post nepotem amisit. inter quae, consternata Publi Clodi caede re publica, cum senatus unum consulem nominatimque Gnaeum Pompeium fieri censuisset, egit cum tribunis plebis collegam se Pompeio destinantibus, id potius ad populum ferrent, ut absenti sibi, quandoque imperii tempus expleri coepisset, petitio secundi consulatus daretur, ne ea causa maturius et inperfecto adhuc bello decederet. quod ut adeptus est, altiora iam meditans [s]et spei plenus nullum largitionis aut officiorum in quemquam genus publice priuatimque omisit. forum de manubiis incohauit, cuius area super sestertium milies constitit. munus populo epulumque pronuntiauit in filiae memoriam, quod ante eum nemo. quorum ut quam maxima expectatio esset, ea quae ad epulum pertinerent, quamuis macellaris ablocata, etiam domesticatim apparabat. gladiatores notos, sicubi infestis spectatoribus dimicarent, ui rapiendos reseruandosque mandabat. tirones neque in ludo neque per lanistas, sed in domibus per equites Romanos atque etiam per senatores armorum peritos erudiebat, precibus enitens, quod epistulis eius ostenditur, ut disciplinam singulorum susciperent ipsique dictata exercentibus darent. legionibus stipendium in perpetuum duplicauit. frumentum, quotiens copia esset, etiam sine modo mensuraque praebuit ac singula interdum mancipia e praeda uiritim dedit.", "st": "Jul. 26"}, {"sp": "N", "t": "ad retinendam autem Pompei necessitudinem ac uoluntatem Octauiam sororis suae neptem, quae Gaio Marcello nupta erat, condicionem ei detulit sibique filiam eius in matrimonium petit Fausto Sullae destinatam. omnibus uero circa eum atque etiam parte magna senatus gratuito aut leui faenore obstrictis, ex reliquo quoque ordinum genere uel inuitatos uel sponte ad se commeantis uberrimo congiario prosequebatur, libertos insuper seruulosque cuiusque, prout domino patronoue gratus qui esset. tum reorum aut obaeratorum aut prodigae iuuentutis subsidium unicum ac promptissimum erat, nisi quos grauior criminum uel inopiae luxuriaeue uis urgeret, quam ut subueniri posset a se; his plane palam bello ciuili opus esse dicebat.", "st": "Jul. 27"}, {"sp": "N", "t": "nec minore studio reges atque prouincias per terrarum orbem adliciebat, aliis captiuorum milia dono offerens, aliis citra senatus populique auctoritatem, quo uellent et quotiens uellent, auxilia submittens, superque Italiae Galliarumque et Hispaniarum, Asiae quoque et Graeciae potentissimas urbes praecipuis operibus exornans; donec, attonitis iam omnibus et quorsum illa tenderent reputantibus, Marcus Claudius Marcellus consul edicto praefatus, de summa se re publica acturum, rettulit ad senatum, ut ei succederetur ante tempus, quoniam bello confecto pax esset ac dimitti deberet uictor exercitus; et ne absentis ratio comitiis haberetur, quando nec plebi scito Pompeius postea abrogasset. acciderat autem, ut is legem de iure magistratuum ferens eo capite, quo petitione honorum absentis submouebat, ne Caesarem quidem exciperet per obliuionem, ac mox lege iam in aes incisa et in aerarium condita corrigeret errorem. nec contentus Marcellus prouincias Caesari et priuilegium eripere, rettulit etiam, ut colonis, quos rogatione Vatinia Nouum Comum deduxisset, ciuitas adimeretur, quod per ambitionem et ultra praescriptum data esset.", "st": "Jul. 28"}, {"sp": "N", "t": "Commotus his Caesar ac iudicans, quod saepe ex eo auditum ferunt, 'difficilius se principem ciuitatis a primo ordine in secundum quam ex secundo in nouissimum detrudi,' summa ope restitit, partim per intercessores tribunos, partim per Seruium Sulpicium alterum consulem. insequenti quoque anno Gaio Marcello, qui fratri patrueli suo Marco in consulatu successerat, eadem temptante collegam eius Aemilium Paulum Gaiumque Curionem uiolentissimum tribunorum ingenti mercede defensores parauit. sed cum obstinatius omnia agi uideret et designatos etiam consules e parte diuersa, senatum litteris deprecatus est, ne sibi beneficium populi adimeretur, aut ut ceteri quoque imperatores ab exercitibus discederent; confisus, ut putant, facilius se, simul atque libuisset, ueteranos conuocaturum quam Pompeium nouos milites. cum aduersariis autem pepigit, ut dimissis octo legionibus Transalpinaque Gallia duae sibi legiones et Cisalpina prouincia uel etiam una legio cum Illyrico concederetur, quoad consul fieret.", "st": "Jul. 29"}, {"sp": "N", "t": "uerum neque senatu interueniente et aduersariis negantibus ullam se de re publica facturos pactionem, transiit in citeriorem Galliam, conuentibusque peractis Rauennae substitit, bello uindicaturus si quid de tribunis plebis intercedentibus pro se grauius a senatu constitutum esset. Et praetextum quidem illi ciuilium armorum hoc fuit; causas autem alias fuisse opinantur. Gnaeus Pompeius ita dictitabat, quod neque opera consummare, quae instituerat, neque populi expectationem, quam de aduentu suo fecerat, priuatis opibus explere posset, turbare omnia ac permiscere uoluisse. alii timuisse dicunt, ne eorum, quae primo consulatu aduersus auspicia legesque et intercessiones gessisset, rationem reddere cogeretur; cum M. Cato identidem nec sine iure iurando denuntiaret delaturum se nomen eius, simul ac primum exercitum dimisisset; cumque uulgo fore praedicarent, ut si priuatus redisset, Milonis exemplo circumpositis armatis causam apud iudices diceret. quod probabilius facit Asinius Pollio, Pharsalica acie caesos profligatosque aduersarios prospicientem haec eum ad uerbum dixisse referens: 'hoc uoluerunt; tantis rebus gestis Gaius Caesar condemnatus essem, nisi ab exercitu auxilium petissem.' quidam putant captum imperii consuetudine pensitatisque suis et inimicorum uiribus usum occasione rapiendae dominationis, quam aetate prima concupisset. quod existimasse uidebatur et Cicero scribens de Officiis tertio libro semper Caesarem in ore habuisse [est in Phoenissis: εἴπερ γὰρ ἀδικεῖν χρή, τυραννίδος πέρι κάλλιστον ἀδίκημα· τὰ δ’ ἄλλα εὐσεβεῖν χρεών] Euripidis uersus, quos sic ipse conuertit:<br>nam si uiolandum est ius, regnandi gratia<br>uiolandum est: aliis rebus pietatem colas.", "st": "Jul. 30"}, {"sp": "N", "t": "Cum ergo sublatam tribunorum intercessionem ipsosque urbe cessisse nuntiatum esset, praemissis confestim clam cohortibus, ne qua suspicio moueretur, et spectaculo publico per dissimulationem interfuit et formam, qua ludum gladiatorium erat aedificaturus, considerauit et ex consuetudine conuiuio se frequenti dedit. dein post solis occasum mulis e proximo pistrino ad uehiculum iunctis occultissimum iter modico comitatu ingressus est; et cum luminibus extinctis decessisset uia, diu errabundus tandem ad lucem duce reperto per angustissimos tramites pedibus euasit. consecutusque cohortis ad Rubiconem flumen, qui prouinciae eius finis erat, paulum constitit, ac reputans quantum moliretur, conuersus ad proximos: 'etiam nunc,' inquit, 'regredi possumus; quod si ponticulum transierimus, omnia armis agenda erunt.'", "st": "Jul. 31"}, {"sp": "N", "t": "cunctanti ostentum tale factum est. quidam eximia magnitudine et forma in proximo sedens repente apparuit harundine canens; ad quem audiendum cum praeter pastores plurimi etiam ex stationibus milites concurrissent interque eos et aeneatores, rapta ab uno tuba prosiliuit ad flumen et ingenti spiritu classicum exorsus pertendit ad alteram ripam. tunc Caesar: 'eatur,' inquit, 'quo deorum ostenta et inimicorum iniquitas uocat. iacta alea est,' inquit.", "st": "Jul. 32"}, {"sp": "N", "t": "atque ita traiecto exercitu, adhibitis tribunis plebis, qui pulsi superuenerant, pro contione fidem militum flens ac ueste a pectore discissa inuocauit. existimatur etiam equestres census pollicitus singulis; quod accidit opinione falsa. nam cum in adloquendo adhortandoque saepius digitum laeuae manus ostentans adfirmaret se ad satis faciendum omnibus, per quos dignitatem suam defensurus esset, anulum quoque aequo animo detracturum sibi, extrema contio, cui facilius erat uidere contionantem quam audire, pro dicto accepit, quod uisu suspicabatur; promissumque ius anulorum cum milibus quadringenis fama distulit.", "st": "Jul. 33"}, {"sp": "N", "t": "Ordo et summa rerum, quas deinceps gessit, sic se habent. Picenum Vmbriam Etruriam occupauit et Lucio Domitio, qui per tumultum successor ei nominatus Corfinium praesidio tenebat, in dicionem redacto atque dimisso secundum Superum mare Brundisium tetendit, quo consules Pompeiusque confugerant quam primum transfretaturi. hos frustra per omnis moras exitu prohibere conatus Romam iter conuertit appellatisque de re publica patribus ualidissimas Pompei copias, quae sub tribus legatis M. Petreio et L. Afranio et M. Varrone in Hispania erant, inuasit, professus ante inter suos, 'ire se ad exercitum sine duce et inde reuersurum ad ducem sine exercitu.' et quanquam obsidione Massiliae, quae sibi in itinere portas clauserat, summaque frumentariae rei penuria retardante breui tamen omnia subegit.", "st": "Jul. 34"}, {"sp": "N", "t": "hinc urbe repetita in Macedoniam transgressus Pompeium, per quattuor paene menses maximis obsessum operibus, ad extremum Pharsalico proelio fudit et fugientem Alexandriam persecutus, ut occisum deprehendit, cum Ptolemaeo rege, a quo sibi quoque insidias tendi uidebat, bellum sane difficillimum gessit, neque loco neque tempore aequo, sed hieme anni et intra moenia copiosissimi ac sollertissimi hostis, inops ipse omnium rerum atque inparatus. regnum Aegypti uictor Cleopatrae fratrique eius minori permisit, ueritus prouinciam facere, ne quandoque uiolentiorem praesidem nacta nouarum rerum materia esset. ab Alexandria in Syriam et inde Pontum transiit urgentibus de Pharnace nuntiis, quem Mithridatis Magni filium ac tunc occasione temporum bellantem iamque multiplici successu praeferocem, intra quintum quam adfuerat diem, quattuor quibus in conspectum uenit horis, una profligauit acie; crebro commemorans Pompei felicitatem, cui praecipua militiae laus de tam inbelli genere hostium contigisset. dehinc Scipionem ac Iubam reliquias partium in Africa refouentis deuicit, Pompei liberos in Hispania.", "st": "Jul. 35"}, {"sp": "N", "t": "omnibus ciuilibus bellis nullam cladem nisi per legatos suos passus est, quorum C. Curio in Africa periit, C. Antonius in Illyrico in aduersariorum deuenit potestatem, P. Dolabella classem in eodem Illyrico, Cn. Domitius Caluinus in Ponto exercitum amiserunt. ipse prosperrime semper ac ne ancipiti quidem umquam fortuna praeterquam bis dimicauit: semel ad Dyrrachium, ubi pulsus non instante Pompeio negauit eum uincere scire, iterum in Hispania ultimo proelio, cum desperatis rebus etiam de consciscenda nece cogitauit.", "st": "Jul. 36"}, {"sp": "N", "t": "Confectis bellis quinquiens triumphauit, post deuictum Scipionem quater eodem mense, sed interiectis diebus, et rursus semel post superatos Pompei liberos. primum et excellentissimum triumphum egit Gallicum, sequentem Alexandrinum, deinde Ponticum, huic proximum Africanum, nouissimum Hispaniensem, diuerso quemque apparatu et instrumento. Gallici triumphi die Velabrum praeteruehens paene curru excussus est axe diffracto ascenditque Capitolium ad lumina quadraginta elephantis dextra sinistraque lychnuchos gestantibus. Pontico triumpho inter pompae fercula trium uerborum praetulit titulum VENI · VIDI · VICI non acta belli significantem sicut ceteris, sed celeriter confecti notam.", "st": "Jul. 37"}, {"sp": "N", "t": "ueteranis legionibus praedae nomine in pedites singulos super bina sestertia, quae initio ciuilis tumultus numerauerat, uicena quaterna milia nummum dedit. adsignauit et agros, sed non continuos, ne quis possessorum expelleretur. populo praeter frumenti denos modios ac totidem olei libras trecenos quoque nummos, quos pollicitus olim erat, uiritim diuisit et hoc amplius centenos pro mora. annuam etiam habitationem Romae usque ad bina milia nummum, in Italia non ultra quingenos sestertios remisit. adiecit epulum ac uiscerationem et post Hispaniensem uictoriam duo prandia; nam cum prius parce neque pro liberalitate sua praebitum iudicaret, quinto post die aliud largissimum praebuit.", "st": "Jul. 38"}, {"sp": "N", "t": "edidit spectacula uarii generis: munus gladiatorium, ludos etiam regionatim urbe tota et quidem per omnium linguarum histriones, item circenses athletas naumachiam. munere in foro depugnauit Furius Leptinus stirpe praetoria et Q. Calpenus senator quondam actorque causarum. pyrricham saltauerunt Asiae Bithyniaeque principum liberi. ludis Decimus Laberius eques Romanus mimum suum egit donatusque quingentis sestertiis et anulo aureo sessum in quattuordecim e scaena per orchestram transiit. circensibus spatio circi ab utraque parte producto et in gyrum euripo addito quadrigas bigasque et equos desultorios agitauerunt nobilissimi iuuenes. Troiam lusit turma duplex maiorum minorumque puerorum. uenationes editae per dies quinque ac nouissime pugna diuisa in duas acies, quingenis peditibus, elephantis uicenis, tricenis equitibus hinc et inde commissis. nam quo laxius dimicaretur, sublatae metae inque earum locum bina castra exaduersum constituta erant. athletae stadio ad tempus extructo regione Marti campi certauerunt per triduum. nauali proelio in minore Codeta defosso lacu biremes ac triremes quadriremesque Tyriae et Aegyptiae classis magno pugnatorum numero conflixerunt. ad quae omnia spectacula tantum undique confluxit hominum, ut plerique aduenae aut inter uicos aut inter uias tabernaculis positis manerent, ac saepe prae turba elisi exanimatique sint plurimi et in his duo senatores.", "st": "Jul. 39"}, {"sp": "N", "t": "Conuersus hinc ad ordinandum rei publicae statum fastos correxit iam pridem uitio pontificum per intercalandi licentiam adeo turbatos, ut neque messium feriae aestate neque uindemiarum autumno conpeterent; annumque ad cursum solis accommodauit, ut trecentorum sexaginta quinque dierum esset et intercalario mense sublato unus dies quarto quoque anno intercalaretur. quo autem magis in posterum ex Kalendis Ianuariis nouis temporum ratio congrueret, inter Nouembrem ac Decembrem mensem interiecit duos alios; fuitque is annus, quo haec constituebantur, quindecim mensium cum intercalario, qui ex consuetudine in eum annum inciderat.", "st": "Jul. 40"}, {"sp": "N", "t": "senatum suppleuit, patricios adlegit, praetorum aedilium quaestorum, minorum etiam magistratuum numerum ampliauit; nudatos opere censorio aut sententia iudicum de ambitu condemnatos restituit. comitia cum populo partitus est, ut exceptis consulatus conpetitoribus de cetero numero candidatorum pro parte dimidia quos populus uellet pronuntiarentur, pro parte altera quos ipse dedisset. et edebat per libellos circum tribum missos scriptura breui: 'Caesar dictator illi tribui. commendo uobis illum et illum, ut uestro suffragio suam dignitatem teneant.' admisit ad honores et proscriptorum liberos. iudicia ad duo genera iudicum redegit, equestris ordinis ac senatorii; tribunos aerarios, quod erat tertium, sustulit. Recensum populi nec more nec loco solito, sed uicatim per dominos insularum egit atque ex uiginti trecentisque milibus accipientium frumentum e publico ad centum quinquaginta retraxit; ac ne qui noui coetus recensionis causa moueri quandoque possent, instituit, quotannis in demortuorum locum ex iis, qui recensi non essent, subsortitio a praetore fieret.", "st": "Jul. 41"}, {"sp": "N", "t": "octoginta autem ciuium milibus in transmarinas colonias distributis, ut exhaustae quoque urbis frequentia suppeteret, sanxit, ne quis ciuis maior annis uiginti minorue †decem, qui sacramento non teneretur, plus triennio continuo Italia abesset, neu qui senatoris filius nisi contubernalis aut comes magistratus peregre proficisceretur; neue ii, qui pecuariam facerent, minus tertia parte puberum ingenuorum inter pastores haberent. omnisque medicinam Romae professos et liberalium artium doctores, quo libentius et ipsi urbem incolerent et ceteri adpeterent, ciuitate donauit. de pecuniis mutuis disiecta nouarum tabularum expectatione, quae crebro mouebatur, decreuit tandem, ut debitores creditoribus satis facerent per aestimationem possessionum, quanti quasque ante ciuile bellum comparassent, deducto summae aeris alieni, si quid usurae nomine numeratum aut perscriptum fuisset; qua condicione quarta pars fere crediti deperibat. cuncta collegia praeter antiquitus constituta distraxit. poenas facinorum auxit; et cum locupletes eo facilius scelere se obligarent, quod integris patrimoniis exulabant, parricidas, ut Cicero scribit, bonis omnibus, reliquos dimidia parte multauit.", "st": "Jul. 42"}, {"sp": "N", "t": "ius laboriosissime ac seuerissime dixit. repetundarum conuictos etiam ordine senatorio mouit. diremit nuptias praetorii uiri, qui digressam a marito post biduum statim duxerat, quamuis sine probri suspicione. peregrinarum mercium portoria instituit. lecticarum usum, item conchyliatae uestis et margaritarum nisi certis personis et aetatibus perque certos dies ademit. legem praecipue sumptuariam exercuit dispositis circa macellum custodibus, qui obsonia contra uetitum retinerent deportarentque ad se, submissis nonnumquam lictoribus atque militibus, qui, si qua custodes fefellissent, iam adposita e triclinio auferrent.", "st": "Jul. 43"}, {"sp": "N", "t": "Nam de ornanda instruendaque urbe, item de tuendo ampliandoque imperio plura ac maiora in dies destinabat: in primis Martis templum, quantum nusquam esset, extruere repleto et conplanato lacu, in quo naumachiae spectaculum ediderat, theatrumque summae magnitudinis Tarpeio monti accubans; ius ciuile ad certum modum redigere atque ex immensa diffusaque legum copia optima quaeque et necessaria in paucissimos conferre libros; bibliothecas Graecas Latinasque quas maximas posset publicare data Marco Varroni cura comparandarum ac digerendarum; siccare Pomptinas paludes; emittere Fucinum lacum; uiam munire a mari Supero per Appennini dorsum ad Tiberim usque; perfodere Isthmum; Dacos, qui se in Pontum et Thraciam effuderant, coercere; mox Parthis inferre bellum per Armeniam minorem nec nisi ante expertos adgredi proelio. Talia agentem atque meditantem mors praeuenit. de qua prius quam dicam, ea quae ad formam et habitum et cultum et mores, nec minus quae ad ciuilia et bellica eius studia pertineant, non alienum erit summatim exponere.", "st": "Jul. 44"}, {"sp": "N", "t": "Fuisse traditur excelsa statura, colore candido, teretibus membris, ore paulo pleniore, nigris uegetisque oculis, ualitudine prospera, nisi quod tempore extremo repente animo linqui atque etiam per somnum exterreri solebat. comitiali quoque morbo bis inter res agendas correptus est. circa corporis curam morosior, ut non solum tonderetur diligenter ac raderetur, sed uelleretur etiam, ut quidam exprobrauerunt, caluitii uero deformitatem iniquissime ferret saepe obtrectatorum iocis obnoxiam expertus. ideoque et deficientem capillum reuocare a uertice adsueuerat et ex omnibus decretis sibi a senatu populoque honoribus non aliud aut recepit aut usurpauit libentius quam ius laureae coronae perpetuo gestandae. Etiam cultu notabilem ferunt: usum enim lato clauo ad manus fimbriato nec umquam aliter quam ut super eum cingeretur, et quidem fluxiore cinctura; unde emanasse Sullae dictum optimates saepius admonentis, 'ut male praecinctum puerum cauerent.'", "st": "Jul. 45"}, {"sp": "N", "t": "habitauit primo in Subura modicis aedibus, post autem pontificatum maximum in Sacra uia domo publica. munditiarum lautitiarumque studiosissimum multi prodiderunt: uillam in Nemorensi a fundamentis incohatam magnoque sumptu absolutam, quia non tota ad animum ei responderat, totam diruisse, quanquam tenuem adhuc et obaeratum; in expeditionibus tessellata et sectilia pauimenta circumtulisse;", "st": "Jul. 46"}, {"sp": "N", "t": "Britanniam petisse spe margaritarum, quarum amplitudinem conferentem interdum sua manu exegisse pondus; gemmas, toreumata, signa, tabulas operis antiqui semper animosissime comparasse; seruitia rectiora politioraque inmenso pretio, et cuius ipsum etiam puderet, sic ut rationibus uetaret inferri;", "st": "Jul. 47"}, {"sp": "N", "t": "conuiuatum assidue per prouincias duobus tricliniis, uno quo sagati palliatiue, altero quo togati cum inlustrioribus prouinciarum discumberent. domesticam disciplinam in paruis ac maioribus rebus diligenter adeo seuereque rexit, ut pistorem alium quam sibi panem conuiuis subicientem compedibus uinxerit, libertum gratissimum ob adulteratam equitis Romani uxorem, quamuis nullo querente, capitali poena adfecerit.", "st": "Jul. 48"}, {"sp": "N", "t": "Pudicitiae eius famam nihil quidem praeter Nicomedis contubernium laesit, graui tamen et perenni obprobrio et ad omnium conuicia exposito. omitto Calui Licini notissimos uersus:<br>Bithynia quicquid<br>et p[r]edicator Caesaris umquam habuit.<br>praetereo actiones Dolabellae et Curionis patris, in quibus eum Dolabella 'paelicem reginae, spondam interiorem regiae lecticae,' at Curio 'stabulum Nicomedis et Bithynicum fornicem' dicunt. missa etiam facio edicta Bibuli, quibus proscripsit 'collegam suum Bithynicam reginam, eique antea regem fuisse cordi, nunc esse regnum.' quo tempore, ut Marcus Brutus refert, Octauius etiam quidam ualitudine mentis liberius dicax conuentu maximo, cum Pompeium regem appellasset, ipsum reginam salutauit. sed C. Memmius etiam ad cyathum †et ui Nicomedi stetisse obicit, cum reliquis exoletis, pleno conuiuio, accubantibus nonnullis urbicis negotiatoribus, quorum refert nomina. Cicero uero non contentus in quibusdam epistulis scripsisse a satellitibus eum in cubiculum regium eductum in aureo lecto ueste purpurea decubuisse floremque aetatis a Venere orti in Bithynia contaminatum, quondam etiam in senatu defendenti ei Nysae causam, filiae Nicomedis, beneficiaque regis in se commemoranti: 'remoue,' inquit, 'istaec, oro te, quando notum est, et quid ille tibi et quid illi tute dederis.' Gallico denique triumpho milites eius inter cetera carmina, qualia currum prosequentes ioculariter canunt, etiam illud uulgatissimum pronuntiauerunt:<br>Gallias Caesar subegit, Nicomedes Caesarem:<br>ecce Caesar nunc triumphat qui subegit Gallias,<br>Nicomedes non triumphat qui subegit Caesarem.", "st": "Jul. 49"}, {"sp": "N", "t": "pronum et sumptuosum in libidines fuisse constans opinio est, plurimasque et illustres feminas corrupisse, in quibus Postumiam Serui Sulpici[i], Lolliam Auli Gabini, Tertullam Marci Crassi, etiam Cn. Pompei Muciam. nam certe Pompeio et a Curionibus patre et filio et a multis exprobratum est, quod cuius causa post tres liberos exegisset uxorem et quem gemens Aegisthum appellare consuesset, eius postea filiam potentiae cupiditate in matrimonium recepisset. sed ante alias dilexit Marci Bruti matrem Seruiliam, cui et proximo suo consulatu sexagiens sestertium margaritam mercatus est et bello ciuili super alias donationes amplissima praedia ex auctionibus hastae minimo addixit; cum quidem plerisque uilitatem mirantibus facetissime Cicero: 'quo melius,' inquit, 'emptum sciatis, tertia deducta'; existimabatur enim Seruilia etiam filiam suam Tertiam Caesari conciliare.", "st": "Jul. 50"}, {"sp": "N", "t": "ne prouincialibus quidem matrimoniis abstinuisse uel hoc disticho apparet iactato aeque a militibus per Gallicum triumphum:<br>urbani, seruate uxores: moechum caluom adducimus.<br>aurum in Gallia effutuisti, hic sumpsisti mutuum.", "st": "Jul. 51"}, {"sp": "N", "t": "dilexit et reginas, inter quas Eunoen Mauram Bogudis uxorem, cui maritoque eius plurima et immensa tribuit, ut Naso scripsit; sed maxime Cleopatram, cum qua et conuiuia in primam lucem saepe protraxit et eadem naue thalamego paene Aethiopia tenus Aegyptum penetrauit, nisi exercitus sequi recusasset, quam denique accitam in urbem non nisi maximis honoribus praemiisque auctam remisit filiumque natum appellare nomine suo passus est. quem quidem nonnulli Graecorum similem quoque Caesari et forma et incessu tradiderunt. M. Antonius adgnitum etiam ab eo senatui adfirmauit, quae scire C. Matium et C. Oppium reliquosque Caesaris amicos; quorum Gaius Oppius, quasi plane defensione ac patrocinio res egeret, librum edidit, non esse Caesaris filium, quem Cleopatra dicat. Heluius Cinna tr. pl. plerisque confessus est habuisse se scriptam paratamque legem, quam Caesar ferre iussisset cum ipse abesset, uti uxores liberorum quaerendorum causa quas et quot uellet ducere liceret. at ne cui dubium omnino sit et impudicitiae et adulteriorum flagrasse infamia, Curio pater quadam eum oratione omnium mulierum uirum et omnium uirorum mulierem appellat.", "st": "Jul. 52"}, {"sp": "N", "t": "Vini parcissimum ne inimici quidem negauerunt. Marci Catonis est: 'unum ex omnibus Caesarem ad euertendam rem publicam sobrium accessisse.' nam circa uictum Gaius Oppius adeo indifferentem docet, ut quondam ab hospite conditum oleum pro uiridi adpositum aspernantibus ceteris solum etiam largius appetisse scribat, ne hospitem aut neglegentiae aut rusticitatis uideretur arguere.", "st": "Jul. 53"}, {"sp": "N", "t": "abstinentiam neque in imperiis neque in magistratibus praestitit. ut enim quidam monumentis suis testati sunt, in Hispania pro consule et a sociis pecunias accepit emendicatas in auxilium aeris alieni et Lusitanorum quaedam oppida, quanquam nec imperata detrectarent et aduenienti portas patefacerent, diripuit hostiliter. in Gallia fana templaque deum donis referta expilauit, urbes diruit saepius ob praedam quam ob delictum; unde factum, ut auro abundaret ternisque milibus nummum in libras promercale per Italiam prouinciasque diuenderet. in primo consulatu tria milia pondo auri furatus e Capitolio tantundem inaurati aeris reposuit. societates ac regna pretio dedit, ut qui uni Ptolemaeo prope sex milia talentorum suo Pompeique nomine abstulerit. postea uero euidentissimis rapinis ac sacrilegis et onera bellorum ciuilium et triumphorum ac munerum sustinuit impendia.", "st": "Jul. 54"}, {"sp": "N", "t": "Eloquentia militarique re aut aequauit praestantissimorum gloriam aut excessit. post accusationem Dolabellae haud dubie principibus patronis adnumeratus est. certe Cicero ad Brutum oratores enumerans negat se uidere, cui debeat Caesar cedere, aitque eum elegantem, splendidam quoque atque etiam magnificam et generosam quodam modo rationem dicendi tenere; et ad Cornelium Nepotem de eodem ita scripsit: 'quid? oratorem quem huic antepones eorum, qui nihil aliud egerunt? quis sententiis aut acutior aut crebrior? quis uerbis aut ornatior aut elegantior?' genus eloquentiae dum taxat adulescens adhuc Strabonis Caesaris secutus uidetur, cuius etiam ex oratione, quae inscribitur 'pro Sardis,' ad uerbum nonnulla transtulit in diuinationem suam. pronuntiasse autem dicitur uoce acuta, ardenti motu gestuque, non sine uenustate. orationes aliquas reliquit, inter quas temere quaedam feruntur. 'pro Quinto Metello' non immerito Augustus existimat magis ab actuaris exceptam male subsequentibus uerba dicentis, quam ab ipso editam; nam in quibusdam exemplaribus inuenio ne inscriptam quidem 'pro Metello,' sed 'quam scripsit Metello,' cum ex persona Caesaris sermo sit Metellum seque aduersus communium obtrectatorum criminationes purgantis. 'apud milites' quoque 'in Hispania' idem Augustus uix ipsius putat, quae tamen duplex fertur: una quasi priore habita proelio, altera posteriore, quo Asinius Pollio ne tempus quidem contionandi habuisse eum dicit subita hostium incursione.", "st": "Jul. 55"}, {"sp": "N", "t": "reliquit et rerum suarum commentarios Gallici ciuilisque belli Pompeiani. nam Alexandrini Africique et Hispaniensis incertus auctor est: alii Oppium putant, alii Hirtium, qui etiam Gallici belli nouissimum imperfectumque librum suppleuerit. de commentariis Caesaris Cicero in eodem Bruto sic refert: 'commentarios scripsit ualde quidem probandos: nudi sunt, recti et uenusti, omni ornatu orationis tamquam ueste detracta; sed dum uoluit alios habere parata, unde sumerent qui uellent scribere historiam, ineptis gratum fortasse fecit, qui illa uolent calamistris inurere, sanos quidem homines a scribendo deterruit.' de isdem commentariis Hirtius ita praedicat: 'adeo probantur omnium iudicio, ut praerepta, non praebita facultas scriptoribus uideatur. ⟨cuius tamen rei maior nostra quam reliquorum est admiratio; ceteri enim, quam bene atque emendate,⟩ nos etiam, quam facile atque celeriter eos perscripserit, scimus.' Pollio Asinius parum diligenter parumque integra ueritate compositos putat, cum Caesar pleraque et quae per alios erant gesta temere crediderit et quae per se, uel consulto uel etiam memoria lapsus perperam ediderit; existimatque rescripturum et correcturum fuisse. reliquit et 'de analogia' duos libros et 'Anticatones' totidem ac praeterea poema quod inscribitur 'Iter'. quorum librorum primos in transitu Alpium, cum ex citeriore Gallia conuentibus peractis ad exercitum rediret, sequentes sub tempus Mundensis proelii fecit; nouissimum, dum ab urbe in Hispaniam ulteriorem quarto et uicensimo die peruenit. epistulae quoque eius ad senatum extant, quas primum uidetur ad paginas et formam memorialis libelli conuertisse, cum antea consules et duces non nisi transuersa charta scriptas mitterent. extant et ad Ciceronem, item ad familiares domesticis de rebus, in quibus, si qua occultius perferenda erant, per notas scripsit, id est sic structo litterarum ordine, ut nullum uerbum effici posset: quae si qui inuestigare et persequi uelit, quartam elementorum litteram, id est D pro A et perinde reliquas commutet. feruntur et †aituero ab adulescentulo quaedam scripta, ut 'Laudes Herculis,' tragoedia 'Oedipus,' item 'Dicta collectanea': quos omnis libellos uetuit Augustus publicari in epistula, quam breuem admodum ac simplicem ad Pompeium Macrum, cui ordinandas bibliothecas delegauerat, misit.", "st": "Jul. 56"}, {"sp": "N", "t": "Armorum et equitandi peritissimus, laboris ultra fidem patiens erat. in agmine nonnumquam equo, saepius pedibus anteibat, capite detecto, seu sol seu imber esset; longissimas uias incredibili celeritate confecit, expeditus, meritoria raeda, centena passuum milia in singulos dies; si flumina morarentur, nando traiciens uel innixus inflatis utribus, ut persaepe nuntios de se praeuenerit.", "st": "Jul. 57"}, {"sp": "N", "t": "in obeundis expeditionibus dubium cautior an audentior, exercitum neque per insidiosa itinera duxit umquam nisi perspeculatus locorum situs, neque in Britanniam transuexit, nisi ante per se portus et nauigationem et accessum ad insulam explorasset. at idem obsessione castrorum in Germania nuntiata per stationes hostium Gallico habitu penetrauit ad suos. a Brundisio Dyrrachium inter oppositas classes hieme transmisit cessantibusque copiis, quas subsequi iusserat, cum ad accersendas frustra saepe misisset, nouissime ipse clam noctu paruulum nauigium solus obuoluto capite conscendit, neque aut quis esset ante detexit aut gubernatorem cedere aduersae tempestati passus est quam paene obrutus fluctibus.", "st": "Jul. 58"}, {"sp": "N", "t": "ne religione quidem ulla a quoquam incepto absterritus umquam uel retardatus est. cum immolanti aufugisset hostia, profectionem aduersus Scipionem et Iubam non distulit. prolapsus etiam in egressu nauis uerso ad melius omine: 'teneo te,' inquit, 'Africa.' ad eludendas autem uaticinationes, quibus felix et inuictum in ea prouincia fataliter Scipionum nomen ferebatur, despectissimum quendam ex Corneliorum genere, cui ad opprobrium uitae Saluitoni cognomen erat, in castris secum habuit.", "st": "Jul. 59"}, {"sp": "N", "t": "Proelia non tantum destinato, sed ex occasione sumebat ac saepe ab itinere statim, interdum spurcissimis tempestatibus, cum minime quis moturum putaret; nec nisi tempore extremo ad dimicandum cunctatior factus est, quo saepius uicisset, hoc minus experiendos casus opinans nihilque se tantum adquisiturum uictoria, quantum … hostem fudit, quin castris quoque exueret: ita [ut] nullum spatium perterritis dabat. ancipiti proelio equos dimittebat et in primis suum, quo maior permanendi necessitas imponeretur auxilio fugae erepto.", "st": "Jul. 60"}, {"sp": "N", "t": "utebatur autem equo insigni, pedibus prope humanis et in modum digitorum ungulis fissis, quem natum apud se, cum haruspices imperium orbis terrae significare domino pronuntiassent, magna cura aluit nec patientem sessoris alterius primus ascendit; cuius etiam instar pro aede Veneris Genetricis postea dedicauit.", "st": "Jul. 61"}, {"sp": "N", "t": "inclinatam aciem solus saepe restituit obsistens fugientibus retinensque singulos et contortis faucibus conuertens in hostem et quidem adeo plerumque trepidos, ut aquilifer[o] moranti se cuspide sit comminatus, alius in manu detinentis reliquerit signum.", "st": "Jul. 62"}, {"sp": "N", "t": "non minor illa constantia eius, maiora etiam indicia fuerint. post aciem Pharsalicam cum praemissis in Asiam copiis per angustias Hellesponti uectoria nauicula traiceret, L. Cassium partis aduersae cum decem rostratis nauibus obuium sibi neque refugit et comminus tendens, ultro ad deditionem hortatus, supplicem ad se recepit.", "st": "Jul. 63"}, {"sp": "N", "t": "Alexandriae circa oppugnationem pontis eruptione hostium subita conpulsus in scapham pluribus eodem praecipitantibus, cum desilisset in mare, nando per ducentos passus euasit ad proximam nauem, elata laeua, ne libelli quos tenebat madefierent, paludamentum mordicus trahens, ne spolio poteretur hostis.", "st": "Jul. 64"}, {"sp": "N", "t": "Militem neque a moribus neque a fortuna probabat, sed tantum a uiribus, tractabatque pari seueritate atque indulgentia. non enim ubique ac semper, sed cum hostis in proximo esset, coercebat: tum maxime exactor grauissimus disciplinae, ut neque itineris neque proelii tempus denuntiaret, sed paratum et intentum momentis omnibus quo uellet subito educeret. quod etiam sine causa plerumque faciebat, praecipue pluuiis et festis diebus. ac subinde obseruandum se admonens repente interdiu uel nocte subtrahebat, augebatque iter, ut serius subsequentis defetigaret.", "st": "Jul. 65"}, {"sp": "N", "t": "fama uero hostilium copiarum perterritos non negando minuendoue, sed insuper amplificando ementiendoque confirmabat. itaque cum expectatio aduentus Iubae terribilis esset, conuocatis ad contionem militibus: 'scitote,' inquit, 'paucissimis his diebus regem adfuturum cum decem legionibus, equitum triginta, leuis armaturae centum milibus, elephantis trecentis. proinde desinant quidam quaerere ultra aut opinari mihique, qui compertum habeo, credant; aut quidem uetustissima naue impositos quocumque uento in quascumque terras iubebo auehi.'", "st": "Jul. 66"}, {"sp": "N", "t": "Delicta neque obseruabat omnia neque pro modo exequebatur, sed desertorum ac seditiosorum et inquisitor et punitor acerrimus coniuebat in ceteris. ac nonnumquam post magnam pugnam atque uictoriam remisso officiorum munere licentiam omnem passim lasciuiendi permittebat, iactare solitus milites suos etiam unguentatos bene pugnare posse. nec milites eos pro contione, sed blandiore nomine commilitones appellabat habebatque tam cultos, ut argento et auro politis armis ornaret, simul et ad speciem et quo tenaciores eorum in proelio essent metu damni. diligebat quoque usque adeo, ut audita clade Tituriana barbam capillumque summiserit nec ante dempserit quam uindicasset.", "st": "Jul. 67"}, {"sp": "N", "t": "quibus rebus et deuotissimos sibi et fortissimos reddidit. ingresso ciuile bellum centuriones cuiusque legionis singulos equites e uiatico suo optulerunt, uniuersi milites gratuitam et sine frumento stipendioque operam, cum tenuiorum tutelam locupletiores in se contulissent. neque in tam diuturno spatio quisquam omnino desciuit, plerique capti concessam sibi sub condicione uitam, si militare aduersus eum uellent, recusarunt. famem et ceteras necessitates, non cum obsiderentur modo sed et si ipsi alios obsiderent, tanto opere tolerabant, ut Dyrrachina munitione Pompeius uiso genere panis ex herba, quo sustinebantur, 'cum feris sibi rem esse' dixerit amouerique ocius nec cuiquam ostendi iusserit, ne patientia et pertinacia hostis animi suorum frangerentur. Quanta fortitudine dimicarint, testimonio est quod aduerso semel apud Dyrrachium proelio poenam in se ultro depoposcerunt, ut consolandos eos magis imperator quam puniendos habuerit. ceteris proeliis innumeras aduersariorum copias multis partibus ipsi pauciores facile superarunt. denique una sextae legionis cohors praeposita castello quattuor Pompei legiones per aliquot horas sustinuit paene omnis confixa multitudine hostilium sagittarum, quarum centum ac triginta milia intra uallum reperta sunt. nec mirum, si quis singulorum facta respiciat, uel Cassi Scaeuae centurionis uel Gai Acili militis, ne de pluribus referam. Scaeua excusso oculo, transfixus femore et umero, centum et uiginti ictibus scuto perforato, custodiam portae commissi castelli retinuit. Acilius nauali ad Massiliam proelio iniecta in puppem hostium dextera et abscisa memorabile illud apud Graecos Cynegiri exemplum imitatus transiluit in nauem umbone obuios agens.", "st": "Jul. 68"}, {"sp": "N", "t": "Seditionem per decem annos Gallicis bellis nullam omnino mouerunt, ciuilibus aliquas, sed ut celeriter ad officium redierint, nec tam indulgentia ducis quam auctoritate. non enim cessit umquam tumultuantibus atque etiam obuiam semper iit; et nonam quidem legionem apud Placentiam, quanquam in armis adhuc Pompeius esset, totam cum ignominia missam fecit aegreque post multas et supplicis preces, nec nisi exacta de sontibus poena, restituit;", "st": "Jul. 69"}, {"sp": "N", "t": "decimanos autem Romae cum ingentibus minis summoque etiam urbis periculo missionem et praemia flagitantes, ardente tunc in Africa bello, neque adire cunctatus est, quanquam deterrentibus amicis, neque dimittere; sed una uoce, qua 'Quirites' eos pro militibus appellarat, tam facile circumegit et flexit, ut ei milites esse confestim responderint et quamuis recusantem ultro in Africam sint secuti; ac sic quoque seditiosissimum quemque et praedae et agri destinati tertia parte multauit.", "st": "Jul. 70"}, {"sp": "N", "t": "Studium et fides erga clientis ne iuueni quidem defuerunt. Masintham nobilem iuuenem, cum aduersus Hiempsalem regem tam enixe defendisset, ut Iubae regis filio in altercatione barbam inuaserit, stipendiarium quoque pronuntiatum et abstrahentibus statim eripuit occultauitque apud se diu et mox ex praetura proficiscens in Hispaniam inter officia prosequentium fascesque lictorum lectica sua auexit.", "st": "Jul. 71"}, {"sp": "N", "t": "Amicos tanta semper facilitate indulgentiaque tractauit, ut Gaio Oppio comitanti se per siluestre iter correptoque subita ualitudine deuersoriolo[co], quod unum erat, cesserit et ipse humi ac sub diuo cubuerit. iam autem rerum potens quosdam etiam infimi generis ad amplissimos honores prouexit, cum ob id culparetur, professus palam, 'si grassatorum et sicariorum ope in tuenda sua dignitate usus esset, talibus quoque se parem gratiam relaturum.'", "st": "Jul. 72"}, {"sp": "N", "t": "Simultates contra nullas tam graues excepit umquam, ut non occasione oblata libens deponeret. Gai Memmi, cuius asperrimis orationibus non minore acerbitate rescripserat, etiam suffragator mox in petitione consulatus fuit. Gaio Caluo post famosa epigrammata de reconciliatione per amicos agenti ultro ac prior scripsit. Valerium Catullum, a quo sibi uersiculis de Mamurra perpetua stigmata imposita non dissimulauerat, satis facientem eadem die adhibuit cenae hospitioque patris eius, sicut consuerat, uti perseuerauit.", "st": "Jul. 73"}, {"sp": "N", "t": "sed et in ulciscendo natura lenissimus piratas, a quibus captus est, cum in dicionem redegisset, quoniam suffixurum se cruci ante iurauerat, iugulari prius iussit, deinde suffigi; Cornelio Phagitae, cuius quondam nocturnas insidias aeger ac latens, ne perduceretur ad Sullam, uix praemio dato euaserat, numquam nocere sustinuit; Philemonem a manu seruum, qui necem suam per uenenum inimicis promiserat, non grauius quam simplici morte puniit; in Publium Clodium Pompeiae uxoris suae adulterum atque eadem de causa pollutarum caerimoniarum reum testis citatus negauit se quicquam comperisse, quamuis et mater Aurelia et soror Iulia apud eosdem iudices omnia ex fide rettulissent; interrogatusque, cur igitur repudiasset uxorem: 'quoniam,' inquit, 'meos tam suspicione quam crimine iudico carere oportere.'", "st": "Jul. 74"}, {"sp": "N", "t": "moderationem uero clementiamque cum in administratione tum in uictoria belli ciuilis admirabilem exhibuit. denuntiante Pompeio pro hostibus se habiturum qui rei publicae defuissent, ipse medios et neutrius partis suorum sibi numero futuros pronuntiauit. quibus autem ex commendatione Pompei ordines dederat, potestatem transeundi ad eum omnibus fecit. motis apud Ilerdam deditionis condicionibus, cum, assiduo inter utrasque partes usu atque commercio, Afranius et Petreius deprehensos intra castra Iulianos subita paenitentia interfecissent, admissam in se perfidiam non sustinuit imitari. acie Pharsalica proclamauit, ut ciuibus parceretur, deincepsque nemini non suorum quem uellet unum partis aduersae seruare concessit. nec ulli perisse nisi in proelio reperientur, exceptis dum taxat Afranio et Fausto et Lucio Caesare iuuene; ac ne hos quidem uoluntate ipsius interemptos putant, quorum tamen et priores post impetratam ueniam rebellauerant et Caesar libertis seruisque eius ferro et igni crudelem in modum enectis bestias quoque ad munus populi comparatas contrucidauerat. denique tempore extremo etiam quibus nondum ignouerat, cunctis in Italiam redire permisit magistratusque et imperia capere; sed et statuas Luci Sullae atque Pompei a plebe disiectas reposuit; ac si qua posthac aut cogitarentur grauius aduersus se aut dicerentur, inhibere maluit quam uindicare. itaque et detectas coniurationes conuentusque nocturnos non ultra arguit, quam ut edicto ostenderet esse sibi notas, et acerbe loquentibus satis habuit pro contione denuntiare ne perseuerarent, Aulique Caecinae criminosissimo libro et Pitholai carminibus maledicentissimis laceratam existimationem suam ciuili animo tulit.", "st": "Jul. 75"}, {"sp": "N", "t": "Praegrauant tamen cetera facta dictaque eius, ut et abusus dominatione et iure caesus existimetur. non enim honores modo nimios recepit: continuum consulatum, perpetuam dictaturam praefecturamque morum, insuper praenomen Imperatoris, cognomen Patris patriae, statuam inter reges, suggestum in orchestra; sed et ampliora etiam humano fastigio decerni sibi passus est: sedem auream in curia et pro tribunali, tensam et ferculum circensi pompa, templa, aras, simulacra iuxta deos, puluinar, flaminem, lupercos, appellationem mensis e suo nomine; ac nullos non honores ad libidinem cepit et dedit. tertium et quartum consulatum titulo tenus gessit contentus dictaturae potestate decretae cum consulatibus simul atque utroque anno binos consules substituit sibi in ternos nouissimos menses, ita ut medio tempore comitia nulla habuerit praeter tribunorum et aedilium plebis praefectosque pro praetoribus constituerit, qui apsente se res urbanas administrarent. pridie autem Kalendas Ianuarias repentina consulis morte cessantem honorem in paucas horas petenti dedit. eadem licentia spreto patrio more magistratus in pluris annos ordinauit, decem praetoris uiris consularia ornamenta tribuit, ciuitate donatos et quosdam e semibarbaris Gallorum recepit in curiam. praeterea monetae publicisque uectigalibus peculiares seruos praeposuit. trium legionum, quas Alexandreae relinquebat, curam et imperium Rufioni liberti sui filio exoleto suo demandauit.", "st": "Jul. 76"}, {"sp": "N", "t": "nec minoris inpotentiae uoces propalam edebat, ut Titus Amp[r]ius scribit: 'nihil esse rem publicam, appellationem modo sine corpore ac specie. Sullam nescisse litteras, qui dictaturam deposuerit. debere homines consideratius iam loqui secum ac pro legibus habere quae dicat.' eoque arrogantiae progressus est, ut haruspice tristia et sine corde exta quondam nuntiante 'futura' diceret 'laetiora, cum uellet; nec pro ostento ducendum, si pecudi cor defuisset.'", "st": "Jul. 77"}, {"sp": "N", "t": "Verum praecipuam et exitiabilem sibi inuidiam hinc maxime mouit. adeuntis se cum plurimis honorificentissimisque decretis uniuersos patres conscriptos sedens pro aede Veneris Genetricis excepit. quidam putant retentum a Cornelio Balbo, cum conaretur assurgere; alii, ne conatum quidem omnino, sed etiam admonentem Gaium Trebatium ut assurgeret minus familiari uultu respexisse. idque factum eius tanto intolerabilius est uisum, quod ipse triumphanti et subsellia tribunicia praeteruehenti sibi unum e collegio Pontium Aquilam non assurrexisse adeo indignatus sit, ut proclamauerit: 'repete ergo a me Aquila rem publicam tribunus!' et nec destiterit per continuos dies quicquam cuiquam nisi sub exceptione polliceri: 'si tamen per Pontium Aquilam licuerit.'", "st": "Jul. 78"}, {"sp": "N", "t": "adiecit ad tam insignem despecti senatus contumeliam multo arrogantius factum. nam cum in sacrificio Latinarum reuertente eo inter inmodicas ac nouas populi acclamationes quidam e turba statuae eius coronam lauream candida fascia praeligata inposuisset et tribuni plebis Epidius Marullus Caesetiusque Flauus coronae fasciam detrahi hominemque duci in uincula iussissent, dolens seu parum prospere motam regni mentionem siue, ut ferebat, ereptam sibi gloriam recusandi, tribunos grauiter increpitos potestate priuauit. neque ex eo infamiam affectati etiam regii nominis discutere ualuit, quanquam et plebei regem se salutanti Caesarem se, non regem esse responderit et Lupercalibus pro rostris a consule Antonio admotum saepius capiti suo diadema reppulerit atque in Capitolium Ioui Optimo Maximo miserit. quin etiam uaria fama percrebruit migraturum Alexandream uel Ilium, translatis simul opibus imperii exhaustaque Italia dilectibus et procuratione urbis amicis permissa, proximo autem senatu Lucium Cottam quindecimuirum sententiam dicturum, ut, quoniam fatalibus libris contineretur Parthos nisi a rege non posse uinci, Caesar rex appellaretur.", "st": "Jul. 79"}, {"sp": "N", "t": "quae causa coniuratis maturandi fuit destinata negotia, ne assentiri necesse esset. Consilia igitur dispersim antea habita et quae saepe bini terniue ceperant, in unum omnes contulerunt, ne populo quidem iam praesenti statu laeto, sed clam palamque detrectante dominationem atque assertores flagitante. peregrinis in senatum allectis libellus propositus est: 'Bonum factum: ne quis senatori nouo curiam monstrare uelit!' et illa uulgo canebantur:<br>Gallos Caesar in triumphum ducit, idem in curiam:<br>Galli bracas deposuerunt, latum clauum sumpserunt.<br>Quinto Maximo suffecto trimenstrique consule theatrum introeunte, cum lictor animaduerti ex more iussisset, ab uniuersis conclamatum est non esse eum consulem. post remotos Caesetium et Marullum tribunos reperta sunt proximis comitiis complura suffragia consules eos declarantium. subscripsere quidam Luci Bruti statuae: 'utinam uiueres!' item ipsius Caesaris:<br>Brutus, quia reges eiecit, consul primus factus est:<br>hic, quia consules eiecit, rex postremo factus est.<br>conspiratum est in eum a sexaginta amplius, Gaio Cassio Marcoque et Decimo Bruto principibus conspirationis. qui primum cunctati utrumne in Campo per comitia tribus ad suffragia uocantem partibus diuisis e ponte deicerent atque exceptum trucidarent, an in Sacra uia uel in aditu theatri adorirentur, postquam senatus Idibus Martiis in Pompei curiam edictus est, facile tempus et locum praetulerunt.", "st": "Jul. 80"}, {"sp": "N", "t": "Sed Caesari futura caedes euidentibus prodigiis denuntiata est. paucos ante menses, cum in colonia Capua deducti lege Iulia coloni ad extruendas uillas uetustissima sepulcra dis[s]icerent idque eo studiosius facerent, quod aliquantum uasculorum operis antiqui scrutantes reperiebant, tabula aenea in monimento, in quo dicebatur Capys conditor Capuae sepultus, inuenta est conscripta litteris uerbisque Graecis hac sententia: 'quandoque ossa Capyis detecta essent, fore ut illo prognatus manu consanguineorum necaretur magnisque mox Italiae cladibus uindicaretur.' cuius rei, ne quis fabulosam aut commenticiam putet, auctor est Cornelius Balbus, familiarissimus Caesaris. proximis diebus equorum greges, quos in traiciendo Rubiconi flumini consecrarat ac uagos et sine custode dimiserat, comperit pertinacissime pabulo abstinere ubertimque flere. et immolantem haruspex Spurinna monuit, 'caueret periculum, quod non ultra Martias Idus proferretur.' pridie autem easdem Idus auem regaliolum cum laureo ramulo Pompeianae curiae se inferentem uolucres uarii generis ex proximo nemore persecutae ibidem discerpserunt. ea uero nocte, cui inluxit dies caedis, et ipse sibi uisus est per quietem interdum supra nubes uolitare, alias cum Ioue dextram iungere; et Calpurnia uxor imaginata est conlabi fastigium domus maritumque in gremio suo confodi; ac subito cubiculi fores sponte patuerunt. Ob haec simul et ob infirmam ualitudinem diu cunctatus an se contineret et quae apud senatum proposuerat agere differret, tandem Decimo Bruto adhortante, ne frequentis ac iam dudum opperientis destitueret, quinta fere hora progressus est libellumque insidiarum indicem ab obuio quodam porrectum libellis ceteris, quos sinistra manu tenebat, quasi mox lecturus commiscuit. dein pluribus hostiis caesis, cum litare non posset, introiit curiam spreta religione Spurinnamque irridens et ut falsum arguens, quod sine ulla sua noxa Idus Martiae adessent: quanquam is uenisse quidem eas diceret, sed non praeterisse.", "st": "Jul. 81"}, {"sp": "N", "t": "assidentem conspirati specie officii circumsteterunt, ilicoque Cimber Tillius, qui primas partes susceperat, quasi aliquid rogaturus propius accessit renuentique et gestu[m] in aliud tempus differenti ab utroque umero togam adprehendit: deinde clamantem: 'ista quidem uis est!' alter e Cascis auersum uulnerat paulum infra iugulum. Caesar Cascae brachium arreptum graphio traiecit conatusque prosilire alio uulnere tardatus est; utque animaduertit undique se strictis pugionibus peti, toga caput obuoluit, simul sinistra manu sinum ad ima crura deduxit, quo honestius caderet etiam inferiore corporis parte uelata. atque ita tribus et uiginti plagis confossus est uno modo ad primum ictum gemitu sine uoce edito, etsi tradiderunt quidam Marco Bruto irruenti dixisse: καὶ σὺ τέκνον; exanimis diffugientibus cunctis aliquamdiu iacuit, donec lecticae impositum, dependente brachio, tres seruoli domum rettulerunt. nec in tot uulneribus, ut Antistius medicus existimabat, letale ullum repertum est, nisi quod secundo loco in pectore acceperat. Fuerat animus coniuratis corpus occisi in Tiberim trahere, bona publicare, acta rescindere, sed metu Marci Antoni consulis et magistri equitum Lepidi destiterunt.", "st": "Jul. 82"}, {"sp": "N", "t": "postulante ergo Lucio Pisone socero testamentum eius aperitur recitaturque in Antoni domo, quod Idibus Septembribus proximis in Lauicano suo fecerat demandaueratque uirgini Vestali maximae. Quintus Tubero tradit heredem ab eo scribi solitum ex consulatu ipsius primo usque ad initium ciuilis belli Cn. Pompeium, idque militibus pro contione recitatum. sed nouissimo testamento tres instituit heredes sororum nepotes, Gaium Octauium ex dodrante, et Lucium Pinarium et Quintum Pedium ex quadrante reliquo[s]; in ima cera Gaium Octauium etiam in familiam nomenque adoptauit; plerosque percussorum in tutoribus fili, si qui sibi nasceretur, nominauit, Decimum Brutum etiam in secundis heredibus. populo hortos circa Tiberim publice et uiritim trecenos sestertios legauit.", "st": "Jul. 83"}, {"sp": "N", "t": "Funere indicto rogus extructus est in Martio campo iuxta Iuliae tumulum et pro rostris aurata aedes ad simulacrum templi Veneris Genetricis collocata; intraque lectus eburneus auro ac purpura stratus et ad caput tropaeum cum ueste, in qua fuerat occisus. praeferentibus munera, quia suffecturus dies non uidebatur, praeceptum, ut omisso ordine, quibus quisque uellet itineribus urbis, portaret in Campum. inter ludos cantata sunt quaedam ad miserationem et inuidiam caedis eius accommodata, ex Pacuui Armorum iudicio:<br>men seruasse, ut essent qui me perderent?<br>et ex Electra Acili ad similem sententiam. laudationis loco consul Antonius per praeconem pronuntiauit senatus consultum, quo omnia simul ei diuina atque humana decreuerat, item ius iurandum, quo se cuncti pro salute unius astrinxerant; quibus perpauca a se uerba addidit. lectum pro rostris in forum magistratus et honoribus functi detulerunt. quem cum pars in Capitolini Iouis cella cremare pars in curia Pompei destinaret, repente duo quidam gladiis succincti ac bina iacula gestantes ardentibus cereis succenderunt confestimque circumstantium turba uirgulta arida et cum subselliis tribunalia, quicquid praeterea ad donum aderat, congessit. deinde tibicines et scaenici artifices uestem, quam ex triumphorum instrumento ad praesentem usum induerant, detractam sibi atque discissam iniecere flammae et ueteranorum militum legionarii arma sua, quibus exculti funus celebrabant; matronae etiam pleraeque ornamenta sua, quae gerebant, et liberorum bullas atque praetextas. In summo publico luctu exterarum gentium multitudo circulatim suo quaeque more lamentata est praecipueque Iudaei, qui etiam noctibus continuis bustum frequentarunt.", "st": "Jul. 84"}, {"sp": "N", "t": "plebs statim a funere ad domum Bruti et Cassi[i] cum facibus tetendit atque aegre repulsa obuium sibi Heluium Cinnam per errorem nominis, quasi Cornelius is esset, quem grauiter pridie contionatum de Caesare requirebat, occidit caputque eius praefixum hastae circumtulit. postea solidam columnam prope uiginti pedum lapidis Numidici in foro statuit inscripsitque PARENTI PATRIAE. apud eam longo tempore sacrificare, uota suscipere, controuersias quasdam interposito per Caesarem iure iurando distrahere perseuerauit.", "st": "Jul. 85"}, {"sp": "N", "t": "Suspicionem Caesar quibusdam suorum reliquit neque uoluisse se diutius uiuere neque curasse quod ualitudine minus prospera uteretur, ideoque et quae religiones monerent et quae renuntiarent amici neglexisse. sunt qui putent, confisum eum nouissimo illo senatus consulto ac iure iurando etiam custodias Hispanorum cum gladiis †adinspectantium se remouisse. alii e diuerso opinantur insidias undique imminentis subire semel quam cauere … solitum ferunt: non tam sua quam rei publicae interesse, uti saluus esset: se iam pridem potentiae gloriaeque abunde adeptum; rem publicam, si quid sibi eueniret, neque quietam fore et aliquanto deteriore condicione ciuilia bella subituram.", "st": "Jul. 86"}, {"sp": "N", "t": "illud plane inter omnes fere constitit, talem ei mortem paene ex sententia obtigisse. nam et quondam, cum apud Xenophontem legisset Cyrum ultima ualitudine mandasse quaedam de funere suo, aspernatus tam lentum mortis genus subitam sibi celeremque optauerat; et pridie quam occideretur, in sermone nato super cenam apud Marcum Lepidum, quisnam esset finis uitae commodissimus, repentinum inopinatumque praetulerat.", "st": "Jul. 87"}, {"sp": "N", "t": "Periit sexto et quinquagensimo aetatis anno atque in deorum numerum relatus est, non ore modo decernentium, sed et persuasione uolgi. siquidem ludis, quos primos consecrato[s] ei heres Augustus edebat, stella crinita per septem continuos dies fulsit exoriens circa undecimam horam, creditumque est animam esse Caesaris in caelum recepti; et hac de causa simulacro eius in uertice additur stella. Curiam, in qua occisus est, obstrui placuit Idusque Martias Parricidium nominari, ac ne umquam eo die senatus ageretur.", "st": "Jul. 88"}, {"sp": "N", "t": "percussorum autem fere neque triennio quisquam amplius superuixit neque sua morte defunctus est. damnati omnes alius alio casu periit, pars naufragio, pars proelio; nonnulli semet eodem illo pugione, quo Caesarem uiolauerant, interemerunt.", "st": "Jul. 89"}, {"sp": "HDR", "t": "Divus Augustus", "st": "Aug."}, {"sp": "N", "t": "Gentem Octauiam Velitris praecipuam olim fuisse multa declarant. nam et uicus celeberrima parte oppidi iam pridem Octauius uocabatur et ostendebatur ara Octauio consecrata, qui bello dux finitimo, cum forte Marti rem diuinam faceret, nuntiata repente hostis incursione semicruda exta rapta foco prosecuit atque ita proelium ingressus uictor redit. decretum etiam publicum extabat, quo cauebatur, ut in posterum quoque simili modo exta Marti redderentur reliquiaeque ad Octauios referrentur.", "st": "Aug. 1"}, {"sp": "N", "t": "ea gens a Tarquinio Prisco rege inter minores gentis adlecta in senatum, mox a Seru[il]io Tullio in patricias traducta, procedente tempore ad plebem se contulit ac rursus magno interuallo per Diuum Iulium in patriciatum redit. primus ex hac magistratum populi suffragio cepit C. Rufus. is quaestorius Cn. et C. procreauit, a quibus duplex Octauiorum familia defluxit condicione diuersa, siquidem Gnaeus et deinceps ab eo reliqui omnes functi sunt honoribus summis; at C. eiusque posteri, seu fortuna seu uoluntate, in equestri ordine constiterunt usque ad Augusti patrem. proauus Augusti secundo Punico bello stipendia in Sicilia tribunus militum fecit Aemilio Papo imperatore. auus municipalibus magisteriis contentus abundante patrimonio tranquillissime senuit. sed haec alii; ipse Augustus nihil amplius quam equestri familia ortum se scribit uetere ac locuplete, et in qua primus senator pater suus fuerit. M. Antonius libertinum ei proauum exprobrat, restionem e pago Thurino, auum argentarium. nec quicquam ultra de paternis Augusti maioribus repperi.", "st": "Aug. 2"}, {"sp": "N", "t": "C. Octauius pater a principio aetatis et re et existimatione magna fuit, ut equidem mirer hunc quoque a nonnullis argentarium atque etiam inter diuisores operasque campestres proditum; amplis enim innutritus opibus honores et adeptus est facile et egregie administrauit. ex praetura Macedoniam sortitus fugitiuos, residuam Spartaci et Catilinae manum, Thurin[g]um agrum tenentis in itinere deleuit, negotio sibi in senatu extra ordinem dato. prouinciae praefuit non minore iustitia quam fortitudine; namque Bessis ac Thracibus magno proelio fusis ita socios tractauit, ut epistulae M. Ciceronis extent, quibus Quintum fratrem eodem tempore parum secunda fama proconsulatum Asiae administrantem hortatur et monet, imitetur in promerendis sociis uicinum suum Octauium.", "st": "Aug. 3"}, {"sp": "N", "t": "decedens Macedonia, prius quam profiteri se candidatum consulatus posset, mortem obiit repentinam, superstitibus liberis Octauia maiore, quam ex Ancharia, et Octauia minore item Augusto, quos ex Atia tulerat. Atia M. Atio Balbo et Iulia, sorore C. Caesaris, genita est. Balbus, paterna stirpe Aricinus, multis in familia senatoriis imaginibus, a matre Magnum Pompeium artissimo contingebat gradu functusque honore praeturae inter uigintiuiros agrum Campanum plebi Iulia lege diuisit. uerum idem Antonius, despiciens etiam maternam Augusti originem, proauum eius Afri generis fuisse et modo unguentariam tabernam modo pistrinum Ariciae exercuisse obicit. Cassius quidem Parmensis quadam epistula non tantum ut pistoris, sed etiam ut nummulari nepotem sic taxat Augustum: 'materna tibi farina est ex crudissimo Ariciae pistrino: hanc finxit manibus collybo decoloratis Nerulonensis mensarius.'", "st": "Aug. 4"}, {"sp": "N", "t": "Natus est Augustus M. Tullio Cicerone C. Antonio conss. VIIII. Kal. Octob. paulo ante solis exortum, regione Palati ad Capita bubula, ubi nunc sacrarium habet, aliquanto post quam excessit constitutum. nam ut senatus actis continetur, cum C. Laetorius, adulescens patricii generis, in deprecanda grauiore adulterii poena praeter aetatem atque natales hoc quoque patribus conscriptis allegaret, esse possessorem ac uelut aedituum soli, quod primum Diuus Augustus nascens attigisset, peteretque donari quasi proprio suo ac peculiari deo, decretum est ut ea pars domus consecraretur.", "st": "Aug. 5"}, {"sp": "N", "t": "nutrimentorum eius ostenditur adhuc locus in auito suburbano iuxta Velitras permodicus et cellae penuariae instar, tenetque uicinitatem opinio tamquam et natus ibi sit. huc introire nisi necessario et caste religio est, concepta opinione ueteri, quasi temere adeuntibus horror quidam et metus obiciatur, sed et mox confirmata. nam cum possessor uillae nouus seu forte seu temptandi causa cubitum se eo contulisset, euenit ut post paucissimas noctis horas exturbatus inde subita ui et incerta paene semianimis cum strato simul ante fores inueniretur.", "st": "Aug. 6"}, {"sp": "N", "t": "Infanti cognomen Thurino inditum est, in memoriam maiorum originis, uel quod regione Thurina recens eo nato pater Octauius aduersus fugitiuos rem prospere gesserat. Thurinum cognominatum satis certa probatione tradiderim nactus puerilem imagunculam eius aeream ueterem ferreis et paene iam exolescentibus litteris hoc nomine inscriptam, quae dono a me principi data inter cubiculi Lares colitur. sed et a M. Antonio in epistulis per contumeliam saepe Thurinus appellatur et ipse nihil amplius quam mirari se rescribit pro obprobrio sibi prius nomen obici. postea Gai Caesaris et deinde Augusti cognomen assumpsit, alterum testamento maioris auunculi, alterum Munati Planci sententia, cum quibusdam censentibus Romulum appellari oportere quasi et ipsum conditorem urbis, praeualuisset, ut Augustus potius uocaretur, non tantum nouo sed etiam ampliore cognomine, quod loca quoque religiosa et in quibus augurato quid consecratur augusta dicantur, ab auctu uel ab auium gestu gustuue, sicut etiam Ennius docet scribens:<br>Augusto augurio postquam incluta condita Roma est.", "st": "Aug. 7"}, {"sp": "N", "t": "Quadrimus patrem amisit. duodecimum annum agens auiam Iuliam defunctam pro contione laudauit. quadriennio post uirili toga sumpta militaribus donis triumpho Caesaris Africano donatus est, quanquam expers belli propter aetatem. profectum mox auunculum in Hispanias aduersus Cn. Pompei liberos uixdum firmus a graui ualitudine per infestas hostibus uias paucissimis comitibus naufragio etiam facto subsecutus, magno opere demeruit, approbata cito etiam morum indole super itineris industriam. Caesare post receptas Hispanias expeditionem in Dacos et inde in Parthos destinante praemissus Apolloniam studiis uacauit. utque primum occisum eum heredemque se comperit, diu cunctatus an proximas legiones imploraret, id quidem consilium ut praeceps inmaturumque omisit. ceterum urbe repetita hereditatem adiit, dubitante matre, uitrico uero Marcio Philippo consulari multum dissuadente. atque ab eo tempore exercitibus comparatis primum cum M. Antonio M.que Lepido, deinde tantum cum Antonio per duodecim fere annos, nouissime per quattuor et quadraginta solus rem p. tenuit.", "st": "Aug. 8"}, {"sp": "N", "t": "Proposita uitae eius uelut summa partes singillatim neque per tempora sed per species exequar, quo distinctius demonstrari cognoscique possint. Bella ciuilia quinque gessit: Mutinense, Philippense, Perusinum, Siculum, Actiacum; e quibus primum ac nouissimum aduersus M. Antonium, secundum aduersus Brutum et Cassium, tertium aduersus L. Antonium triumuiri fratrem, quartum aduersus Sextum Pompeium Cn. f(ilium).", "st": "Aug. 9"}, {"sp": "N", "t": "omnium bellorum initium et causam hinc sumpsit: nihil conuenientius ducens quam necem auunculi uindicare tuerique acta, confestim ut Apollonia rediit, Brutum Cassiumque et ui necopinantis et, quia prouisum periculum subterfugerant, legibus adgredi reosque caedis absentis deferre statuit. ludos autem uictoriae Caesaris non audentibus facere quibus optigerat id munus, ipse edidit. et quo constantius cetera quoque exequeretur, in locum tr. pl. forte demortui candidatum se ostendit, quanquam patricius necdum senator. sed aduersante conatibus suis M. Antonio consule, quem uel praecipuum adiutorem sperauerat, ac ne publicum quidem et translatiuum ius ulla in re sibi sine pactione grauissimae mercedis impertiente, ad optimates se contulit, quibus eum inuisum sentiebat, maxime quod D. Brutum obsessum Mutinae prouincia a Caesare data et per senatum confirmata expellere armis niteretur. hortantibus itaque nonnullis percussores ei subornauit, ac fraude deprehensa periculum in uicem metuens ueteranos simul in suum ac rei p. auxilium quanta potuit largitione contraxit; iussusque comparato exercitui pro praetore praeesse et cum Hirtio ac Pansa, qui consulatum susceperant, D. Bruto opem ferre, demandatum bellum tertio mense confecit duobus proeliis. priore Antonius fugisse eum scribit ac sine paludamento equoque post biduum demum apparuisse, sequenti satis constat non modo ducis, sed etiam militis functum munere atque in media dimicatione, aquilifero legionis suae grauiter saucio, aquilam umeris subisse diuque portasse.", "st": "Aug. 10"}, {"sp": "N", "t": "hoc bello cum Hirtius in acie, Pansa paulo post ex uulnere perissent, rumor increbruit ambos opera eius occisos, ut Antonio fugato, re p. consulibus orbata solus uictores exercitus occuparet. Pansae quidem adeo suspecta mors fuit, ut Glyco medicus custoditus sit, quasi uenenum uulneri indidisset. adicit his Aquilius Niger alterum e consulibus Hirtium in pugnae tumultu ab ipso interemptum.", "st": "Aug. 11"}, {"sp": "N", "t": "sed ut cognouit Antonium post fugam a M. Lepido receptum ceterosque duces et exercitus consentire pro partibus, causam optimatium sine cunctatione deseruit, ad praetextum mutatae uoluntatis dicta factaque quorundam calumniatus, quasi alii se puerum, alii ornandum tollendumque iactassent, ne aut sibi aut ueteranis par gratia referretur. et quo magis paenitentiam prioris sectae approbaret, Nursinos grandi pecunia et quam pendere nequirent multatos extorres oppido egit, quod Mutinensi acie interemptorum ciuium tumulo publice extructo ascripserant pro libertate eos occubuisse.", "st": "Aug. 12"}, {"sp": "N", "t": "Inita cum Antonio et Lepido societate Philippense quoque bellum, quamquam inualidus atque aeger, duplici proelio transegit, quorum priore castris exutus uix ad Antoni cornu fuga euaserat. nec successum uictoriae moderatus est, sed capite Bruti Romam misso, ut statuae Caesaris subiceretur, in splendidissimum quemque captiuum non sine uerborum contumelia saeuiit; ut quidem uni suppliciter sepulturam precanti respondisse dicitur iam istam uolucrum fore potestatem; alios, patrem et filium, pro uita rogantis sortiri uel micare iussisse, ut alterutri concederetur, ac spectasse utrumque morientem, cum patre, quia se optulerat, occiso filius quoque uoluntariam occubuisset necem. quare ceteri, in his M. Fauonius ille Catonis aemulus, cum catenati producerentur, imperatore Antonio honorifice salutato, hunc foedissimo conuicio coram prosciderunt. Partitis post uictoriam officiis cum Antonius Orientem ordinandum, ipse ueteranos in Italiam reducendos et municipalibus agris collocandos recepisset, neque ueteranorum neque possessorum gratiam tenuit, alteris pelli se, alteris non pro spe meritorum tractari querentibus.", "st": "Aug. 13"}, {"sp": "N", "t": "quo tempore L. Antonium fiducia consulatus, quem gerebat, ac fraternae potentiae res nouas molientem confugere Perusiam coegit et ad deditionem fame conpulit, non tamen sine magnis suis et ante bellum et in bello discriminibus. nam cum spectaculo ludorum gregarium militem in quattuordecim ordinibus sedentem excitari per apparitorem iussisset, rumore ab obtrectatoribus dilato quasi eundem mox et discruciatum necasset, minimum afuit quin periret concursu et indignatione turbae militaris. saluti fuit, quod qui desiderabatur repente comparuit incolumis ac sine iniuria. circa Perusinum autem murum sacrificans paene interceptus est a manu gladiatorum, quae oppido eruperat.", "st": "Aug. 14"}, {"sp": "N", "t": "Perusia capta in plurimos animaduertit, orare ueniam uel excusare se conantibus una uoce occurrens 'moriendum esse'. scribunt quidam trecentos ex dediticiis electos utriusque ordinis ad aram Diuo Iulio extructam Idibus Martiis hostiarum more mactatos. extiterunt qui traderent con[s]pecto eum ad arma isse, ut occulti aduersarii et quos metus magis quam uoluntas contineret, facultate L. Antoni ducis praebita, detegerentur deuictisque is et confiscatis promissa ueteranis praemia soluerentur.", "st": "Aug. 15"}, {"sp": "N", "t": "Siculum bellum incohauit in primis, sed diu traxit intermissum saepius, modo reparandarum classium causa, quas tempestatibus duplici naufragio et quidem per aestatem amiserat, modo pace facta, flagitante populo ob interclusos commeatus famemque ingrauescentem; donec nauibus ex integro fabricatis ac uiginti seruorum milibus manumissis et ad remum datis portum Iulium apud Baias inmisso in Lucrinum et Auernum lacum mari effecit. in quo cum hieme tota copias exercuisset, Pompeium inter Mylas et Naulochum superauit, sub horam pugnae tam arto repente somno deuinctus, ut ad dandum signum ab amicis excitaretur. unde praebitam Antonio materiam putem exprobrandi: ne rectis quidem oculis eum aspicere potuisse instructam aciem, uerum supinum, caelum intuentem, stupidum cubuisse nec prius surrexisse ac militibus in conspectum uenisse quam a M. Agrippa fugatae sint hostium naues. alii dictum factumque eius criminantur, quasi classibus tempestate perditis exclamauerit etiam inuito Neptuno uictoriam se adepturum, ac die circensium proximo sollemni pompae simulacrum dei detraxerit. nec temere plura ac maiora pericula ullo alio bello adiit. traiecto in Siciliam exercitu, cum partem reliquam copiarum continenti repeteret, oppressus ex inprouiso a Demochare et Apollophane praefectis Pompei uno demum nauigio aegerrime effugit. iterum cum praeter Locros Regium pedibus iret et prospectis biremibus Pompeianis terram legentibus suas ratus descendisset ad litus, paene exceptus est. tunc etiam per deuios tramites refugientem seruus Aemili Pauli comitis eius, dolens proscriptum olim ab eo patrem Paulum et quasi occasione ultionis oblata, interficere conatus est. Post Pompei fugam collegarum alterum M. Lepidum, quem ex Africa in auxilium euocarat, superbientem uiginti legionum fiducia summasque sibi partes terrore et minis uindicantem spoliauit exercitu supplicemque concessa uita Cerceios in perpetuum relegauit.", "st": "Aug. 16"}, {"sp": "N", "t": "M. Antoni[i] societatem semper dubiam et incertam reconciliationibusque uariis male focilatam abrupit tandem, et quo magis degenerasse eum a ciuili more approbaret, testamentum, quod is Romae etiam de Cleopatra liberis inter heredes nuncupatis reliquerat, aperiundum recitandumque pro contione curauit. remisit tamen hosti iudicato necessitudines amicosque omnes atque inter alios C. Sosium et T. Domitium tunc adhuc consules. Bononiensibus quoque publice, quod in Antoniorum clientela antiquitus erant, gratiam fecit coniurandi cum tota Italia pro partibus suis. nec multo post nauali proelio apud Actium uicit in serum dimicatione protracta, ut in naue uictor pernoctauerit. ab Actio cum Samum in hiberna se recepisset, turbatus nuntiis de seditione praemia et missionem poscentium, quos ex omni numero confecta uictoria Brundisium praemiserat, repetita Italia tempestate in traiectu bis conflictatus, primo inter promunturia Peloponensi atque Aetoliae, rursus circa montes Ceraunios utrubique parte liburnicarum demersa, simul eius, in qua uehebatur, fusis armamentis et gubernaculo diffracto; nec amplius quam septem et uiginti dies, donec †ad desideria militum ordinarentur, Brundisii commoratus, Asiae Syriaeque circuitu Aegyptum petit obsessaque Alexandrea, quo Antonius cum Cleopatra confugerat, breui potitus est. et Antonium quidem seras condiciones pacis temptantem ad mortem adegit uiditque mortuum. Cleopatrae, quam seruatam triumpho magno opere cupiebat, etiam psyllos admouit, qui uenenum ac uirus exugerent, quod perisse morsu aspidis putabatur. ambobus communem sepulturae honorem tribuit ac tumulum ab ipsis incohatum perfici iussit. Antonium iuuenem, maiorem de duobus Fuluia genitis, simulacro Diui Iuli, ad quod post multas et irritas preces confugerat, abreptum interemit. item Caesarionem, quem ex Caesare patre Cleopatra concepisse praedicabat, retractum e fuga supplicio adfecit. reliquos Antoni[i] reginaeque communes liberos non secus ac necessitudine iunctos sibi et conseruauit et mox pro condicione cuiusque sustinuit ac fouit.", "st": "Aug. 17"}, {"sp": "N", "t": "per idem tempus conditorium et corpus Magni Alexandri, cum prolatum e penetrali subiecisset oculis, corona aurea imposita ac floribus aspersis ueneratus est consultusque, num et Ptolemaeum inspicere uellet, regem se uoluisse ait uidere, non mortuos. Aegyptum in prouinciae formam redactam ut feraciorem habilioremque annonae urbicae redderet, fossas omnis, in quas Nilus exaestuat, oblimatas longa uetustate militari opere detersit. quoque Actiacae uictoriae memoria celebratior et in posterum esset, urbem Nicopolim apud Actium condidit ludosque illic quinquennales constituit et ampliato uetere Apollinis templo locum castrorum, quibus fuerat usus, exornatum naualibus spoliis Neptuno ac Marti consecrauit.", "st": "Aug. 18"}, {"sp": "N", "t": "Tumultus posthac et rerum nouarum initia coniurationesque complures, prius quam inualescerent indicio detectas, compressit alias alio tempore: Lepidi iuuenis, deinde Varronis Murenae et Fanni Caepionis, mox M. Egnati, exin Plauti Rufi Lucique Pauli progeneri sui, ac praeter has L. Audasi falsarum tabularum rei ac neque aetate neque corpore integri, item Asini Epicadi ex gente Parthina ibridae, ad extremum Telephi, mulieris serui nomenculatoris. nam ne ultimae quidem sortis hominum conspiratione et periculo caruit. Audasius atque Epicadus Iuliam filiam et Agrippam nepotem ex insulis, quibus continebantur, rapere ad exercitus, Telephus quasi debita sibi fato dominatione et ipsum et senatum adgredi destinarant. quin etiam quondam iuxta cubiculum eius lixa quidam ex Illyrico exercitu, ianitoribus deceptis, noctu deprehensus est cultro uenatorio cinctus, imposne mentis an simulata dementia incertum; nihil enim exprimi quaestione potuit.", "st": "Aug. 19"}, {"sp": "N", "t": "Externa bella duo omnino per se gessit, Delmaticum adulescens adhuc et Antonio deuicto Cantabricum. Delmatico etiam uulnera excepit, una acie dextrum genu lapide ictus, altera et crus et utrumque brachium ruina pontis consauciatus. reliqua per legatos administrauit, ut tamen quibusdam Pannonicis atque Germanicis aut interueniret aut non longe abesset, Rauennam uel Mediolanium uel Aquileiam usque ab urbe progrediens.", "st": "Aug. 20"}, {"sp": "N", "t": "domuit autem partim ductu partim auspiciis suis Cantabriam, Aquitaniam, Pannoniam, Delmatiam cum Illyrico omni, item Raetiam et Vindelicos ac Salassos, gentes Inalpinas. coercuit et Dacorum incursiones tribus eorum ducibus cum magna copia caesis, Germanosque ultra Albim fluuium summouit, ex quibus Suebos et Sigambros dedentis se traduxit in Galliam atque in proximis Rheno agris conlocauit. alias item nationes male quietas ad obsequium redegit. nec ulli genti sine iustis et necessariis causis bellum intulit tantumque afuit a cupiditate quoquo modo imperium uel bellicam gloriam augendi, ut quorundam barbarorum principes in aede Martis Vltoris iurare coegerit mansuros se in fide ac pace quam peterent, a quibusdam uero nouum genus obsidum, feminas, exigere temptauerit, quod neglegere marum pignera sentiebat; et tamen potestatem semper omnibus fecit, quotiens uellent obsides recipiendi. neque aut crebrius aut perfidiosius rebellantis grauiore umquam ultus est poena, quam ut captiuos sub lege uenundaret, ne in uicina regione seruirent neue intra tricensimum annum liberarentur. qua uirtutis moderationisque fama Indos etiam ac Scythas auditu modo cognitos pellexit ad amicitiam suam populique Rom. ultro per legatos petendam. Parthi quoque et Armeniam uindicanti facile cesserunt et signa militaria, quae M. Crasso et M. Antonio ademerant, reposcenti reddiderunt obsidesque insuper optulerunt, denique pluribus quondam de regno concertantibus, non nisi ab ipso electum probauerunt.", "st": "Aug. 21"}, {"sp": "N", "t": "Ianum Quirinum semel atque iterum a condita urbe ante memoriam suam clausum in multo breuiore temporis spatio terra marique pace parta ter clusit. bis ouans ingressus est urbem, post Philippense et rursus post Siculum bellum. curulis triumphos tris egit, Delmaticum, Actiacum, Alexandrinum, continuo triduo omnes.", "st": "Aug. 22"}, {"sp": "N", "t": "Graues ignominias cladesque duas omnino nec alibi quam in Germania accepit, Lollianam et Varianam, sed Lollianam maioris infamiae quam detrimenti, Varianam paene exitiabilem tribus legionibus cum duce legatisque et auxiliis omnibus caesis. hac nuntiata excubias per urbem indixit, ne quis tumultus existeret, et praesidibus prouinciarum propagauit imperium, ut a peritis et assuetis socii continerentur. uouit et magnos ludos Ioui Optimo Maximo, si res p. in meliorem statum uertisset: quod factum Cimbrico Marsicoque bello erat. adeo denique consternatum ferunt, ut per continuos menses barba capilloque summisso caput interdum foribus illideret uociferans: 'Quintili Vare, legiones redde!' diemque cladis quotannis maestum habuerit ac lugubrem.", "st": "Aug. 23"}, {"sp": "N", "t": "In re militari et commutauit multa et instituit atque etiam ad antiquum morem nonnulla reuocauit. disciplinam seuerissime rexit. ne legatorum quidem cuiquam, nisi grauate hibernisque demum mensibus, permisit uxorem interuisere. equitem R., quod duobus filiis adulescentibus causa detrectandi sacramenti pollices amputasset, ipsum bonaque subiecit hastae; quem tamen, quod inminere emptioni publicanos uidebat, liberto suo addixit, ut relegatum in agros pro libero esse sineret. decimam legionem contumacius parentem cum ignominia totam dimisit, item alias immodeste missionem postulantes citra commoda emeritorum praemiorum exauctorauit. cohortes, si quae cessissent loco, decimatas hordeo pauit. centuriones statione deserta, itidem ut manipulares, capitali animaduersione puniit, pro cetero delictorum genere uariis ignominis adfecit, ut stare per totum diem iuberet ante praetorium, interdum tunicatos discinctosque, nonnumquam cum decempedis, uel etiam caespitem portantes.", "st": "Aug. 24"}, {"sp": "N", "t": "neque post bella ciuilia aut in contione aut per edictum ullos militum commilitones appellabat, sed milites, ac ne a filiis quidem aut priuignis suis imperio praeditis aliter appellari passus est, ambitiosius id existimans, quam aut ratio militaris aut temporum quies aut sua domusque suae maiestas postularet. libertino milite, praeterquam Romae incendiorum causa et si tumultus in grauiore annona metueretur, bis usus est: semel ad praesidium coloniarum Illyricum contingentium, iterum ad tutelam ripae Rheni fluminis; eosque, seruos adhuc uiris feminisque pecuniosioribus indictos ac sine mora manumissos, sub priore uexillo habuit, neque aut commixtos cum ingenuis aut eodem modo armatos. Dona militaria aliquanto facilius phaleras et torques, quicquid auro argentoque constaret, quam uallares ac murales coronas, quae honore praecellerent, dabat; has quam parcissime et sine ambitione ac saepe etiam caligatis tribuit. M. Agrippam in Sicilia post naualem uictoriam caeruleo uexillo donauit. solos triumphales, quamquam et socios expeditionum et participes uictoriarum suarum, numquam donis impertiendos putauit, quod ipsi quoque ius habuissent tribuendi ea quibus uellent. nihil autem minus [in]perfecto duci quam festinationem temeritatemque conuenire arbitrabatur. crebro itaque illa iactabat: σπεῦδε βραδέως·<br>ἀσφαλὴς γάρ ἐστʼ ἀμείνων ἢ θρασὺς στρατηλάτης<br>et: 'sat celeriter fieri quidquid fiat satis bene.' proelium quidem aut bellum suscipiendum omnino negabat, nisi cum maior emolumenti spes quam damni metus ostenderetur. nam minima commoda non minimo sectantis discrimine similes aiebat esse aureo hamo piscantibus, cuius abrupti damnum nulla captura pensari posset.", "st": "Aug. 25"}, {"sp": "N", "t": "Magistratus atque honores et ante tempus et quosdam noui generis perpetuosque cepit. consulatum uicesimo aetatis anno inuasit admotis hostiliter ad urbem legionibus missisque qui sibi nomine exercitus deposcerent; cum quidem cunctante senatu Cornelius centurio, princeps legationis, reiecto sagulo ostendens gladii capulum non dubitasset in curia dicere: 'hic faciet, si uos non feceritis.' secundum consulatum post nouem annos, tertium anno interiecto gessit, sequentis usque ad undecimum continuauit, multisque mox, cum deferrentur, recusatis duodecimum magno, id est septemdecim annorum, interuallo et rursus tertium decimum biennio post ultro petit, ut C. et Lucium filios amplissimo praeditus magistratu suo quemque tirocinio deduceret in forum. quinque medios consulatus a sexto ad decimum annuos gessit, ceteros aut nouem aut sex aut quattuor aut tribus mensibus, secundum uero paucissimis horis. nam die Kal. Ian. cum mane pro aede Capitolini Iouis paululum curuli sella praesedisset, honore abiit suffecto alio in locum suum. nec omnes Romae, sed quartum consulatum in Asia, quintum in insula Samo, octauum et nonum Tarracone init.", "st": "Aug. 26"}, {"sp": "N", "t": "Triumuiratum rei p. constituendae per decem annos administrauit; in quo restitit quidem aliquamdiu collegis ne qua fieret proscriptio, sed inceptam utroque acerbius exercuit. namque illis in multorum saepe personam per gratiam et preces exorabilibus solus magno opere contendit ne cui parceretur, proscripsitque etiam C. Toranium tutorem suum, eundem collegam patris sui Octaui in aedilitate. Iulius Saturninus hoc amplius tradit, cum peracta proscriptione M. Lepidus in senatu excusasset praeterita et spem clementiae in posterum fecisset, quoniam satis poenarum exactum esset, hunc e diuerso professum, ita modum se proscribendi statuisse, ut omnia sibi reliquerit libera. in cuius tamen pertinaciae paenitentiam postea T. Vinium Philopoemenem, quod patronum suum proscriptum celasse olim diceretur, equestri dignitate honorauit. in eadem hac potestate multiplici flagrauit inuidia. nam et Pinarium equitem R., cum contionante se admissa turba paganorum apud milites subscribere quaedam animaduertisset, curiosum ac speculatorem ratus coram confodi imperauit; et Tedium Afrum consulem designatum, quia factum quoddam suum maligno sermone carpsisset, tantis conterruit minis, ut is se praecipitauerit; et Quintum Gallium praetorem, in officio salutationis tabellas duplices ueste tectas tenentem, suspicatus gladium occulere, nec quicquam statim, ne aliud inueniretur, ausus inquirere, paulo post per centuriones et milites raptum e tribunali seruilem in modum torsit ac fatentem nihil iussit occidi prius oculis eius sua manu effossis; quem tamen scribit conloquio petito insidiatum sibi coniectumque a se in custodiam, deinde urbe interdicta dimissum naufragio uel latronum insidiis perisse. tribuniciam potestatem perpetuam recepit, in qua semel atque iterum per singula lustra collegam sibi cooptauit. recepit et morum legumque regimen aeque perpetuum, quo iure, quamquam sine censurae honore, censum tamen populi ter egit, primum ac tertium cum collega, medium solus.", "st": "Aug. 27"}, {"sp": "N", "t": "De reddenda re p. bis cogitauit: primum post oppressum statim Antonium, memor obiectum sibi ab eo saepius, quasi per ipsum staret ne redderetur; ac rursus taedio diuturnae ualitudinis, cum etiam magistratibus ac senatu domum accitis rationarium imperii tradidit. sed reputans et se priuatum non sine periculo fore et illam plurium arbitrio temere committi, in retinenda perseuerauit, dubium euentu meliore an uoluntate. quam uoluntatem, cum prae se identidem ferret, quodam etiam edicto his uerbis testatus est: 'ita mihi saluam ac sospitem rem p. sistere in sua sede liceat atque eius rei fructum percipere, quem peto, ut optimi status auctor dicar et moriens ut feram mecum spem, mansura in uestigio suo fundamenta rei p. quae iecero.' fecitque ipse se compotem uoti nisus omni modo, ne quem noui status paeniteret. Vrbem neque pro maiestate imperii ornatam et inundationibus incendiisque obnoxiam excoluit adeo, ut iure sit gloriatus marmoream se relinquere, quam latericiam accepisset. tutam uero, quantum prouideri humana ratione potuit, etiam in posterum praestitit.", "st": "Aug. 28"}, {"sp": "N", "t": "publica opera plurima extruxit, e quibus uel praecipua: forum cum aede Martis Vltoris, templum Apollinis in Palatio, aedem Tonantis Iouis in Capitolio. fori extruendi causa fuit hominum et iudiciorum multitudo, quae uidebatur non sufficientibus duobus etiam tertio indigere; itaque festinatius necdum perfecta Martis aede publicatum est cautumque, ut separatim in eo publica iudicia et sortitiones iudicum fierent. aedem Martis bello Philippensi pro ultione paterna suscepto uouerat; sanxit ergo, ut de bellis triumphisque hic consuleretur senatus, prouincias cum imperio petituri hinc deducerentur, quique uictores redissent, huc insignia triumphorum conferrent. templum Apollinis in ea parte Palatinae domus excitauit, quam fulmine ictam desiderari a deo haruspices pronuntiarant; addidit porticus cum bibliotheca Latina Graecaque, quo loco iam senior saepe etiam senatum habuit decuriasque iudicum recognouit. Tonanti Ioui aedem consecrauit liberatus periculo, cum expeditione Cantabrica per nocturnum iter lecticam eius fulgur praestrinxisset seruumque praelucentem exanimasset. quaedam etiam opera sub nomine alieno, nepotum scilicet et uxoris sororisque fecit, ut porticum basilicamque Gai et Luci, item porticus Liuiae et Octauiae theatrumque Marcelli. sed et ceteros principes uiros saepe hortatus est, ut pro facultate quisque monimentis uel nouis uel refectis et excultis urbem adornarent. multaque a multis tunc extructa sunt, sicut a Marcio Philippo aedes Herculis Musarum, a L. Cornificio aedes Dianae, ab Asinio Pollione atrium Libertatis, a Munatio Planco aedes Saturni, a Cornelio Balbo theatrum, a Statilio Tauro amphitheatrum, a M. uero Agrippa complura et egregia.", "st": "Aug. 29"}, {"sp": "N", "t": "Spatium urbis in regiones uicosque diuisit instituitque, ut illas annui magistratus sortito tuerentur, hos magistri e plebe cuiusque uiciniae lecti. aduersus incendia excubias nocturnas uigilesque commentus est; ad coercendas inundationes alueum Tiberis laxauit ac repurgauit completum olim ruderibus et aedificiorum prolationibus coartatum. quo autem facilius undique urbs adiretur, desumpta sibi Flaminia uia Arimino tenus munienda reliquas triumphalibus uiris ex manubiali pecunia sternendas distribuit. Aedes sacras uetustate conlapsas aut incendio absumptas refecit easque et ceteras opulentissimis donis adornauit, ut qui in cellam Capitolini Iouis sedecim milia pondo auri gemmasque ac margaritas quingenties sestertium una donatione contulerit.", "st": "Aug. 30"}, {"sp": "N", "t": "postquam uero pontificatum maximum, quem numquam uiuo Lepido auferre sustinuerat, mortuo demum suscepit, quidquid fatidicorum librorum Graeci Latinique generis nullis uel parum idoneis auctoribus uulgo ferebatur, supra duo milia contracta undique cremauit ac solos retinuit Sibyllinos, hos quoque dilectu habito; condiditque duobus forulis auratis sub Palatini Apollinis basi. annum a Diuo Iulio ordinatum, sed postea neglegentia conturbatum atque confusum, rursus ad pristinam rationem redegit; in cuius ordinatione Sextilem mensem e suo cognomine nuncupauit magis quam Septembrem quo erat natus, quod hoc sibi et primus consulatus et insignes uictoriae optigissent. sacerdotum et numerum et dignitatem sed et commoda auxit, praecipue Vesta lium uirginum. cumque in demortuae locum aliam capi oporteret ambirentque multi ne filias in sortem darent, adiurauit, si cuiusquam neptium suarum competeret aetas, oblaturum se fuisse eam. nonnulla etiam ex antiquis caerimonis paulatim abolita restituit, ut Salutis augurium, Diale flamonium, sacrum Lupercale, ludos Saeculares et Compitalicios. Lupercalibus uetuit currere inberbes, item Saecularibus ludis iuuenes utriusque sexus prohibuit ullum nocturnum spectaculum frequentare nisi cum aliquo maiore natu propinquorum. Compitales Lares ornari bis anno instituit uernis floribus et aestiuis. Proximum a dis immortalibus honorem memoriae ducum praestitit, qui imperium p. R. ex minimo maximum reddidissent. itaque et opera cuiusque manentibus titulis restituit et statuas omnium triumphali effigie in utraque fori sui porticu dedicauit, professus e[s]t edicto: commentum id se, ut ad illorum … uelut ad exemplar et ipse, dum uiueret, et insequentium aetatium principes exigerentur a ciuibus. Pompei quoque statuam contra theatri eius regiam marmoreo Iano superposuit translatam e curia, in qua C. Caesar fuerat occisus.", "st": "Aug. 31"}, {"sp": "N", "t": "Pleraque pessimi exempli in perniciem publicam aut ex consuetudine licentiaque bellorum ciuilium durauerant aut per pacem etiam extiterant. nam et grassatorum plurimi palam se ferebant succincti ferro, quasi tuendi sui causa, et rapti per agros uiatores sine discrimine liberi seruique ergastulis possessorum supprimebantur, et plurimae factiones titulo collegi noui ad nullius non facinoris societatem coibant. igitur grassaturas dispositis per oportuna loca stationibus inhibuit, ergastula recognouit, collegia praeter antiqua et legitima dissoluit. tabulas ueterum aerari debitorum, uel praecipuam calumniandi materiam, ex[c]ussit; loca in urbe publica iuris ambigui possessoribus adiudicauit; diuturnorum reorum et ex quorum sordibus nihil aliud quam uoluptas inimicis quaereretur nomina aboleuit condicione proposita, ut si quem quis repetere uellet, par periculum poenae subiret. ne quod autem maleficium negotiumue inpunitate uel mora elaberetur, triginta amplius dies, qui honoraris ludis occupabantur, actui rerum accommodauit. ad tris iudicum decurias quartam addidit ex inferiore censu, quae ducenariorum uocaretur iudicaretque de leuioribus summis. iudices a tricensimo aetatis anno adlegit, id est quinquennio maturius quam solebant. ac plerisque iudicandi munus detractantibus uix concessit, ut singulis decuriis per uices annua uacatio esset et ut solitae agi Nouembri ac Decembri mense res omitterentur.", "st": "Aug. 32"}, {"sp": "N", "t": "ipse ius dixit assidue et in noctem nonnumquam, si parum corpore ualeret, lectica pro tribunali collocata uel etiam domi cubans. dixit autem ius non diligentia modo summa sed et lenitate, siquidem manifesti parricidii reum, ne culleo insueretur, quod non nisi confessi adficiuntur hac poena, ita fertur interrogasse: 'certe patrem tuum non occidisti?' et cum de falso testamento ageretur omnesque signatores lege Cornelia tenerentur, non tantum duas tabellas, damnatoriam et absolutoriam, simul cognoscentibus dedit, sed tertiam quoque, qua ignosceretur iis, quos fraude ad signandum uel errore inductos constitisset. appellationes quotannis urbanorum quidem litigatorum praetori delegabat urbano, at prouincialium consularibus uiris, quos singulos cuiusque prouinciae negotiis praeposuisset.", "st": "Aug. 33"}, {"sp": "N", "t": "Leges retractauit et quasdam ex integro sanxit, ut sumptuariam et de adulteriis et de pudicitia, de ambitu, de maritandis ordinibus. hanc cum aliquanto seuerius quam ceteras emendasset, prae tumultu recusantium perferre non potuit nisi adempta demum lenitaue parte poenarum et uacatione trienni data auctisque praemiis. sic quoque abolitionem eius publico spectaculo pertinaciter postulante equite, accitos Germanici liberos receptosque partim ad se partim in patris gremium ostentauit, manu uultuque significans ne grauarentur imitari iuuenis exemplum. cumque etiam inmaturitate sponsarum et matrimoniorum crebra mutatione uim legis eludi sentiret, tempus sponsas habendi coartauit, diuortiis modum imposuit.", "st": "Aug. 34"}, {"sp": "N", "t": "Senatorum affluentem numerum deformi et incondita turba—erant enim super mille, et quidam indignissimi et post necem Caesaris per gratiam et praemium adlecti, quos orciuos uulgus uocabat—ad modum pristinum et splendorem redegit duabus lectionibus: prima ipsorum arbitratu, quo uir uirum legit, secunda suo et Agrippae; quo tempore existimatur lorica sub ueste munitus ferroque cinctus praesedisse decem ualentissimis senatorii ordinis amicis sellam suam circumstantibus. Cordus Cremutius scribit ne admissum quidem tunc quemquam senatorum nisi solum et praetemptato sinu. quosdam ad excusandi se uerecundiam compulit seruauitque etiam excusantibus insigne uestis et spectandi in orchestra epulandique publice ius. quo autem lecti probatique et religiosius et minore molestia senatoria munera fungerentur, sanxit, ut prius quam consideret quisque ture ac mero supplicaret apud aram eius dei, in cuius templo coiretur, et ne plus quam bis in mense legitimus senatus ageretur, Kalendis et Idibus, neue Septembri Octobriue mense ullos adesse alios necesse esset quam sorte ductos, per quorum numerum decreta confici possent; sibique instituit consilia sortiri semenstria, cum quibus de negotiis ad frequentem senatum referendis ante tractaret. sententias de maiore negotio non more atque ordine sed prout libuisset perrogabat, ut perinde quisque animum intenderet ac si censendum magis quam adsentiendum esset.", "st": "Aug. 35"}, {"sp": "N", "t": "Auctor et aliarum rerum fuit, in quis: ne acta senatus publicarentur, ne magistratus deposito honore statim in prouincias mitterentur, ut proconsulibus ad mulos et tabernacula, quae publice locari solebant, certa pecunia constitueretur, ut cura aerari a quaestoribus urbanis ad praetorios praetoresue transiret, ut centumuiralem hastam quam quaesturam functi consuerant cogere decemuiri cogerent.", "st": "Aug. 36"}, {"sp": "N", "t": "quoque plures partem administrandae rei p. caperent, noua officia excogitauit: curam operum publicorum, uiarum, aquarum, aluei Tiberis, frumenti populo diuidundi, praefecturam urbis, triumuiratum legendi senatus et alterum recognoscendi turmas equitum, quotiensque opus esset. censores creari desitos longo interuallo creauit. numerum praetorum auxit. exegit etiam, ut quotiens consulatus sibi daretur, binos pro singulis collegas haberet, nec optinuit, reclamantibus cunctis satis maiestatem eius imminui, quod honorem eum non solus sed cum altero gereret.", "st": "Aug. 37"}, {"sp": "N", "t": "nec parcior in bellica uirtute honoranda, super triginta ducibus iustos triumphos et aliquanto pluribus triumphalia ornamenta decernenda curauit. Liberis senatorum, quo celerius rei p. assuescerent, protinus uirili toga latum clauum induere et curiae interesse permisit militiamque auspicantibus non tribunatum modo legionum, sed et praefecturas alarum dedit; ac ne qui expers castrorum esset, binos plerumque laticlauios praeposuit singulis alis. Equitum turmas frequenter recognouit, post longam intercapedinem reducto more trauectionis. sed neque detrahi quemquam in trauehendo ab accusatore passus est, quod fieri solebat, et senio uel aliqua corporis labe insignibus permisit, praemisso in ordine equo, ad respondendum quotiens citarentur pedibus uenire; mox reddendi equi gratiam fecit eis, qui maiores annorum quinque et triginta retinere eum nollent;", "st": "Aug. 38"}, {"sp": "N", "t": "impetratisque a senatu decem adiutoribus unum quemque equitum rationem uitae reddere coegit atque in exprobratis alios poena, alios ignominia notauit, plures admonitione, sed uaria. lenissimum genus admonitionis fuit traditio coram pugillarium, quos taciti et ibidem statim legerent; notauitque aliquos, quod pecunias leuioribus usuris mutuati grauiore faenore collocassent.", "st": "Aug. 39"}, {"sp": "N", "t": "ac comitiis tribuniciis si deessent candidati senatores, ex equitibus R. creauit, ita ut potestate transacta in utro uellent ordine manerent. cum autem plerique equitum attrito bellis ciuilibus patrimonio spectare ludos e quattuordecim non auderent metu poenae theatralis, pronuntiauit non teneri ea, quibus ipsis parentibusue equester census umquam fuisset. Populi recensum uicatim egit, ac ne plebs frumentationum causa frequentius ab negotiis auocaretur, ter in annum quaternum mensium tesseras dare destinauit; sed desideranti consuetudinem ueterem concessit rursus, ut sui cuiusque mensis acciperet. comitiorum quoque pristinum ius reduxit ac multiplici poena coercito ambitu, Fabianis et Scaptiensibus tribulibus suis die comitiorum, ne quid a quoquam candidato desiderarent, singula milia nummum a se diuidebat. Magni praeterea existimans sincerum atque ab omni colluuione peregrini ac seruilis sanguinis incorruptum seruare populum, et ciuitates Romanas parcissime dedit et manumittendi modum terminauit. Tiberio pro cliente Graeco petenti rescripsit, non aliter se daturum, quam si praesens sibi persuasisset, quam iustas petendi causas haberet; et Liuiae pro quodam tributario Gallo roganti ciuitatem negauit, immunitatem optulit affirmans facilius se passurum fisco detrahi aliquid, quam ciuitatis Romanae uulgari honorem. seruos non contentus multis difficultatibus a libertate et multo pluribus a libertate iusta remouisse, cum et de numero et de condicione ac differentia eorum, qui manumitterentur, curiose cauisset, hoc quoque adiecit, ne uinctus umquam tortusue quis ullo libertatis genere ciuitatem adipisceretur. Etiam habitum uestitumque pristinum reducere studuit, ac uisa quondam pro contione pullatorum turba indignabundus et clamitans: 'en<br>Romanos, rerum dominos, gentemque togatam!'<br>negotium aedilibus dedit, ne quem posthac paterentur in foro circaue nisi positis lacernis togatum consistere.", "st": "Aug. 40"}, {"sp": "N", "t": "Liberalitatem omnibus ordinibus per occasiones frequenter exhibuit. nam et inuecta urbi Alexandrino triumpho regia gaza tantam copiam nummariae rei effecit, ut faenore deminuto plurimum agrorum pretiis accesserit, et postea, quotiens ex damnatorum bonis pecunia superflueret, usum eius gratuitum iis, qui cauere in duplum possent, ad certum tempus indulsit. senatorum censum ampliauit ac pro octingentorum milium summa duodecies sestertium taxauit suppleuitque non habentibus. congiaria populo frequenter dedit, sed diuersae fere summae: modo quadringenos, modo trecenos, nonnumquam ducenos quinquagenosque nummos; ac ne minores quidem pueros praeteriit, quamuis non nisi ab undecimo aetatis anno accipere consuessent. frumentum quoque in annonae difficultatibus saepe leuissimo, interdum nullo pretio uiritim admensus est tesserasque nummarias duplicauit.", "st": "Aug. 41"}, {"sp": "N", "t": "sed ut salubrem magis quam ambitiosum principem scires, querentem de inopia et caritate uini populum seuerissima coercuit uoce: satis prouisum a genero suo Agrippa perductis pluribus aquis, ne homines sitirent. eidem populo promissum quidem congiarium reposcenti bonae se fidei esse respondit; non promissum autem flagitanti turpitudinem et impudentiam edicto exprobrauit affirmauitque non daturum se quamuis dare destinaret. nec minore grauitate atque constantia, cum proposito congiario multos manumissos insertosque ciuium numero comperisset, negauit accepturos quibus promissum non esset, ceterisque minus quam promiserat dedit, ut destinata summa sufficeret. magna uero quondam sterilitate ac difficili remedio cum uenalicias et lanistarum familias peregrinosque omnes exceptis medicis et praeceptoribus partimque seruitiorum urbe expulisset, ut tandem annona conualuit, impetum se cepisse scribit frumentationes publicas in perpetuum abolendi, quod earum fiducia cultura agrorum cessaret: neque tamen perseuerasse, quia certum haberet posse per ambitionem quandoque restitui. atque ita postha[n]c rem temperauit, ut non minorem aratorum ac negotiantium quam populi rationem deduceret.", "st": "Aug. 42"}, {"sp": "N", "t": "Spectaculorum et assiduitate et uarietate et magnificentia omnes antecessit. fecisse se ludos ait suo nomine quater, pro aliis magistratibus, qui aut abessent aut non sufficerent, ter et uicies. fecitque nonnumquam etiam uicatim ac pluribus scaenis per omnium linguarum histriones … non in foro modo, nec in amphitheatro, sed et in circo et in Saeptis, et aliquando nihil praeter uenationem edidit; athletas quoque extructis in campo Martio sedilibus ligneis; item nauale proelium circa Tiberim cauato solo, in quo nunc Caesarum nemus est. quibus diebus custodes in urbe disposuit, ne raritate remanentium grassatoribus obnoxia esset. in circo aurigas cursoresque et confectores ferarum, et nonnumquam ex nobilissima iuuentute, produxit. sed et Troiae lusum edidit frequentissime maiorum minorumque puerorum, prisci decorique moris existimans clarae stirpis indolem sic notescere. in hoc ludicro Nonium Asprenatem lapsu debilitatum aureo torque donauit passusque est ipsum posterosque Torquati ferre cognomen. mox finem fecit talia edendi Asinio Pollione oratore grauiter inuidioseque in curia questo Aesernini nepotis sui casum, qui et ipse crus fregerat. Ad scaenicas quoque et gladiatorias operas et equitibus Romanis aliquando usus est, uerum prius quam senatus consulto interdiceretur. postea nihil sane praeterquam adulescentulum Lycium honeste natum exhibuit, tantum ut ostenderet, quod erat bipedali minor, librarum septemdecim ac uocis immensae. quodam autem muneris die Parthorum obsides tunc primum missos per mediam harenam ad spectaculum induxit superque se subsellio secundo collocauit. solebat etiam citra spectaculorum dies, si quando quid inuisitatum dignumque cognitu aduectum esset, id extra ordinem quolibet loco publicare, ut rhinocerotem apud Saepta, tigrim in scaena, anguem quinquaginta cubitorum pro comitio. Accidit uotiuis circensibus, ut correptus ualitudine lectica cubans tensas deduceret; rursus commissione ludorum, quibus theatrum Marcelli dedicabat, euenit ut laxatis sellae curulis compagibus caderet supinus. nepotum quoque suorum munere cum consternatum ruinae metu populum retinere et confirmare nullo modo posset, transiit e loco suo atque in ea parte consedit, quae suspecta maxime erat.", "st": "Aug. 43"}, {"sp": "N", "t": "Spectandi confusissimum ac solutissimum morem correxit ordinauitque motus iniuria senatoris, quem Puteolis per celeberrimos ludos consessu frequenti nemo receperat. facto igitur decreto patrum ut, quotiens quid spectaculi usquam publice ederetur, primus subselliorum ordo uacaret senatoribus, Romae legatos liberarum sociarumque gentium uetuit in orchestra sedere, cum quosdam etiam libertini generis mitti deprendisset. militem secreuit a populo. maritis e plebe proprios ordines assignauit, praetextatis cuneum suum, et proximum paedagogis, sanxitque ne quis pullatorum media cauea sederet. feminis ne gladiatores quidem, quos promiscue spectari sollemne olim erat, nisi ex superiore loco spectare concessit. solis uirginibus Vestalibus locum in theatro separatim et contra praetoris tribunal dedit. athletarum uero spectaculo muliebre secus omne adeo summouit, ut pontificalibus ludis pugilum par postulatum distulerit in insequentis diei matutinum tempus edixeritque mulieres ante horam quintam uenire in theatrum non placere.", "st": "Aug. 44"}, {"sp": "N", "t": "ipse circenses ex amicorum fere libertorumque cenaculis spectabat, interdum ex puluinari et quidem cum coniuge ac liberis sedens. spectaculo plurimas horas, aliquando totos dies aberat, petita uenia commendatisque qui suam uicem praesidendo fungerentur. uerum quotiens adesset, nihil praeterea agebat, seu uitandi rumoris causa, quo patrem Caesarem uulgo reprehensum commemorabat, quod inter spectandum epistulis libellisque legendis aut rescribendis uacaret, seu studio spectandi ac uoluptate, qua teneri se neque dissimulauit umquam et saepe ingenue professus est. itaque corollaria et praemia in alienis quoque muneribus ac ludis et crebra et grandia de suo offerebat nullique Graeco certamini interfuit, quo non pro merito quemque certantium honorarit. spectauit autem studiosissime pugiles et maxime Latinos, non legitimos atque ordinarios modo, quos etiam committere cum Graecis solebat, sed et cateruarios oppidanos inter angustias uicorum pugnantis temere ac sine arte. uniuersum denique genus operas aliquas publico spectaculo praebentium etiam cura sua dignatus est: athletis et conseruauit priuilegia et ampliauit, gladiatores sine missione edi prohibuit, coercitionem in histriones magistratibus omni tempore et loco lege uetere permissam ademit praeterquam ludis et scaena. nec tamen eo minus aut xysticorum certationes aut gladiatorum pugnas seuerissime semper exegit. nam histrionum licentiam adeo compescuit, ut Stephanionem togatarium, cui in puerilem habitum circumtonsam matronam ministrasse compererat, per trina theatra uirgis caesum relegauerit, Hylan pantomimum querente praetore in atrio domus suae nemine excluso flagellis uerberarit et Pyladen urbe atque Italia summouerit, quod spectatorem, a quo exibilabatur, demonstrasset digito conspicuumque fecisset.", "st": "Aug. 45"}, {"sp": "N", "t": "Ad hunc modum urbe urbanisque rebus administratis Italiam duodetriginta coloniarum numero deductarum a se frequentauit operibusque ac uectigalibus publicis plurifariam instruxit, etiam iure ac dignatione urbi quodam modo pro parte aliqua adaequauit excogitato genere suffragiorum, quae de magistratibus urbicis decuriones colonici in sua quisque colonia ferrent et sub die comitiorum obsignata Romam mitterent. ac necubi aut honestorum deficeret copia aut multitudinis suboles, equestrem militiam petentis etiam ex commendatione publica cuiusque oppidi ordinabat, at iis, qui e plebe regiones sibi reuisenti filios filiasue approbarent, singula nummorum milia pro singulis diuidebat.", "st": "Aug. 46"}, {"sp": "N", "t": "Prouincias ualidiores et quas annuis magistratuum imperiis regi nec facile nec tutum erat, ipse suscepit, ceteras proconsulibus sortito permisit; et tamen nonnullas commutauit interdum atque ex utroque genere plerasque saepius adiit. urbium quasdam, foederatas sed ad exitium licentia praecipites, libertate priuauit, alias aut aere alieno laborantis leuauit aut terrae motu subuersas denuo condidit aut merita erga populum R. adlegantes Latinitate uel ciuitate donauit. nec est, ut opinor, prouincia, excepta dum taxat Africa et Sardinia, quam non adierit. in has fugato Sex. Pompeio traicere ex Sicilia apparantem continuae et immodicae tempestates inhibuerunt nec mox occasio aut causa traiciendi fuit.", "st": "Aug. 47"}, {"sp": "N", "t": "Regnorum quibus belli iure potitus est, praeter pauca, aut isdem quibus ademerat reddidit aut alienigenis contribuit. reges socios etiam inter semet ipsos necessitudinibus mutuis iunxit, promptissimus affinitatis cuiusque atque amicitiae conciliator et fautor; nec aliter uniuersos quam membra partisque imperii curae habuit, rectorem quoque solitus apponere aetate paruis aut mente lapsis, donec adolescerent aut resipiscerent; ac plurimorum liberos et educauit simul cum suis et instituit.", "st": "Aug. 48"}, {"sp": "N", "t": "Ex militaribus copiis legiones et auxilia prouinciatim distribuit, classem Miseni et alteram Rauennae ad tutelam Superi et Inferi maris conlocauit, ceterum numerum partim in urbis partim in sui custodiam adlegit dimissa Calagurritanorum manu, quam usque ad deuictum Antonium, item Germanorum, quam usque ad cladem Varianam inter armigeros circa se habuerat. neque tamen umquam plures quam tres cohortes in urbe esse passus est easque sine castris, reliquas in hiberna et aestiua circa finitima oppida dimittere assuerat. quidquid autem ubique militum esset, ad certam stipendiorum praemiorumque formulam adstrinxit definitis pro gradu cuiusque et temporibus militiae et commodis missionum, ne aut aetate aut inopia post missionem sollicitari ad res nouas possent. utque perpetuo ac sine difficultate sumptus ad tuendos eos prosequendosque suppeteret, aerarium militare cum uectigalibus nouis constituit. Et quo celerius ac sub manum adnuntiari cognoscique posset, quid in prouincia quaque gereretur, iuuenes primo modicis interuallis per militaris uias, dehinc uehicula disposuit. commodius id uisum est, ut qui a loco idem perferunt litteras, interrogari quoque, si quid res exigant, possint.", "st": "Aug. 49"}, {"sp": "N", "t": "in diplomatibus libellisque et epistulis signandis initio sphinge usus est, mox imagine Magni Alexandri, nouissime sua, Dioscuridis manu scalpta, qua signare insecuti quoque principes perseuerarunt. ad epistulas omnis horarum quoque momenta nec diei modo sed et noctis, quibus datae significarentur, addebat.", "st": "Aug. 50"}, {"sp": "N", "t": "Clementiae ciuilitatisque eius multa et magna documenta sunt. ne enumerem, quot et quos diuersarum partium uenia et incolumitate donatos principem etiam in ciuitate locum tenere passus sit: Iunium Nouatum et Cassium Patauinum e plebe homines alterum pecunia, alterum leui exilio punire satis habuit, cum ille Agrippae iuuenis nomine asperrimam de se epistulam in uulgus edidisset, hic conuiuio pleno proclamasset neque uotum sibi neque animum deesse confodiendi eum. quadam uero cognitione, cum Aemilio Aeliano Cordubensi inter cetera crimina uel maxime obiceretur quod male opinari de Caesare soleret, conuersus ad accusatorem commotoque similis: 'uelim,' inquit, 'hoc mihi probes; faciam sciat Aelianus et me linguam habere, plura enim de eo loquar'; nec quicquam ultra aut statim aut postea inquisiit. Tiberio quoque de eadem re, sed uiolentius apud se per epistulam conquerenti ita rescripsit: 'aetati tuae, mi Tiberi, noli in hac re indulgere et nimium indignari quemquam esse, qui de me male loquatur; satis est enim, si hoc habemus ne quis nobis male facere possit.'", "st": "Aug. 51"}, {"sp": "N", "t": "Templa, quamuis sciret etiam proconsulibus decerni solere, in nulla tamen prouincia nisi communi suo Romaeque nomine recepit. nam in urbe quidem pertinacissime abstinuit hoc honore; atque etiam argenteas statuas olim sibi positas conflauit omnis exque iis aureas cortinas Apollini Palatino dedicauit. Dictaturam magna ui offerente populo genu nixus deiecta ab umeris toga nudo pectore deprecatus est.", "st": "Aug. 52"}, {"sp": "N", "t": "domini appellationem ut maledictum et obprobrium semper exhorruit. cum spectante eo ludos pronuntiatum esset in mimo:<br>o dominum aequum et bonum!<br>et uniuersi quasi de ipso dictum exultantes comprobassent, et statim manu uultuque indecoras adulationes repressit et insequenti die grauissimo corripuit edicto; dominumque se posthac appellari ne a liberis quidem aut nepotibus suis uel serio uel ioco passus est atque eius modi blanditias etiam inter ipsos prohibuit. non temere urbe oppidoue ullo egressus aut quoquam ingressus est nisi uespera aut noctu, ne quem officii causa inquietaret. in consulatu pedibus fere, extra consulatum saepe adoperta sella per publicum incessit. promiscuis salutationibus admittebat et plebem, tanta comitate adeuntium desideria excipiens, ut quendam ioco corripuerit, quod sic sibi libellum porrigere dubitaret, 'quasi elephanto stipem'. die senatus numquam patres nisi in curia salutauit et quidem sedentis ac nominatim singulos nullo submonente; etiam discedens eodem modo sedentibus ualere dicebat. officia cum multis mutuo exercuit, nec prius dies cuiusque sollemnes frequentare desiit, quam grandior iam natu et in turba quondam sponsaliorum die uexatus. Gallum Cerrinium senatorem minus sibi familiarem, sed captum repente oculis et ob ⟨id⟩ inedia[m] mori destinantem praesens consolando reuocauit ad uitam.", "st": "Aug. 53"}, {"sp": "N", "t": "In senatu uerba facienti dictum est: 'non intellexi,' et ab alio: 'contra dicerem tibi, si locum haberem.' interdum ob immodicas disceptantium altercationes e curia per iram se proripienti quidam ingesserunt licere oportere senatoribus de re p. loqui. Antistius Labeo senatus lectione, cum uir uirum legeret, M. Lepidum hostem olim eius et tunc exulantem legit interrogatusque ab eo an essent alii digniores, suum quemque iudicium habere respondit. nec ideo libertas aut contumacia fraudi cuiquam fuit.", "st": "Aug. 54"}, {"sp": "N", "t": "etiam sparsos de se in curia famosos libellos nec expauit et magna cura redarguit ac ne requisitis quidem auctoribus id modo censuit, cognoscendum posthac de iis, qui libellos aut carmina ad infamiam cuiuspiam sub alieno nomine edant.", "st": "Aug. 55"}, {"sp": "N", "t": "Iocis quoque quorundam inuidiosis aut petulantibus lacessitus contra dixit edicto. et tamen ne de inhibenda testamentorum licentia quicquam constitueretur intercessit. quotiens magistratuum comitiis interesset, tribus cum candidatis suis circuibat supplicabatque more sollemni. ferebat et ipse suffragium in tribu[s], ut unus e populo. testem se in iudiciis et interrogari et refelli aequissimo animo patiebatur. forum angustius fecit non ausus extorquere possessoribus proximas domos. numquam filios suos populo commendauit ut non adiceret: 'si merebuntur.' eisdem praetextatis adhuc assurrectum ab uniuersis in theatro et a stantibus plausum grauissime questus est. amicos ita magnos et potentes in ciuitate esse uoluit, ut tamen pari iure essent quo ceteri legibusque iudiciariis aeque tenerentur. cum Asprenas Nonius artius ei iunctus causam ueneficii accusante Cassio Seuero diceret, consuluit senatum, quid officii sui putaret; cunctari enim se, ne si superesset, eripere[t] legibus reum, sin deesset, destituere ac praedamnare amicum existimaretur; et consentientibus uniuersis sedit in subselliis per aliquot horas, uerum tacitus et ne laudatione quidem iudiciali data. affuit et clientibus, sicut Scutario cuidam euocato quondam suo, qui postulabatur iniuriarum. unum omnino e reorum numero ac ne eum quidem nisi precibus eripuit, exorato coram iudicibus accusatore, Castricium, per quem de coniuratione Murenae cognouerat.", "st": "Aug. 56"}, {"sp": "N", "t": "Pro quibus meritis quanto opere dilectus sit, facile est aestimare. omitto senatus consulta, quia possunt uideri uel necessitate expressa uel uerecundia. equites R. natalem eius sponte atque consensu biduo semper celebrarunt. omnes ordines in lacum Curti quotannis ex uoto pro salute eius stipem iaciebant, item Kal. Ian. stren[u]am in Capitolio etiam absenti, ex qua summa pretiosissima deorum simulacra mercatus uicatim dedicabat, ut Apollinem Sandaliarium et Iouem Tragoedum aliaque. in restitutionem Palatinae domus incendio absumptae ueterani, decuriae, tribus atque etiam singillatim e cetero genere hominum libentes ac pro facultate quisque pecunias contulerunt, delibante tantum modo eo summarum aceruos neque ex quoquam plus denario auferente. reuertentem ex prouincia non solum faustis ominibus, sed et modulatis carminibus prosequebantur. obseruatum etiam est, ne quotiens introiret urbem, supplicium de quoquam sumeretur.", "st": "Aug. 57"}, {"sp": "N", "t": "Patris patriae cognomen uniuersi repentino maximoque consensu detulerunt ei: prima plebs legatione Antium missa; dein, quia non recipiebat, ineunti Romae spectacula frequens et laureata; mox in curia senatus, neque decreto neque adclamatione, sed per Valerium Messalam is mandantibus cunctis: 'quod bonum,' inquit, 'faustumque sit tibi domuique tuae, Caesar Auguste! sic enim nos perpetuam felicitatem rei p. et laeta huic precari existimamus: senatus te consentiens cum populo R. consalutat patriae patrem.' cui lacrimans respondit Augustus his uerbis—ipsa enim, sicut Messalae, posui—: 'compos factus uotorum meorum, p. c., quid habeo aliud deos immortales precari, quam ut hunc consensum uestrum ad ultimum finem uitae mihi perferre liceat?'", "st": "Aug. 58"}, {"sp": "N", "t": "Medico Antonio Musae, cuius opera ex ancipiti morbo conualuerat, statuam aere conlato iuxta signum Aesculapi statuerunt. nonnulli patrum familiarum testamento cauerunt, ut ab heredibus suis praelato titulo uictumae in Capitolium ducerentur uotumque pro se solueretur, quod superstitem Augustum reliquissent. quaedam Italiae ciuitates diem, quo primum ad se uenisset, initium anni fecerunt. prouinciarum pleraeque super templa et aras ludos quoque quinquennales paene oppidatim constituerunt.", "st": "Aug. 59"}, {"sp": "N", "t": "reges amici atque socii et singuli in suo quisque regno Caesareas urbes condiderunt et cuncti simul aedem Iouis Olympii Athenis antiquitus incohatam perficere communi sumptu destinauerunt Genioque eius dedicare; ac saepe regnis relictis non Romae modo sed et prouincias peragranti cotidiana officia togati ac sine regio insigni more clientium praestiterunt.", "st": "Aug. 60"}, {"sp": "N", "t": "Quoniam qualis in imperis ac magistratibus regendaque per terrarum orbem pace belloque re p. fuerit, exposui, referam nunc interiorem ac familiarem eius uitam quibusque moribus atque fortuna domi et inter suos egerit a iuuenta usque ad supremum uitae diem. Matrem amisit in primo consulatu, sororem Octauiam quinquagensimum et quartum agens aetatis annum. utrique cum praecipua officia uiuae praestitisset, etiam defunctae honores maximos tribuit.", "st": "Aug. 61"}, {"sp": "N", "t": "Sponsam habuerat adulescens P. Seruili Isaurici filiam, sed reconciliatus post primam discordiam Antonio, expostulantibus utriusque militibus ut et necessitudine aliqua iungerentur, priuignam eius Claudiam, Fuluiae ex P. Clodio filiam, duxit uxorem uixdum nubilem ac simultate cum Fuluia socru orta dimisit intactam adhuc et uirginem. mox Scriboniam in matrimonium accepit nuptam ante duobus consularibus, ex altero etiam matrem. cum hac quoque diuortium fecit, 'pertaesus,' ut scribit, 'morum peruersitatem eius,' ac statim Liuiam Drusillam matrimonio Tiberi Neronis et quidem praegnantem abduxit dilexitque et probauit unice ac perseueranter.", "st": "Aug. 62"}, {"sp": "N", "t": "Ex Scribonia Iuliam, ex Liuia nihil liberorum tulit, cum maxime cuperet. infans, qui conceptus erat, immaturus est editus. Iuliam primum Marcello Octauiae sororis suae filio tantum quod pueritiam egresso, deinde, ut is obiit, M. Agrippae nuptum dedit exorata sorore, ut sibi genero cederet; nam tunc Agrippa alteram Marcellarum habebat et ex ea liberos. hoc quoque defuncto, multis ac diu, etiam ex equestri ordine, circumspectis condicionibus, Tiberium priuignum suum elegit coegitque praegnantem uxorem et ex qua iam pater erat dimittere. M. Antonius scribit primum eum Antonio filio suo despondisse Iuliam, dein Cotisoni Getarum regi, quo tempore sibi quoque in uicem filiam regis in matrimonium petisset.", "st": "Aug. 63"}, {"sp": "N", "t": "Nepotes ex Agrippa et Iulia tres habuit C. et L. et Agrippam, neptes duas Iuliam et Agrippinam. Iuliam L. Paulo censoris filio, Agrippinam Germanico sororis suae nepoti collocauit. Gaium et L. adoptauit domi per assem et libram emptos a patre Agrippa tenerosque adhuc ad curam rei p. admouit et consules designatos circum prouincias exercitusque dimisit. filiam et neptes ita instituit, ut etiam lanificio assuefaceret uetaretque loqui aut agere quicquam nisi propalam et quod in di[ut]urnos commentarios referretur; extraneorum quidem coetu adeo prohibuit, ut L. Vinicio, claro decoroque iuueni, scripserit quondam parum modeste fecisse eum, quod filiam suam Baias salutatum uenisset. nepotes et litteras et natare aliaque rudimenta per se plerumque docuit, ac nihil aeque elaborauit quam ut imitarentur chirographum suum; neque cenauit una, nisi ut in imo lecto assiderent, neque iter fecit, nisi ut uehiculo anteirent aut circa adequitarent.", "st": "Aug. 64"}, {"sp": "N", "t": "sed laetum eum atque fidentem et subole et disciplina domus Fortuna destituit. Iulias, filiam et neptem, omnibus probris contaminatas relegauit; C. et L. in duodeuiginti mensium spatio amisit ambos, Gaio in Lycia, Lucio Massiliae defunctis. tertium nepotem Agrippam simulque priuignum Tiberium adoptauit in foro lege curiata; ex quibus Agrippam breui ob ingenium sordidum ac ferox abdicauit seposuitque Surrentum. Aliquanto autem patientius mortem quam dedecora suorum tulit. nam C. Lucique casu non adeo fractus, de filia absens ac libello per quaestorem recitato notum senatui fecit abstinuitque congressu hominum diu prae pudore, etiam de necanda deliberauit. certe cum sub idem tempus una ex consciis liberta Phoebe suspendio uitam finisset, maluisse se ait Phoebes patrem fuisse. relegatae usum uini omnemque delicatiorem cultum ademit neque adiri a quoquam libero seruo[q]ue nisi se consulto permisit, et ita ut certior fieret, qua is aetate, qua statura, quo colore esset, etiam quibus corporis notis uel cicatricibus. post quinquennium demum ex insula in continentem lenioribusque paulo condicionibus transtulit eam. nam ut omnino reuocaret, exorari nullo modo potuit, deprecanti saepe p. R. et pertinacius instanti tales filias talesque coniuges pro contione inprecatus. ex nepte Iulia post damnationem editum infantem adgnosci alique uetuit. Agrippam nihilo tractabiliorem, immo in dies amentiorem in insulam transportauit saepsitque insuper custodia militum. cauit etiam s.c. ut eodem loci in perpetuum contineretur. atque ad omnem et eius et Iuliarum mentionem ingemiscens proclamare etiam solebat:<br>αἴθʼ ὄφελον ἄγαμός τʼ ἔμεναι ἄγονός τʼ ἀπολέσθαι<br>nec aliter eos appellare quam tris uomicas ac tria carcinomata sua.", "st": "Aug. 65"}, {"sp": "N", "t": "Amicitias neque facile admisit et constantissime retinuit, non tantum uirtutes ac merita cuiusque digne prosecutus, sed uitia quoque et delicta, dum taxat modica, perpessus. neque enim temere ex omni numero in amicitia eius afflicti reperientur praeter Saluidienum Rufum, quem ad consulatum usque, et Cornelium Gallum, quem ad praefecturam Aegypti, ex infima utrumque fortuna prouexerat. quorum alterum res nouas molientem damnandum senatui tradidit, alteri ob ingratum et maliuolum animum domo et prouinciis suis interdixit. sed Gallo quoque et accusatorum denuntiationibus et senatus consultis ad necem conpulso laudauit quidem pietatem tanto opere pro se indignantium, ceterum et inlacrimauit et uicem suam conquestus est, quod sibi soli non liceret amicis, quatenus uellet, irasci. reliqui potentia atque opibus ad finem uitae sui quisque ordinis principes floruerunt, quanquam et offensis interuenientibus. desiderauit enim nonnumquam, ne de pluribus referam, et M. Agrippae patientiam et Maecenatis taciturnitatem, cum ille ex leui frigoris suspicione et quod Marcellus sibi anteferretur, Mytilenas se relictis omnibus contulisset, [et] hic secretum de comperta Murenae coniuratione uxori Terentiae prodidisset. Exegit et ipse in uicem ab amicis beniuolentiam mutuam, tam a defunctis quam a uiuis. nam quamuis minime appeteret hereditates, ut qui numquam ex ignoti testamento capere quicquam sustinuerit, amicorum tamen suprema iudicia morosissime pensitauit, neque dolore dissimulato, si parcius aut citra honorem uerborum, neque gaudio, si grate pieque quis se prosecutus fuisset. legata uel partes hereditatium a quibuscumque parentibus relicta sibi aut statim liberis eorum concedere aut, si pupillari aetate essent, die uirilis togae uel nuptiarum cum incremento restituere consueuerat.", "st": "Aug. 66"}, {"sp": "N", "t": "Patronus dominusque non minus seuerus quam facilis et clemens multos libertorum in honore et usu maximo habuit, ut Licin[i]um et Celadum aliosque. Cosmum seruum grauissime de se opinantem non ultra quam compedibus coercuit. Diomeden dispensatorem, a quo simul ambulante incurrenti repente fero apro per metum obiectus est, maluit timiditatis arguere quam noxae remque non minimi periculi, quia tamen fraus aberat, in iocum uertit. idem Polum ex acceptissimis libertis mori coegit compertum adulterare matronas; Thallo a manu, quod pro epistula prodita denarios quingentos accepisset, crura ei fregit; paedagogum ministrosque C. fili, per occasionem ualitudinis mortisque eius superbe auareque in prouincia grassatos, oneratos graui pondere ceruicibus praecipitauit in flumen.", "st": "Aug. 67"}, {"sp": "N", "t": "Prima iuuenta uariorum dedecorum infamiam subiit. Sextus Pompeius ut effeminatum insectatus est; M. Antonius adoptionem auunculi stupro meritum; item L. Marci frater, quasi pudicitiam delibatam a Caesare Aulo etiam Hirtio in Hispania trecentis milibus nummum substrauerit solitusque sit crura suburere nuce ardenti, quo mollior pilus surgeret. sed et populus quondam uniuersus ludorum die et accepit in contumeliam eius et adsensu maximo conprobauit uersum in scaena pronuntiatum de gallo Matris deum tympanizante:<br>uidesne, ut cinaedus orbem digito temperat?", "st": "Aug. 68"}, {"sp": "N", "t": "adulteria quidem exercuisse ne amici quidem negant, excusantes sane non libidine, sed ratione commissa, quo facilius consilia aduersariorum per cuiusque mulieres exquireret. M. Antonius super festinatas Liuiae nuptias obiecit et feminam consularem e triclinio uiri coram in cubiculum abductam, rursus in conuiuium rubentibus auriculis incomptiore capillo reductam; dimissam Scriboniam, quia liberius doluisset nimiam potentiam paelicis; condiciones quaesitas per amicos, qui matres familias et adultas aetate uirgines denudarent atque perspicerent, tamquam Toranio mangone uendente. scribit etiam ad ipsum haec familiariter adhuc necdum plane inimicus aut hostis: 'quid te mutauit? quod reginam ineo? uxor mea est. nunc coepi an abhinc annos nouem? tu deinde solam Drusillam inis? ita ualeas, uti tu, hanc epistulam cum leges, non inieris Tertullam aut Terentillam aut Rufillam aut Saluiam Titiseniam aut omnes. an refert, ubi et in qua arrigas?'", "st": "Aug. 69"}, {"sp": "N", "t": "Cena quoque eius secretior in fabulis fuit, quae uulgo δωδεκάθεος uocabatur; in qua deorum dearumque habitu discubuisse conuiuas et ipsum pro Apolline ornatum non Antoni modo epistulae singulorum nomina amarissime enumerantis exprobrant, sed et sine auctore notissimi uersus:<br>cum primum istorum conduxit mensa choragum,<br>sexque deos uidit Mallia sexque deas,<br>impia dum Phoebi Caesar mendacia ludit,<br>dum noua diuorum cenat adulteria:<br>omnia se a terris tunc numina declinarunt,<br>fugit et auratos Iuppiter ipse thronos.<br>auxit cenae rumorem summa tunc in ciuitate penuria ac fames, adclamatumque est postridie: omne frumentum deos comedisse et Caesarem esse plane Apollinem, sed Tortorem, quo cognomine is deus quadam in parte urbis colebatur. notatus est et ut pretiosae supellectilis Corinthiorumque praecupidus et aleae indulgens. nam et proscriptionis tempore ad statuam eius ascriptum est:<br>pater argentarius, ego Corinthiarius,<br>cum existimaretur quosdam propter uasa Corinthia inter proscriptos curasse referendos; et deinde bello Siciliensi epigramma uulgatum est:<br>postquam bis classe uictus naues perdidit,<br>aliquando ut uincat, ludit assidue aleam.", "st": "Aug. 70"}, {"sp": "N", "t": "ex quibus siue criminibus siue maledictis infamiam impudicitiae facillime refutauit et praesentis et posterae uitae castitate; item lautitiarum inuidiam, cum et Alexandria capta nihil sibi praeter unum murrinum calicem ex instrumento regio retinuerit et mox uasa aurea assiduissimi usus conflauerit omnia. circa libidines haesit, postea quoque, ut ferunt, ad uitiandas uirgines promptior, quae sibi undique etiam ab uxore conquirerentur. aleae rumorem nullo modo expauit lusitque simpliciter et palam oblectamenti causa etiam senex ac praeterquam Decembri mense aliis quoque festis et profestis diebus. nec id dubium est. autographa quadam epistula: 'cenaui,' ait, 'mi Tiberi, cum isdem; accesserunt conuiuae Vinicius et Silius pater. inter cenam lusimus geronticos et heri et hodie; talis enim iactatis, ut quisque canem aut senionem miserat, in singulos talos singulos denarios in medium conferebat, quos tollebat uniuersos, qui Venerem iecerat.' et rursus aliis litteris: 'nos, mi Tiberi, Quinquatrus satis iucunde egimus; lusimus enim per omnis dies forumque aleatorum calfecimus. frater tuus magnis clamoribus rem gessit; ad summam tamen perdidit non multum, sed ex magnis detrimentis praeter spem paulatim retractum est. ego perdidi uiginti milia nummum meo nomine, sed cum effuse in lusu liberalis fuissem, ut soleo plerumque. nam si quas manus remisi cuique exegissem aut retinuissem quod cuique donaui, uicissem uel quinquaginta milia. sed hoc malo; benignitas enim mea me ad caelestem gloriam efferet.' scribit ad filiam: 'misi tibi denarios ducentos quinquaginta, quos singulis conuiuis dederam, si uellent inter se inter cenam uel talis uel par impar ludere.'", "st": "Aug. 71"}, {"sp": "N", "t": "In ceteris partibus uitae continentissimum constat ac sine suspicione ullius uitii. habitauit primo iuxta Romanum forum supra Scalas anularias, in domo quae Calui oratoris fuerat; postea in Palatio, sed nihilo minus aedibus modicis Hortensianis, et neque laxitate neque cultu conspicuis, ut in quibus porticus breues essent Albanarum columnarum et sine marmore ullo aut insigni pauimento conclauia. ac per annos amplius quadraginta eodem cubiculo hieme et aestate mansit, quamuis parum salubrem ualitudini suae urbem hieme experiretur assidueque in urbe hiemaret. si quando quid secreto aut sine interpellatione agere proposuisset, erat illi locus in edito singularis, quem Syracusas et technyphion uocabat: huc transibat aut in alicuius libertorum suburbanum; aeger autem in domo Maecenatis cubabat. ex secessibus praecipue frequentauit maritima insulasque Campaniae aut proxima urbi oppida, Lanuuium, Praeneste, Tibur, ubi etiam in porticibus Herculis templi persaepe ius dixit. ampla et operosa praetoria grauabatur. et neptis quidem suae Iuliae, profuse ab ea extructa, etiam diruit ad solum, sua uero quamuis modica non tam statuarum tabularumque pictarum ornatu quam xystis et nemoribus excoluit rebusque uetustate ac raritate notabilibus, qualia sunt Capreis immanium beluarum ferarumque membra praegrandia, quae dicuntur gigantum ossa, et arma heroum.", "st": "Aug. 72"}, {"sp": "N", "t": "instrumenti eius et supellectilis parsimonia apparet etiam nunc residuis lectis atque mensis, quorum pleraque uix priuatae elegantiae sint. ne toro quidem cubuisse aiunt nisi humili et modice instrato. ueste non temere alia quam domestica usus est, ab sorore et uxore et filia neptibusque confecta; togis neque restrictis neque fusis, clauo nec lato nec angusto, calciamentis altiusculis, ut procerior quam erat uideretur. et forensia autem et calceos numquam non intra cubiculum habuit ad subitos repentinosque casus parata.", "st": "Aug. 73"}, {"sp": "N", "t": "Conuiuabatur assidue nec umquam nisi recta, non sine magno ordinum hominumque dilectu. Valerius Messala tradit, neminem umquam libertinorum adhibitum ab eo cenae excepto Mena, sed asserto in ingenuitatem post proditam Sexti Pompei classem. ipse scribit, inuitasse se quondam, in cuius uilla maneret, qui speculator suus olim fuisset. conuiuia nonnumquam et serius inibat et maturius relinquebat, cum conuiuae et cenare inciperent, prius quam ille discumberet, et permanerent digresso eo. cenam ternis ferculis aut cum abundantissime senis praebebat, ut non nimio sumptu, ita summa comitate. nam et ad communionem sermonis tacentis uel summissim fabulantis prouocabat, et aut acroamata et histriones aut etiam triuiales ex circo ludios interponebat ac frequentius aretalogos.", "st": "Aug. 74"}, {"sp": "N", "t": "Festos et sollemnes dies profusissime, nonnumquam tantum ioculariter celebrabat. Saturnalibus, et si quando alias libuisset, modo munera diuidebat, uestem et aurum et argentum, modo nummos omnis notae, etiam ueteres regios ac peregrinos, interdum nihil praeter cilicia et spongias et rutabula et forpices atque alia id genus titulis obscuris et ambiguis. solebat et inaequalissimarum rerum sortes et auersas tabularum picturas in conuiuio uenditare incertoque casu spem mercantium uel frustrari uel explere, ita ut per singulos lectos licitatio fieret et seu iactura seu lucrum communicaretur.", "st": "Aug. 75"}, {"sp": "N", "t": "cibi—nam ne haec quidem omiserim—minimi erat atque uulgaris fere. secundarium panem et pisciculos minutos et caseum bibulum manu pressum et ficos uirides biferas maxime appetebat; uescebaturque et ante cenam quocumque tempore et loco, quo stomachus desiderasset. uerba ipsius ex epistulis sunt: 'nos in essedo panem et palmulas gustauimus.' et iterum: 'dum lectica ex regia domum redeo, panis unciam cum paucis acinis uuae duracinae comedi.' et rursus: 'ne Iudaeus quidem, mi Tiberi, tam diligenter sabbatis ieiunium seruat quam ego hodie seruaui, qui in balineo demum post horam primam noctis duas buccas manducaui prius quam ungui inciperem.' ex hac inobseruantia nonnumquam uel ante initum uel post dimissum conuiuium solus cenitabat, cum pleno conuiuio nihil tangeret.", "st": "Aug. 76"}, {"sp": "N", "t": "uini quoque natura parcissimus erat. non amplius ter bibere eum solitum super cenam in castris apud Mutinam, Cornelius Nepos tradit. postea quotiens largissime se inuitaret, senos sextantes non excessit, aut si excessisset, reiciebat. et maxime delectatus est Raetico neque temere interdiu bibit. pro potione sumebat perfusum aqua frigida panem aut cucumeris frustum uel lactuculae thyrsum aut recens aridumue pomum suci uinosioris.", "st": "Aug. 77"}, {"sp": "N", "t": "Post cibum meridianum, ita ut uestitus calciatusque erat, retectis pedibus paulisper conquiescebat opposita ad oculos manu. a cena in lecticulam se lucubratoriam recipiebat; ibi, donec residua diurni actus aut omnia aut ex maxima parte conficeret, ad multam noctem permanebat. in lectum inde transgressus non amplius cum plurimum quam septem horas dormiebat, ac ne eas quidem continuas, sed ut in illo temporis spatio ter aut quater expergisceretur. si interruptum somnum reciperare, ut euenit, non posset, lectoribus aut fabulatoribus arcessitis resumebat producebatque ultra primam saepe lucem. nec in tenebris uigilauit umquam nisi assidente aliquo. matutina uigilia offendebatur; ac si uel officii uel sacri causa maturius uigilandum esset, ne id contra commodum faceret, in proximo cuiuscumque domesticorum cenaculo manebat. sic quoque saepe indigens somni, et dum per uicos deportaretur et deposita lectica inter aliquas moras condormiebat.", "st": "Aug. 78"}, {"sp": "N", "t": "Forma fuit eximia et per omnes aetatis gradus uenustissima, quamquam et omnis lenocinii neglegens; in capite comendo tam incuriosus, ut raptim compluribus simul tonsoribus operam daret ac modo tonderet modo raderet barbam eoque ipso tempore aut legeret aliquid aut etiam scriberet. uultu erat uel in sermone uel tacitus adeo tranquillo serenoque, ut quidam e primoribus Galliarum confessus sit inter suos, eo se inhibitum ac remollitum, quo minus, ut destinarat, in transitu Alpium per simulationem conloquii propius admissus in praecipitium propelleret. oculos habuit claros ac nitidos, quibus etiam existimari uolebat inesse quiddam diuini uigoris, gaudebatque, si qui sibi acrius contuenti quasi ad fulgorem solis uultum summitteret; sed in senecta sinistro minus uidit; dentes raros et exiguos et scabros; capillum leuiter inflexum et subflauum; supercilia coniuncta; mediocres aures; nasum et a summo eminentiorem et ab imo deductiorem; colorem inter aquilum candidumque; staturam breuem,—quam tamen Iulius Marathus libertus †etiam memoriam eius quinque pedum et dodrantis fuisse tradit—, sed quae commoditate et aequitate membrorum occuleretur, ut non nisi ex comparatione astantis alicuius procerioris intellegi posset.", "st": "Aug. 79"}, {"sp": "N", "t": "Corpore traditur maculoso dispersis per pectus atque aluum genetiuis notis in modum et ordinem ac numerum stellarum caelestis ursae, sed et callis quibusdam ex prurigine corporis adsiduoque et uehementi strigilis usu plurifariam concretis ad impetiginis formam. coxendice et femore et crure sinistro non perinde ualebat, ut saepe etiam inclaudicaret; sed remedio harenarum atque harundinum confirmabatur. dextrae quoque manus digitum salutarem tam imbecillum interdum sentiebat, ut torpentem contractumque frigore uix cornei circuli supplemento scripturae admoueret. questus est et de uesica, cuius dolore calculis demum per urinam eiectis leuabatur.", "st": "Aug. 80"}, {"sp": "N", "t": "Graues et periculosas ualitudines per omnem uitam aliquot expertus est; praecipue Cantabria domita, cum etiam destillationibus iocinere uitiato ad desperationem redactus contrariam et ancipitem rationem medendi necessario subiit: quia calida fomenta non proderant, frigidis curari coactus auctore Antonio Musa. Quasdam et anniuersarias ac tempore certo recurrentes experiebatur; nam sub natalem suum plerumque languebat; et initio ueris praecordiorum inflatione temptabatur, austrinis autem tempestatibus grauedine. quare quassato corpore neque frigora neque aestus facile tolerabat.", "st": "Aug. 81"}, {"sp": "N", "t": "hieme quaternis cum pingui toga tunicis et subucula et thorace laneo et feminalibus et tibialibus muniebatur, aestate apertis cubiculi foribus ac saepe in peristylo saliente aqua atque etiam uentilante aliquo cubabat. solis uero ne hiberni quidem patiens, domi quoque non nisi petasatus sub diuo spatiabatur. itinera lectica et noctibus fere eaque lenta ac minuta faciebat, ut Praeneste uel Tibur biduo procederet; ac si quo peruenire mari posset, potius nauigabat. uerum tantam infirmitatem magna cura tuebatur, in primis lauandi raritate; unguebatur enim saepius aut sudabat ad flammam, deinde perfundebatur egelida aqua uel sole multo tepefacta. at quotiens neruorum causa marinis Albulisque calidis utendum esset, contentus hoc erat ut insidens ligneo solio, quod ipse Hispanico uerbo duretam uocabat, manus ac pedes alternis iactaret.", "st": "Aug. 82"}, {"sp": "N", "t": "Exercitationes campestres equorum et armorum statim post ciuilia bella omisit et ad pilam primo folliculumque transiit, mox nihil aliud quam uectabatur et deambulabat, ita ut in extremis spatiis subsultim decurreret †sestertio uel lodicula inuolutus. animi laxandi causa modo piscabatur hamo, modo talis aut ocellatis nucibusque ludebat cum pueris minutis, quos facie et garrulitate amabilis undique conquirebat, praecipue Mauros et Syros. nam pumilos atque distortos et omnis generis eiusdem ut ludibria naturae malique ominis abhorrebat.", "st": "Aug. 83"}, {"sp": "N", "t": "Eloquentiam studiaque liberalia ab aetate prima et cupide et laboriosissime exercuit. Mutinensi bello in tanta mole rerum et legisse et scripsisse et declamasse cotidie traditur. nam deinceps neque in senatu neque apud populum neque apud milites locutus est umquam nisi meditata et composita oratione, quamuis non deficeretur ad subita extemporali facultate. ac ne periculum memoriae adiret aut in ediscendo tempus absumeret, instituit recitare omnia. sermones quoque cum singulis atque etiam cum Liuia sua grauiores non nisi scriptos et e libello habebat, ne plus minusue loqueretur ex tempore. pronuntiabat dulci et proprio quodam oris sono dabatque assidue phonasco operam; sed nonnumquam infirmatis faucibus praeconis uoce ad populum contionatus est.", "st": "Aug. 84"}, {"sp": "N", "t": "Multa uarii generis prosa oratione composuit, ex quibus nonnulla in coetu familiarium uelut in auditorio recitauit, sicut 'rescripta Bruto de Catone,' quae uolumina cum iam senior ex magna parte legisset, fatigatus Tiberio tradidit perlegenda; item 'hortationes ad philosophiam,' et aliqua 'de uita sua,' quam tredecim libris Cantabrico tenus bello nec ultra exposuit. poetica summatim attigit. unus liber extat scriptus ab eo hexametris uersibus, cuius et argumentum et titulus est 'Sicilia'; extat alter aeque modicus 'epigrammatum,' quae fere tempore balinei meditabatur. nam tragoediam magno impetu exorsus, non succedenti stilo, aboleuit quaerentibusque amicis, quidnam Aiax ageret, respondit Aiacem suum in spongiam incubuisse.", "st": "Aug. 85"}, {"sp": "N", "t": "Genus eloquendi secutus est elegans et temperatum uitatis sententiarum ineptiis atque concinnitate et 'reconditorum uerborum,' ut ipse dicit, 'fetoribus'; praecipuamque curam duxit sensum animi quam apertissime exprimere. quod quo facilius efficeret aut necubi lectorem uel auditorem obturbaret ac moraretur, neque praepositiones urbibus addere neque coniunctiones saepius iterare dubitauit, quae detractae afferunt aliquid obscuritatis, etsi gratiam augent. cacozelos et antiquarios, ut diuerso genere uitiosos, pari fastidio spreuit exagitabatque nonnumquam; in primis Maecenatem suum, cuius 'myrobrechis,' ut ait, 'cincinnos' usque quaque persequitur et imitando per iocum irridet. sed nec Tiberio parcit et exoletas interdum et reconditas uoces aucupanti. M. quidem Antonium ut insanum increpat, quasi ea scribentem, quae mirentur potius homines quam intellegant; deinde ludens malum et inconstans in eligendo genere dicendi ingenium eius, addit haec: 'tuque dubitas, Cimberne Annius an Veranius Flaccus imitandi sint tibi, ita ut uerbis, quae Crispus Sallustius excerpsit ex Originibus Catonis, utaris? an potius Asiaticorum oratorum inani[bu]s sententiis uerborum uolubilitas in nostrum sermonem transferenda?' et quadam epistula Agrippinae neptis ingenium conlaudans: 'sed opus est,' inquit, 'dare te operam, ne moleste scribas et loquaris.'", "st": "Aug. 86"}, {"sp": "N", "t": "Cotidiano sermone quaedam frequentius et notabiliter usurpasse eum, litterae ipsius autographae ostentant, in quibus identidem, cum aliquos numquam soluturos significare uult, 'ad K(a)l(endas) Graecas soluturos' ait; et cum hortatur ferenda esse praesentia, qualiacumque sint: 'contenti simus hoc Catone'; et ad exprimendam festinatae rei uelocitatem: 'celerius quam asparagi cocuntur.' ponit assidue et pro stulto 'baceolum apud pullum pulleiaceum' et pro cerrito 'uacerrosum' et 'uapide' se habere pro male et 'betizare' pro languere, quod uulgo 'lachanizare' dicitur; item 'simus' pro sumus et 'domos' genetiuo casu singulari pro domuos. nec umquam aliter haec duo, ne quis mendam magis quam consuetudinem putet. Notaui et in chirographo eius illa praecipue: non diuidit uerba nec ab extrema parte uersuum abundantis litteras in alterum transfert, sed ibidem statim subicit circumducitque.", "st": "Aug. 87"}, {"sp": "N", "t": "orthographiam, id est formulam rationemque scribendi a grammaticis institutam, non adeo custodi[i]t ac uidetur eorum potius sequi opinionem, qui perinde scribendum ac loquamur existiment. nam quod saepe non litteras modo sed syllabas aut permutat aut praeterit, communis hominum error est. nec ego id notarem, nisi mihi mirum uideretur tradidisse aliquos, legato eum consulari successorem dedisse ut rudi et indocto, cuius manu 'ixi' pro ipsi scriptum animaduerterit. quotiens autem per notas scribit, B pro A, C pro B ac deinceps eadem ratione sequentis litteras ponit; pro X autem duplex A.", "st": "Aug. 88"}, {"sp": "N", "t": "Ne Graecarum quidem disciplinarum leuiore studio tenebatur. in quibus et ipsis praestabat largiter magistro dicendi usus Apollodoro Pergameno, quem iam grandem natu Apolloniam quoque secum ab urbe iuuenis adhuc eduxerat, deinde eruditione etiam uaria repletus [s]per Arei philosophi filiorumque eius Dionysi et Nicanoris contubernium; non tamen ut aut loqueretur expedite aut componere aliquid auderet; nam et si quid res exigeret, Latine formabat uertendumque alii dabat. sed plane poematum quoque non imperitus, delectabatur etiam comoedia ueteri et saepe eam exhibuit spectaculis publicis. In euoluendis utriusque linguae auctoribus nihil aeque sectabatur, quam praecepta et exempla publice uel priuatim salubria, eaque ad uerbum excerpta aut ad domesticos aut ad exercituum prouinciarumque rectores aut ad urbis magistratus plerumque mittebat, prout quique monitione indigerent. etiam libros totos et senatui recitauit et populo notos per edictum saepe fecit, ut orationes Q. Metelli 'de prole augenda' et Rutili 'de modo aedificiorum,' quo magis persuaderet utramque rem non a se primo animaduersam, sed antiquis iam tunc curae fuisse. Ingenia saeculi sui omnibus modis fouit. recitantis et benigne et patienter audiit, nec tantum carmina et historias, sed et orationes et dialogos. componi tamen aliquid de se nisi et serio et a praestantissimis offendebatur, admonebatque praetores ne paterentur nomen suum commissionibus obsolefieri.", "st": "Aug. 89"}, {"sp": "N", "t": "Circa religiones talem accepimus. tonitrua et fulgura paulo infirmius expauescebat, ut semper et ubique pellem uituli marini circumferret pro remedio atque ad omnem maioris tempestatis suspicionem in abditum et concamaratum locum se reciperet, consternatus olim per nocturnum iter transcursu fulguris, ut praediximus.", "st": "Aug. 90"}, {"sp": "N", "t": "Somnia neque sua neque aliena de se neglegebat. Philippensi acie quamuis statuisset non egredi tabernaculo propter ualitudinem, egressus est tamen amici somnio monitus; cessitque res prospere, quando captis castris lectica eius, quasi ibi cubans remansisset, concursu hostium confossa atque lacerata est. ipse per omne uer plurima et formidulosissima et uana et irrita uidebat, reliquo tempore rariora et minus uana. cum dedicatam in Capitolio aedem Tonanti Ioui assidue frequentaret, somniauit queri Capitolinum Iouem cultores sibi abduci seque respondisse Tonantem pro ianitore ei appositum; ideoque mox tintinnabulis fastigium aedis redimiit, quod ea fere ianuis dependebant. ex nocturno uisu etiam stipem quotannis die certo emendicabat a populo cauam manum asses porrigentibus praebens.", "st": "Aug. 91"}, {"sp": "N", "t": "Auspicia et omina quaedam pro certissimis obseruabat: si mane sibi calceus perperam ac sinister pro dextro induceretur, ut dirum; si terra mariue ingrediente se longinquam profectionem forte rorasset, ut laetum maturique et prosperi reditus. sed et ostentis praecipue mouebatur. enatam inter iuncturas lapidum ante domum suam palmam in conpluuium deorum Penatium transtulit, utque coalesceret magno opere curauit. apud insulam Capreas ueterrimae ilicis demissos iam ad terram languentisque ramos conualuisse aduentu suo, adeo laetatus est, ut eas cum re p. Neapolitanorum permutauerit Aenaria data. obseruabat et dies quosdam, ne aut postridie nundinas quoquam proficisceretur aut Nonis quicquam rei seriae incoharet; nihil in hoc quidem aliud deuitans, ut ad Tiberium scribit, quam δυσφημίαν nominis.", "st": "Aug. 92"}, {"sp": "N", "t": "Peregrinarum caerimoniarum sicut ueteres ac praeceptas reuerentissime coluit, ita ceteras contemptui habuit. namque Athenis initiatus, cum postea Romae pro tribunali de priuilegio sacerdotum Atticae Cereris cognosceret et quaedam secretiora proponerentur, dimisso consilio et corona circumstantium solus audiit disceptantes. at contra non modo in peragranda Aegypto paulo deflectere ad uisendum Apin supersedit, sed et Gaium nepotem, quod Iudaeam praeteruehens apud Hierosolyma[m] non supplicasset, conlaudauit.", "st": "Aug. 93"}, {"sp": "N", "t": "Et quoniam ad haec uentum est, non ab re fuerit subtexere, quae ei prius quam nasceretur et ipso natali die ac deinceps euenerint, quibus futura magnitudo eius et perpetua felicitas sperari animaduertique posset. Velitris antiquitus tacta de caelo parte muri responsum est eius oppidi ciuem quandoque rerum potiturum; qua fiducia Veliterni et tunc statim et postea saepius paene ad exitium sui cum populo R. belligerauerant; sero tandem documentis apparuit ostentum illud Augusti potentiam portendisse. Auctor est Iulius Marathus, ante paucos quam nasceretur menses prodigium Romae factum publice, quo denuntiabatur, regem p(opulo) R(omano) naturam parturire; senatum exterritum censuisse, ne quis illo anno genitus educaretur; eos qui grauidas uxores haberent, quod ad se quisque spem traheret, curasse ne senatus consultum ad aerarium deferretur. In Asclepiadis Mendetis Theologumenon libris lego, Atiam, cum ad sollemne Apollinis sacrum media nocte uenisset, posita in templo lectica, dum ceterae matronae dormirent, obdormisse; draconem repente irrepsisse ad eam pauloque post egressum; illam expergefactam quasi a concubitu mariti purificasse se; et statim in corpore eius extitisse maculam uelut picti draconis nec potuisse umquam exigi, adeo ut mox publicis balineis perpetuo abstinuerit; Augustum natum mense decimo et ob hoc Apollinis filium existimatum. eadem Atia, prius quam pareret, somniauit intestina sua ferri ad sidera explicarique per omnem terrarum et caeli ambitum. somniauit et pater Octauius utero Atiae iubar solis exortum. Quo natus est die, cum de Catilinae coniuratione ageretur in curia et Octauius ob uxoris puerperium serius affuisset, nota ac uulgata res est P. Nigidium comperta morae causa, ut horam quoque partus acceperit, affirmasse dominum terrarum orbi natum. Octauio postea, cum per secreta Thraciae exercitum duceret, in Liberi patris luco barbara caerimonia de filio consulenti, idem affirmatum est a sacerdotibus, quod infuso super altaria mero tantum flammae emicuisset, ut supergressa fastigium templi ad caelum usque ferretur, unique omnino Magno Alexandro apud easdem aras sacrificanti simile prouenisset ostentum. atque etiam sequenti statim nocte uidere uisus est filium mortali specie ampliorem, cum fulmine et sceptro exuuiisque Iouis Optimi Maximi ac radiata corona, super laureatum currum, bis senis equis candore eximio trahentibus. infans adhuc, ut scriptum apud C. Drusum extat, repositus uespere in cunas a nutricula loco plano, postera luce non comparuit diuque quaesitus tandem in altissima turri repertus est iacens contra solis exortum. Cum primum fari coepisset, in auito suburbano obstrepentis forte ranas silere iussit, atque ex eo negantur ibi ranae coaxare. ad quartum lapidem Campanae uiae in nemore prandenti ex inprouiso aquila panem ei e manu rapuit et, cum altissime euolasset, rursus ex inprouiso leniter delapsa reddidit. Q. Catulus post dedicatum Capitolium duabus continuis noctibus somniauit: prima, Iouem Optimum Maximum e praetextatis compluribus circum aram ludentibus unum secreuisse atque in eius sinum signum rei p. quod manu gestaret reposuisse; at insequenti, animaduertisse se in gremio Capitolini Iouis eundem puerum, quem cum detrahi iussisset, prohibitum monitu dei, tamquam is ad tutelam rei p. educaretur; ac die proximo obuium sibi Augustum, cum incognitum alias haberet, non sine admiratione contuitus simillimum dixit puero, de quo somniasset. quidam prius somnium Catuli aliter exponunt, quasi Iuppiter compluribus praetextatis tutorem a se poscentibus unum ex eis demonstrasset, ad quem omnia desideria sua referrent, eiusque osculum delibatum digitis ad os suum rettulisset. M. Cicero C. Caesarem in Capitolium prosecutus somnium pristinae noctis familiaribus forte narrabat: puerum facie liberali demissum e caelo catena aurea ad fores Capitoli constitisse eique Iouem flagellum tradidisse; deinde repente Augusto uiso, quem ignotum plerisque adhuc auunculus Caesar ad sacrificandum acciuerat, affirmauit ipsum esse, cuius imago secundum quietem sibi obuersata sit. Sumenti uirilem togam tunica lati claui resuta ex utraque parte ad pedes decidit. fuerunt qui interpretarentur, non aliud significare, quam ut is ordo cuius insigne id esset quandoque ei subiceretur. Apud Mundam Diuus Iulius castris locum capiens cum siluam caederet, arborem palmae repertam conseruari ut omen uictoriae iussit; ex ea continuo enata suboles adeo in paucis diebus adoleuit, ut non aequiperaret modo matricem, uerum et obtegeret frequentareturque columbarum nidis, quamuis id auium genus duram et asperam frondem maxime uitet. illo et praecipue ostento motum Caesarem ferunt, ne quem alium sibi succedere quam sororis nepotem uellet. In secessu Apolloniae Theogenis mathematici pergulam comite Agrippa ascenderat; cum Agrippae, qui prior consulebat, magna et paene incredibilia praedicerentur, reticere ipse genituram suam nec uelle edere perseuerabat, metu ac pudore ne minor inueniretur. qua tamen post multas adhortationes uix et cunctanter edita exiliuit Theogenes adorauitque eum. tantam mox fiduciam fati Augustus habuit, ut thema suum uulgauerit nummumque argenteum nota sideris Capricorni, quo natus est, percusserit.", "st": "Aug. 94"}, {"sp": "N", "t": "Post necem Caesaris reuerso ab Apollonia et ingrediente eo urbem repente liquido ac puro sereno circulus ad speciem caelestis arcus orbem solis ambiit ac subinde Iuliae Caesaris filiae monimentum fulmine ictum est. primo autem consulatu et augurium capienti duodecim se uultures ut Romulo ostenderunt et immolanti omnium uictimarum iocinera replicata intrinsecus ab ima fibra paruerunt, nemine peritorum aliter coiectante quam laeta per haec et magna portendi.", "st": "Aug. 95"}, {"sp": "N", "t": "Quin et bellorum omnium euentus ante praesensit. contractis ad Bononiam triumuirorum copiis aquila tentorio eius supersedens duos coruos hinc et inde infestantis afflixit et ad terram dedit, notante omni exercitu futuram quandoque inter collegas discordiam talem qualis secuta est, atque exitum praesagiente. … Philippos Thessalus quidam de futura uictoria nuntiauit auctore Diuo Caesare, cuius sibi species itinere auio occurrisset. Circa Perusiam sacrificio non litanti cum augeri hostias imperasset ac subita eruptione hostes omnem rei diuinae apparatum abstulissent, constitit inter haruspices, quae periculosa et aduersa sacrificanti denuntiata essent, cuncta in ipsos recasura qui exta haberent; neque aliter euenit. pridie quam Siciliensem pugnam classe committeret, deambulanti in litore piscis e mari exiliuit et ad pedes iacuit. apud Actium descendenti in aciem asellus cum asinario occurrit: homini Eutychus, bestiae Nicon erat nomen; utriusque simulacrum aeneum uictor posuit in templo, in quod castrorum suorum locum uertit.", "st": "Aug. 96"}, {"sp": "N", "t": "Mors quoque eius, de qua dehinc dicam, diuinitasque post mortem euidentissimis ostentis praecognita est. cum lustrum in campo Martio magna populi frequentia conderet, aquila eum saepius circumuolauit transgressaque in uicinam aedem super nomen Agrippae ad primam litteram sedit; quo animaduerso uota, quae in proximum lustrum suscipi mos est, collegam suum Tiberium nuncupare iussit: nam se, quanquam conscriptis paratisque iam tabulis, negauit suscepturum quae non esset soluturus. sub idem tempus ictu fulminis ex inscriptione statuae eius prima nominis littera effluxit; responsum est, centum solos dies posthac uicturum, quem numerum C littera notaret, futurumque ut inter deos referretur, quod aesar, id est reliqua pars e Caesaris nomine, Etrusca lingua deus uocaretur. Tiberium igitur in Illyricum dimissurus et Beneuentum usque prosecuturus, cum interpellatores aliis atque aliis causis in iure dicendo detinerent, exclamauit, quod et ipsum mox inter omina relatum est: non, si omnia morarentur, amplius se posthac Romae futurum; atque itinere incohato Asturam perrexit et inde praeter consuetudinem de nocte ad occasionem aurae euectus causam ualitudinis contraxit ex profluuio alui.", "st": "Aug. 97"}, {"sp": "N", "t": "tunc Campaniae ora proximisque insulis circuitis Caprearum quoque secessui quadriduum impendit remississimo ad otium et ad omnem comitatem animo. Forte Puteolanum sinum praeteruehenti uectores nautaeque de naui Alexandrina, quae tantum quod appulerat, candidati coronatique et tura libantes fausta omina et eximias laudes congesserant: per illum se uiuere, per illum nauigare, libertate atque fortunis per illum frui. qua re admodum exhilaratus quadragenos aureos comitibus diuisit iusque iurandum et cautionem exegit a singulis, non alio datam summam quam in emptionem Alexandrinarum mercium absumpturos. sed et ceteros continuos dies inter uaria munuscula togas insuper ac pallia distribuit, lege proposita ut Romani Graeco, Graeci Romano habitu et sermone uterentur. spectauit assidue exercentes ephebos, quorum aliqua adhuc copia ex uetere instituto Capreis erat; isdem etiam epulum in conspectu suo praebuit permissa, immo exacta iocandi licentia diripiendique pomorum et obsoniorum rerumque … missilia. nullo denique genere hilaritatis abstinuit. Vicinam Capreis insulam Apragopolim appellabat a desidia secedentium illuc e comitatu suo. sed ex dilectis unum, Masgaban nomine, quasi conditorem insulae κτίστην uocare consueuerat. huius Masgabae ante annum defuncti tumulum cum e triclinio animaduertisset magna turba multisque luminibus frequentari, uersum compositum ex tempore clare pronuntiauit:<br>κτίστου δὲ τύμβον εἰσορῶ πυρούμενον·<br>conuersusque ad Thrasyllum Tiberi comitem contra accubantem et ignarum rei interrogauit, cuiusnam poetae putaret esse; quo haesitante subiecit alium:<br>ὁρᾷς φάεσσι Μασγάβαν τιμώμενον;<br>ac de hoc quoque consuluit. cum ille nihil aliud responderet quam, cuiuscumque essent optimos esse, cachinnum sustulit atque in iocos effusus est. mox Neapolim traiecit quanquam etiam tum infirmis intestinis morbo uariante; tamen et quinquennale certamen gymnicum honori suo institutum perspectauit et cum Tiberio ad destinatum locum contendit. sed in redeundo adgrauata ualitudine tandem Nolae succubuit reuocatumque ex itinere Tiberium diu secreto sermone detinuit neque post ulli maiori negotio animum accommodauit.", "st": "Aug. 98"}, {"sp": "N", "t": "Supremo die identidem exquirens, an iam de se tumultus foris esset, petito speculo capillum sibi comi ac malas labantes corrigi praecepit et admissos amicos percontatus, ecquid iis uideretur mi[ni]mum uitae commode transegisse, adiecit et clausulam:<br>ἐπεὶ δὲ πάνυ καλῶς πέπαισται, δότε κρότον<br>καὶ πάντες ἡμᾶς μετὰ χαρᾶς προπέμψατε.<br>omnibus deinde dimissis, dum aduenientes ab urbe de Drusi filia aegra interrogat, repente in osculis Liuiae et in hac uoce defecit: 'Liuia, nostri coniugii memor uiue, ac uale!' sortitus exitum facilem et qualem semper optauerat. nam fere quotiens audisset cito ac nullo cruciatu defunctum quempiam, sibi et suis εὐθανασίαν similem—hoc enim et uerbo uti solebat—precabatur. unum omnino ante efflatam animam signum alienatae mentis ostendit, quod subito pauefactus a quadraginta se iuuenibus abripi questus est. id quoque magis praesagium quam mentis deminutio fuit, siquidem totidem milites praetoriani extulerunt eum in publicum.", "st": "Aug. 99"}, {"sp": "N", "t": "obiit in cubiculo eodem, quo pater Octauius, duobus Sextis, Pompeio et Appuleio, cons. XIIII. Kal. Septemb. hora diei nona, septuagesimo et sexto aetatis anno, diebus V et XXX minus. Corpus decuriones municipiorum et coloniarum a Nola Bouillas usque deportarunt noctibus propter anni tempus, cum interdiu in basilica cuiusque oppidi uel in aedium sacrarum maxima reponeretur. a Bouillis equester ordo suscepit urbique intulit atque in uestibulo domus conlocauit. senatus et in funere ornando et in memoria honoranda eo studio certatim progressus est, ut inter alia complura censuerint quidam, funus triumphali porta ducendum, praecedente Victoria quae est in curia, canentibus neniam principum liberis utriusque sexus; alii, exequiarum die ponendos anulos aureos ferreosque sumendos; nonnulli, ossa legenda per sacerdotes summorum collegiorum. fuit et qui suaderet, appellationem mensis Augusti in Septembrem transferendam, quod hoc genitus Augustus, illo defunctus esset; alius, ut omne tempus a primo die natali ad exitum eius saeculum Augustum appellaretur et ita in fastos referretur. uerum adhibito honoribus modo bifariam laudatus est: pro aede Diui Iuli a Tiberio et pro rostris ueteribus a Druso Tiberi filio, ac senatorum umeris delatus in Campum crematusque. nec defuit uir praetorius, qui se effigiem cremati euntem in caelum uidisse iuraret. reliquias legerunt primores equestris ordinis tunicati et discincti pedibusque nudis ac Mausoleo condiderunt. id opus inter Flaminiam uiam ripamque Tiberis sexto suo consulatu extruxerat circumiectasque siluas et ambulationes in usum populi iam tum publicarat.", "st": "Aug. 100"}, {"sp": "N", "t": "Testamentum L. Planco C. Silio cons. III. Non. Apriles, ante annum et quattuor menses quam decederet, factum ab eo ac duobus codicibus partim ipsius partim libertorum Polybi et Hilarionis manu scriptum depositumque apud se uirgines Vestales cum tribus signatis aeque uoluminibus protulerunt. quae omnia in senatu aperta atque recitata sunt. heredes instituit primos: Tiberium ex parte dimidia et sextante, Liuiam ex parte tertia, quos et ferre nomen suum iussit; secundos: Drusum Tiberi filium ex triente, ex partibus reliquis Germanicum liberosque eius tres sexus uirilis; tertio gradu propinquos amicosque compluris. legauit populo R. quadringenties, tribubus tricies quinquies sestertium, praetorianis militibus singula milia nummorum, cohortibus urbanis quingenos, legionaris trecenos nummos; quam summam repraesentari iussit, nam et confiscatam semper repositamque habuerat. reliqua legata uarie dedit perduxitque quaedam ad uicena sestertia, quibus soluendis annuum diem finiit, excusata rei familiaris mediocritate nec plus peruenturum ad heredes suos quam milies et quingenties professus, quamuis uiginti proximis annis quaterdecies milies ex testamentis amicorum percepisset, quod paene omne cum duobus paternis patrimoniis ceterisque hereditatibus in rem p. absumpsisset. Iulias filiam neptemque, si quid iis accidisset, uetuit sepulcro suo inferri. tribus uoluminibus, uno mandata de funere suo complexus est, altero indicem rerum a se gestarum, quem uellet incidi in aeneis tabulis, quae ante Mausoleum statuerentur, tertio breuiarium totius imperii, quantum militum sub signis ubique esset, quantum pecuniae in aerario et fiscis et uectigaliorum residuis. adiecit et libertorum seruorumque nomina, a quibus ratio exigi posset.", "st": "Aug. 101"}, {"sp": "HDR", "t": "Tiberius", "st": "Tib."}, {"sp": "N", "t": "Patricia gens Claudia—fuit enim et alia plebeia, nec potentia minor nec dignitate—orta est ex Regillis oppido Sabinorum. inde Romam recens conditam cum magna clientium manu conmigrauit auctore Tito Tatio consorte Romuli, uel, quod magis constat, Atta Claudio gentis principe, post reges exactos sexto fere anno; atque in patricias cooptata agrum insuper trans Anienem clientibus locumque sibi ad sepulturam sub Capitolio publice accepit. deinceps procedente tempore duodetriginta consulatus, dictaturas quinque, censuras septem, triumphos sex, duas ouationes adepta est. cum praenominibus cognominibusque uariis distingueretur, Luci praenomen consensu repudiauit, postquam e duobus gentilibus praeditis eo alter latrocinii, caedis alter conuictus est. inter cognomina autem et Neronis assumpsit, quo[d] significatur lingua Sabina fortis ac strenuus.", "st": "Tib. 1"}, {"sp": "N", "t": "Multa multorum Claudiorum egregia merita, multa etiam sequius admissa in rem p. extant. sed ut praecipua commemorem, Appius Caecus societatem cum rege Pyrro ut parum salubrem iniri dissuasit. Claudius Caudex primus freto classe traiecto Poenos Sicilia expulit. †Tibus Nero aduenientem ex Hispania cum ingentibus copiis Hasdrubalem, prius quam Hannibali fratri coniungeretur, oppressit. contra Claudius Regillianus, decemuir legibus scribendis, uirginem ingenuam per uim libidinis gratia in seruitutem asserere conatus causa plebi fuit secedendi rursus a patribus. Claudius †Drusus statua sibi diademata ad Appi Forum posita Italiam per clientelas occupare temptauit. Claudius Pulcher apud Siciliam non pascentibus in auspicando pullis ac per contemptum religionis mari demersis, quasi ut biberent quando esse nollent, proelium nauale iniit; superatusque, cum dictatorem dicere a senatu iuberetur, uelut iterum inludens discrimini publico Glycian uiatorem suum dixit. Extant et feminarum exempla diuersa aeque, siquidem gentis eiusdem utraque Claudia fuit, et quae nauem cum sacris Matris deum Idaeae obhaerentem Tiberino uado extraxit, precata propalam, ut ita demum se sequeretur, si sibi pudicitia constaret; et quae nouo more iudicium maiestatis apud populum mulier subiit, quod in conferta multitudine aegre procedente carpento palam optauerat, ut frater suus Pulcher reuiuisceret atque iterum classem amitteret, quo minor turba Romae foret. praeterea notatissimum est, Claudios omnis, excepto dum taxat P. Clodio, qui ob expellendum urbe Ciceronem plebeio homini atque etiam natu minori in adoptionem se dedit, optimates adsertoresque unicos dignitatis ac potentiae patriciorum semper fuisse atque aduersus plebem adeo uiolentos et contumaces, ut ne capitis quidem quisquam reus apud populum mutare uestem aut deprecari sustinuerit; nonnulli in altercatione et iurgio tribunos plebi pulsauerint. etiam uirgo Vestalis fratrem iniussu populi triumphantem ascenso simul curru usque in Capitolium prosecuta est, ne uetare aut intercedere fas cuiquam tribunorum esset.", "st": "Tib. 2"}, {"sp": "N", "t": "Ex hac stirpe Tiberius Caesar genus trahit, et quidem utrumque: paternum a Tiberio Nerone, maternum ab Appio Pulchro, qui ambo Appi Caeci filii fuerunt. insertus est et Liuiorum familiae adoptato in eam materno auo. quae familia, quanquam plebeia, tamen et ipsa admodum floruit octo consulatibus, censuris duabus, triumphis tribus, dictatura etiam ac magisterio equitum honorata; clara et insignibus uiris ac maxime Salinatore Drusisque. Salinator uniuersas tribus in censura notauit leuitatis nomine, quod, cum se post priorem consulatum multa inrogata condemnassent, consulem iterum censoremque fecissent. Drusus hostium duce Drauso comminus trucidato sibi posterisque suis cognomen inuenit. traditur etiam pro praetore ex prouincia Gallia rettulisse aurum Senonibus olim in obsidione Capitolii datum nec, ut fama est, extortum a Camillo. eius abnepos ob eximiam aduersus Gracchos operam patronus senatus dictus filium reliquit, quem in simili dissensione multa uarie molientem diuersa factio per fraudem interemit.", "st": "Tib. 3"}, {"sp": "N", "t": "Pater Tiberi, Nero, quaestor C. Caesaris Alexandrino bello classi praepositus, plurimum ad uictoriam contulit. quare et pontifex in locum P. Scipionis substitutus et ad deducendas in Galliam colonias, in quis Narbo et Arelate erant, missus est. tamen Caesare occiso, cunctis turbarum metu abolitionem facti decernentibus, etiam de praemiis tyrannicidarum referendum censuit. praetura deinde functus, cum exitu anni discordia inter triumuiros orta esset, retentis ultra iustum tempus insignibus L. Antonium consulem triumuiri fratrem ad Perusiam secutus, deditione a ceteris facta, solus permansit in partibus ac primo Praeneste, inde Neapolim euasit seruisque ad pilleum frustra uocatis in Siciliam profugit. sed indigne ferens nec statim se in conspectum Sexti Pompei admissum et fascium usu prohibitum, ad M. Antonium traiecit in Achaiam. cum quo breui reconciliata inter omnis pace Romam redit uxoremque Liuiam Drusillam et tunc grauidam et ante iam apud se filium enixam petenti Augusto concessit. nec multo post diem obiit, utroque liberorum superstite, Tiberio Drusoque Neronibus.", "st": "Tib. 4"}, {"sp": "N", "t": "Tiberium quidam Fundis natum existimauerunt secuti leuem coniecturam, quod materna eius auia Fundana fuerit et quod mox simulacrum Felicitatis ex s. c. publicatum ibi sit. sed ut plures certioresque tradunt, natus est Romae in Palatio XVI. Kal. Dec. M. Aemilio Lepido iterum L. Munatio Planco conss. per bellum Philippense. sic enim in fastos actaque in publica relatum est. nec tamen desunt, qui partim antecedente anno, Hirti ac Pansae, partim insequenti, Seruili Isaurici L.que Antoni[i] consulatu, genitum eum scribant.", "st": "Tib. 5"}, {"sp": "N", "t": "Infantiam pueritiamque habuit laboriosam et exercitatam, comes usque quaque parentum fugae; quos quidem apud Neapolim sub inruptionem hostis nauigium clam petentis uagitu suo paene bis prodidit, semel cum a nutricis ubere, iterum cum a sinu matris raptim auferretur ab iis, qui pro necessitate temporis mulierculas leuare onere temptabant. per Siciliam quoque et per Achaiam circumductus ac Lacedaemoniis publice, quod in tutela Claudiorum erant, demandatus, digrediens inde itinere nocturno discrimen uitae adiit flamma repente e siluis undique exorta adeoque omnem comitatum circumplexa, ut Liuiae pars uestis et capilli amburerentur. munera, quibus a Pompeia Sex. Pompei sorore in Sicilia donatus est, chlamys et fibula, item bullae aureae, durant ostendunturque adhuc Bais. post reditum in urbem a M. Gallio senatore testamento adoptatus hereditate adita mox nomine abstinuit, quod Gallius aduersarum Augusto partium fuerat. Nouem natus annos defunctum patrem pro rostris laudauit. dehinc pubescens Actiaco triumpho currum Augusti comitatus est sinisteriore funali equo, cum Marcellus Octauiae filius dexteriore ueheretur. praesedit et asticis ludis et Troiam circensibus lusit ductor turmae puerorum maiorum.", "st": "Tib. 6"}, {"sp": "N", "t": "Virili toga sumpta adulescentiam omnem spatiumque insequentis aetatis usque ad principatus initia per haec fere transegit. munus gladiatorium in memoriam patris et alterum in aui Drusi dedit, diuersis temporibus ac locis, primum in foro, secundum in amphitheatro, rudiaris quoque quibusdam reuocatis auctoramento centenum milium; dedit et ludos, sed absens: cuncta magnifice, inpensa matris ac uitrici. Agrippinam, Marco Agrippa genitam, neptem Caecili Attici equitis R., ad quem sunt Ciceronis epistulae, duxit uxorem; sublatoque ex ea filio Druso, quanquam bene conuenientem rursusque grauidam dimittere ac Iuliam Augusti filiam confestim coactus est ducere non sine magno angore animi, cum et Agrippinae consuetudine teneretur et Iuliae mores improbaret, ut quam sensisset sui quoque sub priore marito appetentem, quod sane etiam uulgo existimabatur. sed Agrippinam et abegisse post diuortium doluit et semel omnino ex occursu uisam adeo contentis et [t]umentibus oculis prosecutus est, ut custoditum sit ne umquam in conspectum ei posthac ueniret. cum Iulia primo concor diter et amore mutuo uixit, mox dissedit et aliquanto grauius, ut etiam perpetuo secubaret, intercepto communis fili pignore, qui Aquileiae natus infans extinctus est. Drusum fratrem in Germania amisit, cuius corpus pedibus toto itinere praegrediens Romam usque peruexit.", "st": "Tib. 7"}, {"sp": "N", "t": "Ciuilium officiorum rudimentis regem Archelaum Trallianos et Thessalos, uaria quosque de causa, Augusto cognoscente defendit; pro Laodicenis Thyatirenis Chiis terrae motu afflictis opemque implorantibus senatum deprecatus est; Fannium Caepionem, qui cum Varrone Murena in Augustum conspirauerat, reum maiestatis apud iudices fecit et condemnauit. interque haec duplicem curam administrauit, annonae quae artior inciderat, et repurgandorum tota Italia ergastulorum, quorum domini in inuidiam uenerant quasi exceptos supprimerent non solum uiatores sed et quos sacramenti metus ad eius modi latebras compulisset.", "st": "Tib. 8"}, {"sp": "N", "t": "Stipendia prima expeditione Cantabrica tribunus militum fecit, dein ducto ad Orientem exercitu regnum Armeniae Tigrani restituit ac pro tribunali diadema imposuit. recepit et signa, quae M. Crasso ademerant Parthi. post hoc Comatam Galliam anno fere rexit et barbarorum incursionibus et principum discordia inquietam. exin Raeticum Vindelicumque bellum, inde Pannonicum, inde Germanicum gessit. Raetico atque Vindelico gentis Alpinas, Pannonico Breucos et Dalmatas subegit, Germanico quadraginta milia dediticiorum traiecit in Galliam iuxtaque ripam Rheni sedibus adsignatis conlocauit. quas ob res et ouans et curru urbem ingressus est, prius, ut quidam putant, triumphalibus ornamentis honoratus, nouo nec antea cuiquam tributo genere honoris. Magistratus et maturius incohauit et paene iunctim percucurrit, quaesturam praeturam consulatum; interpositoque tempore consul iterum etiam tribuniciam potestatem in quinquennium accepit.", "st": "Tib. 9"}, {"sp": "N", "t": "tot prosperis confluentibus integra aetate ac ualitudine statuit repente secedere seque e medio quam longissime amouere: dubium uxorisne taedio, quam neque criminari aut dimittere auderet neque ultra perferre posset, an ut uitato assiduitatis fastidio auctoritatem absentia tueretur atque etiam augeret, si quando indiguisset sui res p. quidam existimant, adultis iam Augusti liberis, loco et quasi possessione usurpati a se diu secundi gradus sponte cessisse exemplo M. Agrippae, qui M. Marcello ad munera publica admoto Mytilenas abierit, ne aut obstare aut obtrectare praesens uideretur. quam causam et ipse, sed postea, reddidit. tunc autem honorum satietatem ac requiem laborum praetendens commeatum petit; neque aut matri suppliciter precanti aut uitrico deseri se etiam in senatu conquerenti ueniam dedit. quin et pertinacius retinentibus, cibo per quadriduum abstinuit. facta tandem abeundi potestate, relictis Romae uxore et filio confestim Ostiam descendit, ne uerbo quidem cuiquam prosequentium reddito paucosque admodum in digressu exosculatus.", "st": "Tib. 10"}, {"sp": "N", "t": "ab Ostia oram Campaniae legens inbecillitate Augusti nuntiata paulum substitit. sed increbrescente rumore quasi ad occasionem maioris spei commoraretur, tantum non aduersis tempestatibus Rhodum enauigauit, amoenitate et salubritate insulae iam inde captus cum ad eam ab Armenia rediens appulisset. hic modicis contentus aedibus nec multo laxiore suburbano genus uitae ciuile admodum instituit, sine lictore aut uiatore gymnasio interdum obambulans mutuaque cum Graeculis officia usurpans prope ex aequo. Forte quondam in disponendo die mane praedixerat, quidquid aegrorum in ciuitate esset uisitare se uelle; id a proximis aliter exceptum iussique sunt omnes aegri in publicam porticum deferri ac per ualitudinum genera disponi. perculsus ergo inopinata re diuque quid ageret incertus, tandem singulos circuit excusans factum etiam tenuissimo cuique et ignoto. unum hoc modo neque praeterea quicquam notatum est, in quo exeruisse ius tribuniciae potestatis uisus sit: cum circa scholas et auditoria professorum assiduus esset, moto inter antisophistas grauiore iurgio, non defuit qui eum interuenientem et quasi studiosiorem partis alterius conuicio incesseret. sensim itaque regressus domum repente cum apparitoribus prodiit citatumque pro tribunali uoce praeconis conuiciatorem rapi iussit in carcerem. Comperit deinde Iuliam uxorem ob libidines atque adulteria damnatam repudiumque ei suo nomine ex auctoritate Augusti remissum; et quamquam laetus nuntio, tamen officii duxit, quantum in se esset, exorare filiae patrem frequentibus litteris et uel utcumque meritae, quidquid umquam dono dedisset, concedere. transacto autem tribuniciae potestatis tempore, confessus tandem, nihil aliud secessu deuitasse se quam aemulationis cum C. Lucioque suspicionem, petit ut sibi securo iam ab hac parte, conroboratis his et secundum locum facile tutantibus, permitteretur reuisere necessitudines, quarum desiderio teneretur. sed neque impetrauit ultroque etiam admonitus est, dimitteret omnem curam suorum, quos tam cupide reliquisset.", "st": "Tib. 11"}, {"sp": "N", "t": "remansit igitur Rhodi contra uoluntatem, uix per matrem consecutus, ut ad uelandam ignominiam quasi legatus Augusto abesset. Enimuero tunc non priuatum modo, sed etiam obnoxium et trepidum egit mediterraneis agris abditus uitansque praeternauigantium officia, quibus frequentabatur assidue, nemine cum imperio aut magistratu tendente quoquam quin deuerteret Rhodum. et accesserunt maioris sollicitudinis causae. namque priuignum Gaium Orienti praepositum, cum uisendi gratia traiecisset Samum, alieniorem sibi sensit ex criminationibus M. Lolli comitis et rectoris eius. uenit etiam in suspicionem per quosdam beneficii sui centuriones a commeatu castra repetentis mandata ad complures dedisse ambigua et quae temptare singulorum animos ad nouas res uiderentur. de qua suspicione certior ab Augusto factus non cessauit efflagitare aliquem cuiuslibet ordinis custodem factis atque dictis suis.", "st": "Tib. 12"}, {"sp": "N", "t": "equi quoque et armorum solitas exercitationes omisit redegitque se deposito patrio habitu ad pallium et crepidas atque in tali statu biennio fere permansit, contemptior in dies et inuisior, adeo ut imagines eius et statuas Nemausenses subuerterint ac familiari quondam conuiuio mentione eius orta extiterit qui Gaio polliceretur, confestim se, si iuberet, Rhodum nauigaturum caputque exulis—sic enim appellabatur—relaturum. quo praecipue non iam metu sed discrimine coactus est, tam suis quam matris inpensissimis precibus reditum expostulare, impetrauitque adiutus aliquantum etiam casu. destinatum Augusto erat, nihil super ea re nisi ex uoluntate maioris fili statuere; is forte tunc M. Lollio offensior, facilis exorabilisque in uitricum fuit. permittente ergo Gaio reuocatus est, uerum sub condicione ne quam partem curamue rei p. attingeret.", "st": "Tib. 13"}, {"sp": "N", "t": "Rediit octauo post secessum anno, magna nec incerta spe futurorum, quam et ostentis et praedictionibus ab initio aetatis conceperat. Praegnans eo Liuia cum an marem editura esset, uariis captaret ominibus, ouum incubanti gallinae subductum nunc sua nunc ministrarum manu per uices usque fouit, quoad pullus insigniter cristatus exclusus est. ac de infante Scribonius mathematicus praeclara spopondit, etiam regnaturum quandoque, sed sine regio insigni, ignota scilicet tunc adhuc Caesarum potestate. et ingresso primam expeditionem ac per Macedoniam ducente exercitum in Syriam, accidit ut apud Philippos sacratae olim uictricium legionum arae sponte subitis conlucerent ignibus; et mox, cum Illyricum petens iuxta Patauium adisset Geryonis oraculum, sorte tracta, qua monebatur ut de consultationibus in Aponi fontem talos aureos iaceret, euenit ut summum numerum iacti ab eo ostenderent; hodieque sub aqua uisuntur hi tali. ante paucos uero quam reuocaretur dies aquila numquam antea Rhodi conspecta in culmine domus eius assedit; et pridie quam de reditu certior fieret, uestimenta mutanti tunica ardere uisa est. Thrasyllum quoque mathematicum, quem ut sapientiae professorem contubernio admouerat, tum maxime expertus est affirmantem naue prouisa gaudium afferri; cum quidem illum durius et contra praedicta cadentibus rebus ut falsum et secretorum temere conscium, eo ipso momento, dum spatiatur una, praecipitare in mare destinasset.", "st": "Tib. 14"}, {"sp": "N", "t": "Romam reuersus deducto in forum filio Druso statim e Carinis ac Pompeiana domo Esquilias in hortos Maecenatianos transmigrauit totumque se ad quietem contulit, priuata modo officia obiens ac publicorum munerum expers. Gaio et Lucio intra triennium defunctis adoptatur ab Augusto simul cum fratre eorum M. Agrippa, coactus prius ipse Germanicum fratris sui filium adoptare. nec quicquam postea pro patre familias egit aut ius, quod amiserat, ex ulla parte retinuit. nam neque donauit neque manumisit, ne hereditatem quidem aut legata percepit ulla aliter quam ut peculio referret accepta. nihil ex eo tempore praetermissum est ad maiestatem eius augendam ac multo magis, postquam Agrippa abdicato atque seposito certum erat, uni spem successionis incumbere;", "st": "Tib. 15"}, {"sp": "N", "t": "data rursus potestas tribunicia in quinquennium, delegatus pacandae Germaniae status, Parthorum legati mandatis Augusto Romae redditis eum quoque adire in prouincia iussi. sed nuntiata Illyrici defectione transiit ad curam noui belli, quod grauissimum omnium externorum bellorum post Punica, per quindecim legiones paremque auxiliorum copiam triennio gessit in magnis omnium rerum difficultatibus summaque frugum inopia. et quanquam saepius reuocaretur, tamen perseuerauit, metuens ne uicinus et praeualens hostis instaret ultro cedentibus. ac perseuerantiae grande pretium tulit, toto Illyrico, quod inter Italiam regnumque Noricum et Thraciam et Macedoniam interque Danuuium flumen et sinum maris Hadriatici patet, perdomito et in dicionem redacto.", "st": "Tib. 16"}, {"sp": "N", "t": "cui gloriae amplior adhuc ex oportunitate cumulus accessit. nam sub id fere tempus Quintilius Varus cum tribus legionibus in Germania periit, nemine dubitante quin uictores Germani iuncturi se Pannoniis fuerint, nisi debellatum prius Illyricum esset. quas ob res triumphus ei decretus est multique et magni honores. censuerunt etiam quidam ut Pannonicus, alii ut Inuictus, nonnulli ut Pius cognominaretur. sed de cognomine intercessit Augustus, eo contentum repromittens, quod se defuncto suscepturus esset. triumphum ipse distulit maesta ciuitate clade Variana; nihilo minus urbem praetextatus et laurea coronatus intrauit positumque in Saeptis tribunal senatu astante conscendit ac medius inter duos consules cum Augusto simul sedit; unde populo consalutato circum templa deductus est.", "st": "Tib. 17"}, {"sp": "N", "t": "Proximo anno repetita Germania cum animaduerteret Varianam cladem temeritate et neglegentia ducis accidisse, nihil non de consilii sententia egit; semper alias sui arbitrii contentusque se uno, tunc praeter consuetudinem cum compluribus de ratione belli communicauit. curam quoque solito exactiorem praestitit. traiecturus Rhenum commeatum omnem ad certam formulam adstrictum non ante transmisit, quam consistens apud ripam explorasset uehiculorum onera, ne qua deportarentur nisi concessa aut necessaria. trans Rhenum uero eum uitae ordinem tenuit, ut sedens in caespite nudo cibum caperet, saepe sine tentorio pernoctaret, praecepta sequentis diei omnia, et si quid subiti muneris iniungendum esset, per libellos daret; addita monitione ut, de quo quisque dubitaret, se nec alio interprete quacumque uel noctis hora uteretur.", "st": "Tib. 18"}, {"sp": "N", "t": "disciplinam acerrime exegit animaduersionum et ignominiarum generibus ex antiquitate repetitis atque etiam legato legionis, quod paucos milites cum liberto suo trans ripam uenatum misisset, ignominia notato. proelia, quamuis minimum fortunae casibusque permitteret, aliquanto constantius inibat, quotiens lucubrante se subito ac nullo propellente decideret lumen et extingueretur, confidens, ut aiebat, ostento sibi a maioribus suis in omni ducatu expertissimo. sed re prospere gesta non multum afuit quin a Bructero quodam occideretur, cui inter proximos uersanti et trepidatione detecto tormentis expressa confessio est cogitati facinoris.", "st": "Tib. 19"}, {"sp": "N", "t": "a Germania in urbem post biennium regressus triumphum, quem distulerat, egit prosequentibus etiam legatis, quibus triumphalia ornamenta impetrarat. ac prius quam in Capitolium flecteret, descendit e curru seque praesidenti patri ad genua summisit. Batonem Pannonium ducem ingentibus donatum praemiis Rauennam transtulit, gratiam referens, quod se quondam cum exercitu iniquitate loci circumclusum passus esset euadere. prandium dehinc populo mille mensis et congiarium trecenos nummos uiritim dedit. dedicauit et Concordiae aedem, item Pollucis et Castoris suo fratrisque nomine de manubiis.", "st": "Tib. 20"}, {"sp": "N", "t": "ac non multo post lege per consules lata, ut prouincias cum Augusto communiter administraret simulque censum a[u]geret, condito lustro in Illyricum profectus est. et statim ex itinere reuocatus iam quidem adfectum, sed tamen spirantem adhuc Augustum repperit fuitque una secreto per totum diem. Scio uulgo persuasum quasi egresso post secretum sermonem Tiberio uox Augusti per cubicularios excepta sit: 'miserum populum R., qui sub tam lentis maxillis erit.' ne illud quidem ignoro aliquos tradidisse, Augustum palam nec dissimulanter morum eius diritatem adeo improbasse, ut nonnumquam remissiores hilarioresque sermones superueniente eo abrumperet; sed expugnatum precibus uxoris adoptionem non abnuisse, uel etiam ambitione tractum, ut tali successore desiderabilior ipse quandoque fieret. adduci tamen nequeo quin existimem, circumspectissimum et prudentissimum principem in tanto praesertim negotio nihil temere fecisse; sed uitiis Tiberi[i] uirtutibusque perpensis potiores duxisse uirtutes, praesertim cum et rei p. causa adoptare se eum pro contione iurauerit et epistulis aliquot ut peritissimum rei militaris utque unicum p. R. praesidium prosequatur. ex quibus in exemplum pauca hinc inde subieci. 'Vale, iucundissime Tiberi, et feliciter rem gere, ἐμοὶ καὶ †μουισασαιστ στρατηγῶν. iucundissime et ita sim felix, uir fortissime et dux νομιμώτατε, uale. Ordinem aestiuorum tuorum ego uero …, mi Tiberi, et inter tot rerum difficultates καὶ[ε]ίαν τῶν στρατευομένων non potuisse quemquam prudentius gerere se quam tu gesseris, existimo. [h]ii quoque qui tecum fuerunt omnes confitentur, uersum illum in te posse dici:<br>unus homo nobis uigilando restituit rem.<br>Siue quid incidit de quo sit cogitandum diligentius, siue quid stomachor, ualde medius Fidius Tiberium meum desidero succurritque uersus ille Homericus:<br>τούτου γ' ἑσπομένοιο καὶ ἐκ πυρὸς αἰθομένοιο<br>ἄμφω νοστήσαιμεν, ἐπεὶ περίοιδε νοῆσαι.<br>Attenuatum te esse continuatione laborum cum audio et lego, di me perdant nisi cohorrescit corpus meum; teque oro ut parcas tibi, ne si te languere audierimus, et ego et mater tua expiremus et summa imperi sui populus R. periclitetur. Nihil interest ualeam ipse necne, si tu non ualebis. Deos obsecro, ut te nobis conseruent et ualere nunc et semper patiantur, si non p. R. perosi sunt.'", "st": "Tib. 21"}, {"sp": "N", "t": "Excessum Augusti non prius palam fecit, quam Agrippa iuuene interempto. hunc tribunus militum custos appositus occidit lectis codicillis, quibus ut id faceret iubebatur; quos codicillos dubium fuit, Augustusne moriens reliquisset, quo materiam tumultus post se subduceret; an nomine Augusti Liuia et ea conscio Tiberio an ignaro, dictasset. Tiberius renuntianti tribuno, factum esse quod imperasset, neque imperasse se et redditurum eum senatui rationem respondit, inuidiam scilicet in praesentia uitans. nam mox silentio rem obliterauit.", "st": "Tib. 22"}, {"sp": "N", "t": "iure autem tribuniciae potestatis coacto senatu incohataque adlocutione derepente uelut impar dolori congemuit, utque non solum uox sed et spiritus deficeret optauit ac perlegendum librum Druso filio tradidit. inlatum deinde Augusti testamentum, non admissis signatoribus nisi senatorii ordinis, ceteris extra curiam signa agnoscentibus, recitauit per libertum. testamenti initium fuit: 'quoniam atrox fortuna Gaium et Lucium filios mihi eripuit, Tiberius Caesar mihi ex parte dimidia et sextante heres esto.' quo et ipso aucta suspicio est opinantium successorem ascitum eum necessitate magis quam iudicio, quando ita praefari non abstinuerit.", "st": "Tib. 23"}, {"sp": "N", "t": "Principatum, quamuis neque occupare confestim neque agere dubitasset, et statione militum, hoc est ui et specie dominationis assumpta, diu tamen recusauit, impudentissimo mimo nunc adhortantis amicos increpans ut ignaros, quanta belua esset imperium, nunc precantem senatum et procumbentem sibi ad genua ambiguis responsis et callida cunctatione suspendens, ut quidam patientiam rumperent atque unus in tumultu proclamaret: 'aut agat aut desistat!' alter coram exprobraret ceteros, quod polliciti sint tarde praestare, sed ipsum, quod praestet tarde polliceri. tandem quasi coactus et querens miseram et onerosam iniungi sibi seruitutem, recepit imperium; nec tamen aliter, quam ut depositurum se quandoque spem faceret. ipsius uerba sunt: 'dum ueniam ad id tempus, quo uobis aequum possit uideri dare uos aliquam senectuti meae requiem.'", "st": "Tib. 24"}, {"sp": "N", "t": "Cunctandi causa erat metus undique imminentium discriminum, ut saepe lupum se auribus tenere diceret. nam et seruus Agrippae Clemens nomine non contemnendam manum in ultionem domini compararat et L. Scribonius Libo uir nobilis res nouas clam moliebatur et duplex seditio militum in Illyrico et in Germania exorta est. flagitabant ambo exercitus multa extra ordinem, ante omnia ut aequarentur stipendio praetorianis. Germaniciani quidem etiam principem detractabant non a se datum summaque ui Germanicum, qui tum iis praeerat, ad capessendam rem p. urgebant, quanquam obfirmate resistentem. quem maxime casum timens, partes sibi quas senatui liberet, tuendas in re p. depoposcit, quando uniuersae sufficere solus nemo posset nisi cum altero uel etiam cum pluribus. simulauit et ualitudinem, quo aequiore animo Germanicus celerem successionem uel certe societatem principatus opperiretur. compositis seditionibus Clementem quoque fraude deceptum redegit in potestatem. Libonem, ne quid in nouitate acerbius fieret, secundo demum anno in senatu coarguit, medio temporis spatio tantum cauere contentus; nam et inter pontifices sacrificanti simul pro secespita plumbeum cultrum subiciendum curauit et secretum petenti non nisi adhibito Druso filio dedit dextramque obambulantis ueluti incumbens, quoad perageretur sermo, continuit.", "st": "Tib. 25"}, {"sp": "N", "t": "Verum liberatus metu ciuilem admodum inter initia ac paulo minus quam priuatum egit. ex plurimis maximisque honoribus praeter paucos et modicos non recepit. natalem suum plebeis incurrentem circensibus uix unius bigae adiectione honorari passus est. templa, flamines, sacerdotes decerni sibi prohibuit, etiam statuas atque imagines nisi permittente se poni; permisitque ea sola condicione, ne inter simulacra deorum sed inter ornamenta aedium ponerentur. intercessit et quo minus in acta sua iuraretur, et ne mensis September Tiberius, October Liuius uocarentur. praenomen quoque imperatoris cognomenque patris patriae et ciuicam in uestibulo coronam recusauit; ac ne Augusti quidem nomen, quanquam hereditarium, nullis nisi ad reges ac dynastas epistulis addidit. nec amplius quam mox tres consulatus, unum paucis diebus, alterum tribus mensibus, tertium absens usque in Idus Maias gessit.", "st": "Tib. 26"}, {"sp": "N", "t": "Adulationes adeo auersatus est, ut neminem senatorum aut officii aut negotii causa ad lecticam suam admiserit, consularem uero satisfacientem sibi ac per genua orare conantem ita suffugerit, ut caderet supinus; atque etiam, si quid in sermone uel in continua oratione blandius de se diceretur, non dubitaret interpellare ac reprehendere et commutare continuo. dominus appellatus a quodam denuntiauit, ne se amplius contumeliae causa nominaret. alium dicentem sacras eius occupationes et rursus alium, auctore eo senatum se a[u]disse, uerba mutare et pro auctore suasorem, pro sacris laboriosas dicere coegit.", "st": "Tib. 27"}, {"sp": "N", "t": "sed et aduersus conuicia malosque rumores et famosa de se ac suis carmina firmus ac patiens subinde iactabat in ciuitate libera linguam mentemque liberas esse debere; et quondam senatu cognitionem de eius modi criminibus ac reis flagitante: 'non tantum,' inquit, 'otii habemus, ut implicare nos pluribus negotiis debeamus; si hanc fenestram aperueritis, nihil aliud agi sinetis: omnium inimicitiae hoc praetexto ad uos deferentur.' extat et sermo eius in senatu perciuilis: 'siquidem locutus aliter fuerit, dabo operam ut rationem factorum meorum dictorumque reddam; si perseuerauerit, in uicem eum odero.'", "st": "Tib. 28"}, {"sp": "N", "t": "Atque haec eo notabiliora erant, quod ipse in appellandis uenerandisque et singulis et uniuersis prope excesserat humanitatis modum. dissentiens in curia a Q. Haterio: 'ignoscas,' inquit, 'rogo, si quid aduersus te liberius sicut senator dixero.' et deinde omnis adloquens: 'dixi et nunc et saepe alias, p. c., bonum et salutarem principem, quem uos tanta et tam libera potestate instruxistis, senatui seruire debere et uniuersis ciuibus saepe et plerumque etiam singulis; neque id dixisse me paenitet, et bonos et aequos et fauentes uos habui dominos et adhuc habeo.'", "st": "Tib. 29"}, {"sp": "N", "t": "Quin etiam speciem libertatis quandam induxit conseruatis senatui ac magistratibus et maiestate pristina et potestate. neque tam paruum quicquam neque tam magnum publici priuatique negotii fuit, de quo non ad patres conscriptos referretur: de uectigalibus ac monopoliis, de extruendis reficiendisue operibus, etiam de legendo uel exauctorando milite ac legionum et auxiliorum discriptione, denique quibus imperium prorogari aut extraordinaria bella mandari, quid et qua[m] forma[m] regum litteris rescribi placeret. praefectum alae de ui et rapinis reum causam in senatu dicere coegit. numquam curiam nisi solus intrauit; lectica quondam intro latus aeger comites a se remouit.", "st": "Tib. 30"}, {"sp": "N", "t": "quaedam aduersus sententiam suam decerni ne questus quidem est. negante eo destinatos magistratus abesse oportere, ut praesentes honori adquiescerent, praetor designatus liberam legationem impetrauit. iterum censente, ut Trebianis legatam in opus noui theatri pecuniam ad munitionem uiae transferre concederetur, optinere non potuit quin rata uoluntas legatoris esset. cum senatus consultum per discessionem forte fieret, transeuntem eum in alteram partem, in qua pauciores erant, secutus est nemo. Cetera quoque non nisi per magistratus et iure ordinario agebantur, tanta consulum auctoritate, ut legati ex Africa adierint eos querentes, trahi se a Caesare ad quem missi forent. nec mirum, cum palam esset, ipsum quoque eisdem et assurgere et decedere uia.", "st": "Tib. 31"}, {"sp": "N", "t": "corripuit consulares exercitibus praepositos, quod non de rebus gestis senatui scriberent quodque de tribuendis quibusdam militaribus donis ad se referrent, quasi non omnium tribuendorum ipsi ius haberent. praetorem conlaudauit, quod honore inito consuetudinem antiquam rettulisset de maioribus suis pro contione memorandi. quorundam illustrium exequias usque ad rogum frequentauit. Parem moderationem minoribus quoque et personis et rebus exhibuit. cum Rhodiorum magistratus, quod litteras publicas sine subscriptione ad se dederant, euocasset, ne uerbo quidem insectatus ac tantum modo iussos subscribere remisit. Diogenes grammaticus, disputare sabbatis Rhodi solitus, uenientem eum, ut se extra ordinem audiret, non admiserat ac per seruolum suum in septimum diem distulerat; hunc Romae salutandi sui causa pro foribus adstantem nihil amplius quam ut post septimum annum rediret admonuit. praesidibus onerandas tributo prouincias suadentibus rescripsit boni pastoris esse tondere pecus, non deglubere.", "st": "Tib. 32"}, {"sp": "N", "t": "Paulatim principem exeruit praestititque etsi uarium diu, commodiorem tamen saepius et ad utilitates publicas proniorem. ac primo eatenus interueniebat, ne quid perperam fieret. itaque et constitutiones senatus quasdam rescidit et magistratibus pro tribunali cognoscentibus plerumque se offerebat consiliarium assidebatque iuxtim uel exaduersum in parte primori; et si quem reorum elabi gratia rumor esset, subitus aderat iudices que aut e plano aut e quaesitoris tribunali legum et religionis et noxae, de qua cognoscerent, admonebat; atque etiam, si qua in publicis moribus desidia aut mala consuetudine labarent, corrigenda suscepit.", "st": "Tib. 33"}, {"sp": "N", "t": "ludorum ac munerum impensas corripuit mercedibus scaenicorum recisis paribusque gladiatorum ad certum numerum redactis. Corinthiorum uasorum pretia in immensum exarsisse tresque mullos triginta milibus nummum uenisse grauiter conquestus, adhibendum supellectili modum censuit annonamque macelli senatus arbitratu quotannis temperandam, dato aedilibus negotio popinas ganeasque usque eo inhibendi, ut ne opera quidem pistoria proponi uenalia sinerent. et ut parsimoniam publicam exemplo quoque iuuaret, sollemnibus ipse cenis pridiana saepe ac semesa obsonia apposuit dimidiatumque aprum, affirmans omnia eadem habere, quae totum. Cotidiana oscula edicto prohibuit, item strenarum commercium ne ultra Kal. Ian. exerceretur. consuerat quadriplam stren[u]am, et de manu, reddere; sed offensus interpellari se toto mense ab iis qui potestatem sui die festo non habuissent, ultra non tulit.", "st": "Tib. 34"}, {"sp": "N", "t": "matronas prostratae pudicitiae, quibus accusator publicus deesset, ut propinqui more maiorum de communi sententia coercerent auctor fuit. eq(uiti) R(omano) iuris iurandi gratiam fecit, uxorem in stupro generi compertam dimitteret, quam se numquam repudiaturum ante iurauerat. feminae famosae, ut ad euitandas legum poenas iure ac dignitate matronali exoluerentur, lenocinium profiteri coeperant, et ex iuuentute utriusque ordinis profligatissimus quisque, quominus in opera scaenae harenaeque edenda senatus consulto teneretur, famosi iudicii notam sponte subibant; eos easque omnes, ne quod refugium in tali fraude cuiquam esset, exilio adfecit. senatori latum clauum ademit, cum cognosset sub Kal. Iul. demigrasse in hortos, quo uilius post diem aedes in urbe conduceret. alium e quaestura remouit, quod uxorem pridie sortitionem ductam postridie repudiasset.", "st": "Tib. 35"}, {"sp": "N", "t": "externas caerimonias, Aegyptios Iudaicosque ritus compescuit, coactis qui superstitione ea tenebantur religiosas uestes cum instrumento omni comburere. Iudaeorum iuuentutem per speciem sacramenti in prouincias grauioris caeli distribuit, reliquos gentis eiusdem uel similia sectantes urbe summouit, sub poena perpetuae seruitutis nisi obtemperassent. expulit et mathematicos, sed deprecantibus ac se artem desituros promittentibus ueniam dedit.", "st": "Tib. 36"}, {"sp": "N", "t": "In primis tuendae pacis a grassaturis ac latrociniis seditionumque licentia curam habuit. stationes militum per Italiam solito frequentiores disposuit. Romae castra constituit, quibus praetorianae cohortes uagae ante id tempus et per hospitia dispersae continerentur. Populares tumultus et ortos grauissime coercuit et ne orerentur sedulo cauit. caede in theatro per discordiam admissa capita factionum et histriones, propter quos dissidebatur, relegauit, nec ut reuocaret umquam ullis populi precibus potuit euinci. cum Pollentina plebs funus cuiusdam primipilaris non prius ex foro misisset quam extorta pecunia per uim heredibus ad gladiatorium munus, cohortem ab urbe et aliam a Cotti regno dissimulata itineris causa detectis repente armis concinentibusque signis per diuersas portas in oppidum immisit ac partem maiorem plebei ac decurionum in perpetua uincula coiecit. aboleuit et ius moremque asylorum, quae usquam erant. Cyzicenis in ciues R. uiolentius quaedam ausis publice libertatem ademit, quam Mithridatico bello meruerant. Hostiles motus nulla postea expeditione suscepta per legatos compescuit, ne per eos quidem nisi cunctanter et necessario. reges infestos suspectosque comminationibus magis et querelis quam ui repressit; quosdam per blanditias atque promissa extractos ad se non remisit, ut Marobodum Germanum, [t]Rhascuporim Thracem, Archelaum Cappadocem, cuius etiam regnum in formam prouinciae redegit.", "st": "Tib. 37"}, {"sp": "N", "t": "Biennio continuo post adeptum imperium pedem porta non extulit; sequenti tempore praeterquam in propinqua oppida et, cum longissime, Antio tenus nusquam afuit, idque perraro et paucos dies; quamuis prouincias quoque et exercitus reuisurum se saepe pronuntiasset et prope quotannis profectionem praepararet, uehiculis comprehensis, commeatibus per municipia et colonias dispositis, ad extremum uota pro itu et reditu suo suscipi passus, ut uulgo iam per iocum 'Callippides' uocaretur, quem cursitare ac ne cubiti quidem mensuram progredi prouerbio Graeco notatum est.", "st": "Tib. 38"}, {"sp": "N", "t": "sed orbatus utroque filio, quorum Germanicus in Syria, Drusus Romae obierat, secessum Campaniae petit; constanti et opinione et sermone paene omnium quasi neque rediturus umquam et cito mortem etiam obiturus. quod paulo minus utrumque euenit; nam neque Romam amplius rediit [s]et paucos post dies iuxta Tarracinam in praetorio, cui Speluncae nomen est, incenante eo complura et ingentia saxa fortuito superne dilapsa sunt, multisque conuiuarum et ministrorum elisis praeter spem euasit.", "st": "Tib. 39"}, {"sp": "N", "t": "Peragrata Campania, cum Capuae Capitolium, Nolae templum Augusti, quam causam profectionis praetenderat, dedicasset, Capreas se contulit, praecipue delectatus insula, quod uno paruoque litore adiretur, saepta undique praeruptis immensae altitudinis rupibus et profundo mari[s]. statimque reuocante assidua obtestatione populo propter cladem, qua apud Fidenas supra uiginti hominum milia gladiatorio munere amphitheatri ruina perierant, transiit in continentem potestatemque omnibus adeundi sui fecit: tanto magis, quod urbe egrediens ne quis se interpellaret edixerat ac toto itinere adeuntis submouerat.", "st": "Tib. 40"}, {"sp": "N", "t": "Regressus in insulam rei p. quidem curam usque adeo abiecit, ut postea non decurias equitum umquam supplerit, non tribunos militum praefectosque, non prouinciarum praesides ullos mutauerit, Hispaniam et Syriam per aliquot annos sine consularibus legatis habuerit, Armeniam a Parthis occupari, Moesiam a Dacis Sarmatisque, Gallias a Germanis uastari neglexerit: magno dedecore imperii nec minore discrimine.", "st": "Tib. 41"}, {"sp": "N", "t": "ceterum secreti licentiam nanctus et quasi ciuitatis oculis remotis, cuncta simul uitia male diu dissimulata tandem profudit: de quibus singillatim ab exordio referam. in castris tiro etiam tum propter nimiam uini auiditatem pro Tiberio 'Biberius,' pro Claudio 'Caldius,' pro Nerone 'Mero' uocabatur. postea princeps in ipsa publicorum morum correctione cum Pomponio Flacco et L. Pisone noctem continuumque biduum epulando potandoque consumpsit, quorum alteri Syriam prouinciam, alteri praefecturam urbis confestim detulit, codicillis quoque iucundissimos et omnium horarum amicos professus. Cestio Gall[i]o, libidinoso ac prodigo seni, olim ab Augusto ignominia notato et a se ante paucos dies apud senatum increpito cenam ea lege condixit, ne quid ex consuetudine immutaret aut demeret, utque nudis puellis ministrantibus cenaretur. ignotissimum quaesturae candidatum nobilissimis anteposuit ob epotam in conuiuio propinante se uini amphoram. Asellio Sabino sestertia ducenta donauit pro dialogo, in quo boleti et ficedulae et ostreae et turdi certamen induxerat. nouum denique officium instituit a uoluptatibus, praeposito equite R. T. Caesonio Prisco.", "st": "Tib. 42"}, {"sp": "N", "t": "secessu uero Caprensi etiam sellaria excogitauit, sedem arcanarum libidinum, in quam undique conquisiti puellarum et exoletorum greges monstrosique concubitus repertores, quos spintrias appellabat, triplici serie conexi, in uicem incestarent coram ipso, ut aspectu deficientis libidines excitaret. cubicula plurifariam disposita tabellis ac sigillis lasciuissimarum picturarum et figurarum adornauit librisque Elephantidis instruxit, ne cui in opera edenda exemplar impe[t]ratae schemae deesset. in siluis quoque ac nemoribus passim Venerios locos commentus est prost[r]antisque per antra et cauas rupes ex utriusque sexus pube Paniscorum et Nympharum habitu, quae palam iam et uulgo nomine insulae abutentes 'Caprineum' dictitabant.", "st": "Tib. 43"}, {"sp": "N", "t": "Maiore adhuc ac turpiore infamia flagrauit, uix ut referri audiriue, nedum credi fas sit, quasi pueros primae teneritudinis, quos pisciculos uocabat, institueret, ut natanti sibi inter femina uersarentur ac luderent lingua morsuque sensim adpetentes; atque etiam quasi infantes firmiores, necdum tamen lacte depulsos, inguini ceu papillae admoueret, pronior sane ad id genus libidinis et natura et aetate. quare Parrasi quoque tabulam, in qua Meleagro Atalanta ore morigeratur, legatam sibi sub condicione, ut si argumento offenderetur decies pro ea sestertium acciperet, non modo praetulit, sed et in cubiculo dedicauit. fertur etiam in sacrificando quondam captus facie ministri acerram praeferentis nequisse abstinere, quin paene uixdum re diuina peracta ibidem statim seductum constupraret simulque fratrem eius tibicinem; atque utrique mox, quod mutuo flagitium exprobrarant, crura fregisse.", "st": "Tib. 44"}, {"sp": "N", "t": "feminarum quoque, et quidem illustrium, capitibus quanto opere solitus sit inludere, euidentissime apparuit Malloniae cuiusdam exitu, quam perductam nec quicquam amplius pati constantissime recusantem delatoribus obiecit ac ne ream quidem interpellare desiit, 'ecquid paeniteret'; donec ea relicto iudicio domum se abripuit ferroque transegit, obscaenitate[m] oris hirsuto atque olido seni clare exprobrata. unde mora in Atellanico exhodio proximis ludis adsensu maximo excepta percrebruit, 'hircum uetulum capreis naturam ligurire.'", "st": "Tib. 45"}, {"sp": "N", "t": "Pecuniae parcus ac tenax comites peregrinationum expeditionumque numquam salario, cibariis tantum sustentauit, una modo liberalitate ex indulgentia uitrici prosecutus, cum tribus classibus factis pro dignitate cuiusque, primae sescenta sestertia, secundae quadringenta distribuit, ducenta tertiae, quam non amicorum sed Graecorum appellabat.", "st": "Tib. 46"}, {"sp": "N", "t": "Princeps neque opera ulla magnifica fecit—nam et quae sola susceperat, Augusti templum restitutionemque Pompeiani theatri, imperfecta post tot annos reliquit—neque spectacula omnino edidit; et iis, quae ab aliquo ederentur, rarissime interfuit, ne quid exposceretur, utique postquam comoedum Actium coactus est manumittere. paucorum senatorum inopia sustentata, ne pluribus opem ferret, negauit se aliis subuenturum, nisi senatui iustas necessitatium causas probassent. quo pacto plerosque modestia et pudore deterruit, in quibus Hortalum, Quinti Hortensi oratoris nepotem, qui permodica re familiari auctore Augusto quattuor liberos tulerat.", "st": "Tib. 47"}, {"sp": "N", "t": "Publice munificentiam bis omnino exhibuit, proposito milies sestertium gratuito in trienni tempus et rursus quibusdam dominis insularum, quae in monte Caelio deflagrarant, pretio restituto. quorum alterum magna difficultate nummaria populo auxilium flagitante coactus est facere, cum per senatus consultum sanxisset, ut faeneratores duas patrimonii partes in solo collocarent, debitores totidem aeris alieni statim soluerent, nec res expediretur; alterum ad mitigandam temporum atrocitatem. quod tamen beneficium tanti aestimauit, ut montem Caelium appellatione mutata uocari Augustum iusserit. militi post duplicata ex Augusti testamento legata nihil umquam largitus est, praeterquam singula milia denariorum praetorianis, quod Seiano se non accommodassent, et quaedam munera Syriacis legionibus, quod solae nullam Seiani imaginem inter signa coluissent. atque etiam missiones ueteranorum rarissimas fecit, ex senio mortem, ex morte compendium captans. ne prouincias quidem liberalitate ulla subleuauit, excepta Asia, disiectis terrae motu ciuitatibus.", "st": "Tib. 48"}, {"sp": "N", "t": "Procedente mox tempore etiam ad rapinas conuertit animum. satis constat, Cn. Lentulum Augurem, cui census maximus fuerit, metu et angore ad fastidium uitae ab eo actum et ut ne quo nisi ipso herede moreretur; condemnatam et generosissimam feminam Lepidam in gratiam Quirini consularis praediuitis et orbi, qui dimissam eam e matrimonio post uicensimum annum ueneni olim in se comparati arguebat; praeterea Galliarum et Hispaniarum Syriaeque et Graeciae principes confiscatos ob tam leue ac tam inpudens calumniarum genus, ut quibusdam non aliud sit obiectum, quam quod partem rei familiaris in pecunia haberent; plurimis etiam ciuitatibus et priuatis ueteres immunitates et ius metallorum ac uectigalium adempta; sed et Vononem regem Parthorum, qui pulsus a suis quasi in fidem p. R. cum ingenti gaza Antiochiam se receperat. spoliatum perfidia et occisum.", "st": "Tib. 49"}, {"sp": "N", "t": "Odium aduersus necessitudines in Druso primum fratre detexit, prodita eius epistula, qua secum de cogendo ad restituendam libertatem Augusto agebat, deinde et in reliquis. Iuliae uxori tantum afuit ut relegatae, quod minimum est, offici aut humanitatis aliquid impertiret, ut ex constitutione patris uno oppido clausam domo quoque egredi et commercio hominum frui uetuerit; sed et peculio concesso a patre praebitisque annuis fraudauit, per speciem publici iuris, quod nihil de his Augustus testamento cauisset. matrem Liuiam grauatus uelut partes sibi aequas potentiae uindicantem, et congressum eius assiduum uitauit et longiores secretioresque sermones, ne consiliis, quibus tamen interdum et egere et uti solebat, regi uideretur. tulit etiam perindigne actum in senatu, ut titulis suis quasi Augusti, ita et 'Liuiae filius' adiceretur. quare non 'parentem patriae' appellari, non ullum insignem honorem recipere publice passus est; sed et frequenter admonuit, maioribus nec feminae conuenientibus negotiis abstineret, praecipue ut animaduertit incendio iuxta aedem Vestae et ipsam interuenisse populumque et milites, quo enixius opem ferrent, adhortatam, sicut sub marito solita esset.", "st": "Tib. 50"}, {"sp": "N", "t": "dehinc ad simultatem usque processit hac, ut ferunt, de causa. instanti saepius, ut ciuitate donatum in decurias adlegeret, negauit alia se condicione adlecturum, quam si pateretur ascribi albo extortum id sibi a matre. at illa commota ueteres quosdam ad se Augusti codicillos de acerbitate et intolerantia morum eius e sacrario protulit atque recitauit. hos et custoditos tam diu et exprobratos tam infeste adeo grauiter tulit, ut quidam putent inter causas secessus hanc ei uel praecipuam fuisse. toto quidem triennio, quo uiuente matre afuit, semel omnino eam nec amplius quam uno die paucissimis uidit horis; ac mox neque aegrae adesse curauit defunctamque et, dum aduentus sui spem facit, complurium dierum mora corrupto demum et tabido corpore funeratam prohibuit consecrari, quasi id ipsa mandasset. testamentum quoque eius pro irrito habuit omnisque amicitias et familiaritates, etiam quibus ea funeris sui curam moriens demandauerat, intra breue tempus afflixit, uno ex iis, equestris ordinis uiro, et in antliam condemnato.", "st": "Tib. 51"}, {"sp": "N", "t": "Filiorum neque naturalem Drusum neque adoptiuum Germanicum patria caritate dilexit, alterius uitiis infensus. nam Drusus fluxioris remissiorisque uitae erat. itaque ne mortuo quidem perinde adfectus est, sed tantum non statim a funere ad negotiorum consuetudinem rediit iustitio longiore inhibito. quin et Iliensium legatis paulo serius consolantibus, quasi obliterata iam doloris memoria, irridens se quoque respondit uicem eorum dolere, quod egregium ciuem Hectorem amisissent. Germanico usque adeo obtrectauit, ut et praeclara facta eius pro superuacuis eleuarit et gloriosissimas uictorias ceu damnosas rei p. increparet. quod uero Alexandream propter immensam et repentinam famem inconsulto se adisset, questus est in senatu. etiam causa mortis fuisse ei per Cn. Pisonem legatum Syriae creditur, quem mox huius criminis reum putant quidam mandata prolaturum, nisi ea secreto ostentant … quae multifariam inscriptum et per noctes celeberrime adclamatum est: 'redde Germanicum!' quam suspicionem confirmauit ipse postea coniuge etiam ac liberis Germanici crudelem in modum afflictis.", "st": "Tib. 52"}, {"sp": "N", "t": "Nurum Agrippinam post mariti mortem liberius quiddam questam manu apprehendit Graecoque uersu: 'si non dominaris,' inquit, 'filiola, iniuriam te accipere existimas?' nec ullo mox sermone dignatus est. quondam uero inter cenam porrecta a se poma gustare non ausam etiam uocare desiit, simulans ueneni se crimine accersi; cum praestructum utrumque consulto esset, ut et ipse temptandi gratia offerret et illa quasi certissimum exitium caueret. nouissime calumniatus modo ad statuam Augusti modo ad exercitus confugere uelle, Pandatariam relegauit conuiciantique oculum per centurionem uerberibus excussit. rursus mori inedia destinanti per uim ore diducto infulciri cibum iussit. sed et perseuerantem atque ita absumptam criminosissime insectatus, cum diem quoque natalem eius inter nefastos referendum suasisset, imputauit etiam, quod non laqueo strangulatam in Gemonias abiecerit: proque tali clementia interponi decretum passus est, quo sibi gratiae agerentur et Capitolino Ioui donum ex auro sacraretur.", "st": "Tib. 53"}, {"sp": "N", "t": "Cum ex Germanico tres nepotes, Neronem et Drusum et Gaium, ex Druso unum Tiberium haberet, destitutus morte liberorum maximos natu de Germanici filiis, Neronem et Drusum, patribus conscriptis commendauit diemque utriusque tirocinii congiario plebei dato celebrauit. sed ut comperit ineunte anno pro eorum quoque salute publice uota suscepta, egit cum senatu, non debere talia praemia tribui nisi expertis et aetate prouectis. atque ex eo patefacta interiore animi sui nota omnium criminationibus obnoxios reddidit uariaque fraude inductos, ut et concitarentur ad conuicia et concitati proderentur, accusauit per litteras amarissime congestis etiam probris et iudicatos hostis fame necauit, Neronem in insula Pontia, Drusum in ima parte Palatii. putant Neronem ad uoluntariam mortem coactum, cum ei carnifex quasi ex senatus auctoritate missus laqueos et uncos ostentaret, Druso autem adeo alimenta subducta, ut tomentum e culcita temptauerit mandere; amborum sic reliquias dispersas, ut uix quandoque colligi possent.", "st": "Tib. 54"}, {"sp": "N", "t": "Super ueteres amicos ac familiares uiginti sibi e numero principum ciuitatis depoposcerat uelut consiliarios in negotiis publicis. horum omnium uix duos anne tres incolumis praestitit, ceteros alium alia de causa perculit, inter quos cum plurimorum clade Aelium Seianum; quem ad summam potentiam non tam beniuolentia prouexerat, quam ut esset cuius ministerio ac fraudibus liberos Germanici circumueniret, nepotemque suum ex Druso filio naturalem ad successionem imperii confirmaret.", "st": "Tib. 55"}, {"sp": "N", "t": "Nihilo lenior in conuictores Graeculos, quibus uel maxime adquiescebat, Xenonem quendam exquisitius sermocinantem cum interrogasset, quaenam illa tam molesta dialectos esset, et ille respondisset Doridem, relegauit Cinariam, existimans exprobratum sibi ueterem secessum, quod Dorice Rhodii loquantur. item cum soleret ex lectione cotidiana quaestiones super cenam proponere comperissetque Seleucum grammaticum a ministris suis perquirere, quos quoque tempore tractaret auctores, atque ita praeparatum uenire, primum a contubernio remouit, deinde etiam ad mortem compulit.", "st": "Tib. 56"}, {"sp": "N", "t": "Saeua ac lenta natura ne in puero quidem latuit; quam Theodorus Gadareus rhetoricae praeceptor et perspexisse primus sagaciter et assimilasse aptissime uisus est, subinde in obiurgando appellans eum πηλὸν αἵματι πεφυραμένον, id est lutum a sanguine maceratum. sed aliquanto magis in principe eluxit, etiam inter initia cum adhuc fauorem hominum moderationis simulatione captaret. scurram, qui praetereunte funere clare mortuo mandarat, ut nuntiaret Augusto nondum reddi legata quae plebei reliquisset, adtractum ad se recipere debitum ducique ad supplicium imperauit et patri suo uerum referre. nec multo post in senatu Pompeio cuidam equiti R. quiddam perneganti, dum uincula minatur, affirmauit fore ut ex Pompeio Pompeianus fieret, acerba cauillatione simul hominis nomen incessens ueteremque partium fortunam.", "st": "Tib. 57"}, {"sp": "N", "t": "sub idem tempus consulente praetore an iudicia maiestatis cogi iuberet, exercendas esse leges respondit et atrocissime exercuit. statuae quidam Augusti caput dempserat, ut alterius imponeret; acta res in senatu et, quia ambigebatur, per tormenta quaesita est. damnato reo paulatim genus calumniae eo processit, ut haec quoque capitalia essent: circa Augusti simulacrum seruum cecidisse, uestimenta mutasse, nummo uel anulo effigiem impressam latrinae aut lupanari intulisse, dictum ullum factumue eius existimatione aliqua laesisse. perit denique et is, qui honorem in colonia sua eodem die decerni sibi passus est, quo decreti et Augusto olim erant.", "st": "Tib. 58"}, {"sp": "N", "t": "Multa praeterea specie grauitatis ac morum corrigendorum, sed et magis naturae optemperans, ita saeue et atrociter factitauit, ut nonnulli uersiculis quoque et praesentia exprobrarent et futura denuntiarent mala:<br>Asper et immitis, breuiter uis omnia dicam?<br>dispeream, si te mater amare potest.<br>Non es eques; quare? non sunt tibi milia centum;<br>omnia si quaeras, et Rhodus exilium est.<br>Aurea mutasti Saturni saecula, Caesar:<br>incolumi nam te ferrea semper erunt.<br>Fastidit uinum, quia iam sitit iste cruorem:<br>tam bibit hunc auide, quam bibit ante merum.<br>Aspice felicem sibi, non tibi, Romule, Sullam<br>et Marium, si uis, aspice, sed reducem,<br>nec non Antoni ciuilia bella mouentis<br>non semel infectas aspice caede manus,<br>et dic: Roma perit! regnauit sanguine multo,<br>ad regnum quisquis uenit ab exilio.<br>quae primo, quasi ab impatientibus remediorum ac non tam ex animi sententia quam bile et stomacho fingerentur, uolebat accipi dicebatque identidem: 'oderint, dum probent.' dein uera plane certaque esse ipse fecit fidem.", "st": "Tib. 59"}, {"sp": "N", "t": "In paucis diebus quam Capreas attigit piscatori, qui sibi secretum agenti grandem mullum inopinanter obtulerat, perfricari eodem pisce faciem iussit, territus quod is a tergo insulae per aspera et deuia erepsisset ad se; gratulanti autem inter poenam, quod non et lucustam, quam praegrandem ceperat, obtulisset, lucusta quoque lacerari os imperauit. militem praetorianum ob subreptum e uiridiario pauonem capite puniit. in quodam itinere lectica, qua uehebatur, uepribus impedita exploratorem uiae, primarum cohortium centurionem, stratum humi paene ad necem uerberauit.", "st": "Tib. 60"}, {"sp": "N", "t": "mox in omne genus crudelitatis erupit numquam deficiente materia, cum primo matris, deinde nepotum et nurus, postremo Seiani familiares atque etiam notos persequeretur; post cuius interitum uel saeuissimus extitit. quo maxime apparuit, non tam ipsum ab Seiano concitari solitum, quam Seianum quaerenti occasiones sumministrasse; etsi commentario, quem de uita sua summatim breuiterque composuit, ausus est scribere Seianum se punisse, quod comperisset furere aduersus liberos Germanici filii sui; quorum ipse alterum suspecto iam, alterum oppresso demum Seiano interemit. Singillatim crudeliter facta eius exequi longum est; genera, uelut exemplaria saeuitiae, enumerare sat erit. nullus a poena hominum cessauit dies, ne religiosus quidem ac sacer; animaduersum in quosdam ineunte anno nouo. accusati damnatique multi cum liberis atque etiam a liberis suis. interdictum ne capite damnatos propinqui lugerent. decreta accusatoribus praecipua praemia, nonnumquam et testibus. nemini delatorum fides abrogata. omne crimen pro capitali receptum, etiam paucorum simpliciumque uerborum. obiectum est poetae, quod in tragoedia Agamemnonem probris lacessisset; obiectum et historico, quod Brutum Cassiumque ultimos Romanorum dixisset; animaduersum statim in auctores scriptaque abolita, quamuis probarentur ante aliquot annos etiam Augusto audiente recitata. quibusdam custodiae traditis non modo studendi solacium ademptum, sed etiam sermonis et conloqui usus. citati ad causam dicendam partim se domi uulnerauerunt certi damnationis et ad uexationem ignominiamque uitandam, partim in media curia uenenum hauserunt; et tamen conligatis uulneribus ac semianimes palpitantesque adhuc in carcerem rapti. nemo punitorum non in Gemonias abiectus uncoque tractus, uiginti uno die abiecti tractique, inter eos feminae et pueri. immaturae puellae, quia more tradito nefas esset uirgines strangulari, uitiatae prius a carnifice, dein strangulatae. mori uolentibus uis adhibita uiuendi. nam mortem adeo leue supplicium putabat, ut cum audisset unum e reis, Carnulum nomine, anticipasse eam, exclamauerit: 'Carnulus me euasit.' et in recognoscendis custodiis precanti cuidam poenae maturitatem respondit: 'nondum tecum in gratiam redii.' annalibus suis uir consularis inseruit, frequenti quodam conuiuio, cui et ipse affuerit, interrogatum eum subito et clare a quodam nano astante mensae inter copreas, cur Paconius maiestatis reus tam diu uiueret, statim quidem petulantiam linguae obiurgasse, ceterum post paucos dies scripsisse senatui, ut de poena Paconi quam primum statueret.", "st": "Tib. 61"}, {"sp": "N", "t": "Auxit intenditque saeuitiam exacerbatus indicio de morte filii sui Drusi. quem cum morbo et intemperantia perisse existimaret, ut tandem ueneno interemptum fraude Liuillae uxoris atque Seiani cognouit, neque tormentis neque supplicio cuiusquam pepercit, soli huic cognitioni adeo per totos dies deditus et intentus, ut Rhodiensem hospitem, quem familiaribus litteris Romam euocarat, aduenisse sibi nuntiatum torqueri sine mora iusserit, quasi aliquis ex necessariis quaestioni adesset, deinde errore detecto et occidi, ne uulgaret iniuriam. carnificinae eius ostenditur locus Capreis, unde damnatos post longa et exquisita tormenta praecipitari coram se in mare iubebat, excipiente classiariorum manu et contis atque remis elidente cadauera, ne cui residui spiritus quicquam inesset. excogitauerat autem inter genera cruciatus etiam, ut larga meri potione per fallaciam oneratos, repente ueretris deligatis, fidicularum simul urinaeque tormento distenderet. quod nisi eum et mors praeuenisset et Thrasyllus consulto, ut aiunt, differre quaedam spe longioris uitae compulisset, plures aliquanto necaturus ac ne reliquis quidem nepotibus parsurus creditur, cum et Gaium suspectum haberet et Tiberium ut ex adulterio conceptum aspernaretur. nec abhorret a uero; namque identidem felicem Priamum uocabat, quod superstes omnium suorum extitisset.", "st": "Tib. 62"}, {"sp": "N", "t": "Quam inter haec non modo inuisus ac detestabilis, sed praetrepidus quoque atque etiam contumeliis obnoxius uixerit, multa indicia sunt. haruspices secreto ac sine testibus consuli uetuit. uicina uero urbi oracula etiam dis[s]icere conatus est, sed maiestate Praenestinarum sortium territus destitit, cum obsignatas deuectasque Romam non repperisset in arca nisi relata rursus ad templum. unum et alterum consulares oblatis prouinciis non ausus a se dimittere usque eo detinuit, donec successores post aliquot annos praesentibus daret, cum interim manente officii titulo etiam delegaret plurima assidue, quae illi per legatos et adiutores suos exequenda curarent.", "st": "Tib. 63"}, {"sp": "N", "t": "nurum ac nepotes numquam aliter post damnationem quam catenatos obsutaque lectica loco mouit, prohibitis per militem obuiis ac uiatoribus respicere usquam uel consistere.", "st": "Tib. 64"}, {"sp": "N", "t": "Seianum res nouas molientem, quamuis iam et natalem eius publice celebrari et imagines aureas coli passim uideret, uix tandem et astu magis ac dolo quam principali auctoritate subuertit. nam primo, ut a se per speciem honoris dimitteret, collegam sibi assumpsit in quinto consulatu, quem longo interuallo absens ob id ipsum susceperat. deinde spe affinitatis ac tribuniciae potestatis deceptum inopinantem criminatus est pudenda miserandaque oratione, cum inter alia patres conscriptos precaretur, mitterent alterum e consulibus, qui se senem et solum in conspectum eorum cum aliquo militari praesidio perduceret. sic quoque diffidens tumultumque metuens Drusum nepotem, quem uinculis adhuc Romae continebat, solui, si res posceret, ducemque constitui praeceperat. aptatis etiam nauibus ad quascumque legiones meditabatur fugam, speculabundus ex altissima rupe identidem signa, quae, ne nuntii morarentur, tolli procul, ut quidque factum foret, mandauerat. uerum et oppressa coniuratione Seiani nihilo securior aut constantior per nouem proximos menses non egressus est uilla, quae uocatur Ionis.", "st": "Tib. 65"}, {"sp": "N", "t": "Vrebant insuper anxiam mentem uaria undique conuicia, nullo non damnatorum omne probri genus coram uel per libellos in orchestra positos ingerente. quibus quidem diuersissime adficiebatur, modo ut prae pudore ignota et celata cuncta cuperet, nonnumquam eadem contemneret et proferret ultro atque uulgaret. quin et Artabani Parthorum regis laceratus est litteris parricidia et caedes et ignauiam et luxuriam obicientis monentisque, ut uoluntaria morte maximo iustissimoque ciuium odio quam primum satis faceret.", "st": "Tib. 66"}, {"sp": "N", "t": "postremo semet ipse pertaesus, tali[s] epistulae principio tantum non summam malorum suorum professus est: 'quid scribam uobis, p. c., aut quo modo scribam, aut quid omnino non scribam hoc tempore, dii me deaeque peius perdant quam cotidie perire sentio, si scio.' Existimant quidam praescisse haec eum peritia futurorum ac multo ante, quanta se quandoque acerbitas et infamia maneret, prospexisse; ideoque, ut imperium inierit, et patris patriae appellationem et ne in acta sua iuraretur obstinatissime recusasse, ne mox maiore dedecore impar tantis honoribus inueniretur. quod sane ex oratione eius, quam de utraque re habuit, colligi potest; uel cum ait: similem se semper sui futurum nec umquam mutaturum mores suos, quam diu sanae mentis fuisset; sed exempli causa cauendum esse, ne se senatus in acta cuiusquam obligaret, quia aliquo casu mutari posset. et rursus: 'Si quando autem,' inquit, 'de moribus meis deuotoque uobis animo dubitaueritis,—quod prius quam eueniat, opto ut me supremus dies huic mutatae uestrae de me opinioni eripiat—nihil honoris adiciet mihi patria appellatio, uobis autem exprobrabit aut temeritatem delati mihi eius cognominis aut inconstantiam contrarii de me iudicii.'", "st": "Tib. 67"}, {"sp": "N", "t": "Corpore fuit amplo atque robusto, statura quae iustam excederet; latus ab umeris et pectore, ceteris quoque membris usque ad imos pedes aequalis et congruens; sinistra manu agiliore ac ualidiore, articulis ita firmis, ut recens et integrum malum digito terebraret, caput pueri uel etiam adulescentis talitro uulneraret. colore erat candido, capillo pone occipitium summissiore ut ceruicem etiam obtegeret, quod gentile in illo uidebatur; facie honesta, in qua tamen crebri et subiti tumores, cum praegrandibus oculis et qui, quod mirum esset, noctu etiam et in tenebris uiderent, sed ad breue et cum primum e somno patuissent; deinde rursum hebescebant. incedebat ceruice rigida et obstipa, adducto fere uultu, plerumque tacitus, nullo aut rarissimo etiam cum proximis sermone eoque tardissimo, nec sine molli quadam digitorum gesticulatione. quae omnia ingrata atque arrogantiae plena et animaduertit Augustus in eo et excusare temptauit saepe apud senatum ac populum professus naturae uitia esse, non animi. ualitudine prosperrima usus est, tempore quidem principatus paene toto prope inlaesa, quamuis a tricesimo aetatis anno arbitratu eam suo rexerit sine adiumento consilioue medicorum.", "st": "Tib. 68"}, {"sp": "N", "t": "Circa deos ac religiones neglegentior, quippe addictus mathematicae plenusque persuasionis cuncta fato agi, tonitrua tamen praeter modum expauescebat et turbatiore caelo numquam non coronam lauream capite gestauit, quod fulmine afflari negetur id genus frondis.", "st": "Tib. 69"}, {"sp": "N", "t": "Artes liberales utriusque generis studiosissime coluit. in oratione Latina secutus est Coruinum Messalam, quem senem adulescens obseruarat. sed adfectatione et morositate nimia obscurabat stilum, ut aliquanto ex tempore quam a cura praestantior haberetur. composuit et carmen lyricum, cuius est titulus 'conquestio de morte L. Caesaris.' fecit et Graeca poemata imitatus Euphorionem et Rhianum et Parthenium, quibus poetis admodum delectatus scripta omnium et imagines publicis bibliothecis inter ueteres et praecipuos auctores dedicauit; et ob hoc plerique eruditorum certatim ad eum multa de his ediderunt. maxime tamen curauit notitiam historiae fabularis usque ad ineptias atque derisum; nam et grammaticos, quod genus hominum praecipue, ut diximus, appetebat, eius modi fere quaestionibus experiebatur: 'quae mater Hecubae, quod Achilli nomen inter uirgines fuisset, quid Sirenes cantare sint solitae.' et quo primum die post excessum Augusti curiam intrauit, quasi pietati simul ac religioni satis facturus Minonis exemplo ture quidem ac uino uerum sine tibicine supplicauit, ut ille olim in morte filii.", "st": "Tib. 70"}, {"sp": "N", "t": "sermone Graeco quamquam alioqui promptus et facilis, non tamen usque quaque usus est abstinuitque maxime in senatu; adeo quidem, ut monopolium nominaturus ueniam prius postularet, quod sibi uerbo peregrino utendum esset. atque etiam cum in quodam decreto patrum ἔμβλημα recitaretur, commutandam censuit uocem et pro peregrina nostratem requirendam aut, si non reperiretur, uel pluribus et per ambitum uerborum rem enuntiandam. militem quoque Graece testimonium interrogatum nisi Latine respondere uetuit.", "st": "Tib. 71"}, {"sp": "N", "t": "Bis omnino toto secessus tempore Romam redire conatus, semel triremi usque ad proximos naumachiae hortos subuectus est disposita statione per ripas Tiberis, quae obuiam prodeuntis submoueret, iterum Appia usque ad septimum lapidem; sed prospectis modo nec aditis urbis moenibus rediit, primo incertum qua de causa, postea ostento territus. erat ei in oblectamentis serpens draco, quem ex consuetudine manu sua cibaturus cum consumptum a formicis inuenisset, monitus est ut uim multitudinis caueret. rediens ergo propere Campaniam Asturae in languorem incidit, quo paulum leuatus Cerceios pertendit. ac ne quam suspicionem infirmitatis daret, castrensibus ludis non tantum interfuit, sed etiam missum in harenam aprum iaculis desuper petit; statimque latere conuulso et, ut exaestuarat, afflatus aura in grauiorem recidit morbum. sustentauit tamen aliquamdiu, quamuis Misenum usque deuectus nihil ex ordine cotidiano praetermitteret, ne conuiuia quidem aut ceteras uoluptates partim intemperantia partim dissimulatione. nam Chariclen medicum, quod commeatu afuturus e conuiuio egrediens manum sibi osculandi causa apprehendisset, existimans temptatas ab eo uenas, remanere ac recumbere hortatus est cenamque protraxit. nec abstinuit consuetudine quin tunc quoque instans in medio triclinio astante lictore singulos ualere dicentis appellaret.", "st": "Tib. 72"}, {"sp": "N", "t": "interim cum in actis senatus legisset dimissos ac ne auditos quidem quosdam reos, de quibus strictim et nihil aliud quam nominatos ab indice scripserat, pro contempto se habitum fremens repetere Capreas quoquo modo destinauit, non temere quicquam nisi ex tuto ausurus. sed tempestatibus et ingrauescente ui morbi retentus paulo post obiit in uilla Lucullana octauo et septuagesimo aetatis anno, tertio et uicesimo imperii, XVII. Kal. Ap. Cn. Acerronio Proculo C. Pontio Nigrino conss. Sunt qui putent uenenum ei a Gaio datum lentum atque tabificum; alii, in remissione fortuitae febris cibum desideranti negatum; nonnulli, puluinum iniectum, cum extractum sibi deficienti anulum mox resipiscens requisisset. Seneca eum scribit intellecta defectione exemptum anulum quasi alicui traditurum parumper tenuisse, dein rursus aptasse digito et compressa sinistra manu iacuisse diu immobilem; subito uocatis ministris ac nemine respondente consurrexisse nec procul a lectulo deficientibus uiribus concidisse.", "st": "Tib. 73"}, {"sp": "N", "t": "Supremo natali suo Apollinem Temenitem et amplitudinis et artis eximiae, aduectum Syracusis ut in bibliotheca templi noui poneretur, uiderat per quietem affirmantem sibi non posse se ab ipso dedicari. et ante paucos quam obiret dies, turris Phari terrae motu Capreis concidit. ac Miseni cinis e fauilla et carbonibus ad calficiendum triclinium inlatis, extinctus iam et diu frigidus, exarsit repente prima uespera atque in multam noctem pertinaciter luxit.", "st": "Tib. 74"}, {"sp": "N", "t": "Morte eius ita laetatus est populus, ut ad primum nuntium discurrentes pars: 'Tiberium in Tiberim!' clamitarent, pars Terram matrem deosque Manes orarent, ne mortuo sedem ullam nisi inter impios darent, alii uncum et Gemonias cadaueri minarentur, exacerbati super memoriam pristinae crudelitatis etiam recenti atrocitate. nam cum senatus consulto cautum esset, ut poena damnatorum in decimum semper diem differretur, forte accidit ut quorundam supplicii dies is esset, quo nuntiatum de Tiberio erat. hos implorantis hominum fidem, quia absente adhuc Gaio nemo extabat qui adiri interpellarique posset, custodes, ne quid aduersus constitutum facerent, strangulauerunt abieceruntque in Gemonias. creuit igitur inuidia, quasi etiam post mortem tyranni saeuitia permanente. corpus ut moueri a Miseno coepit, conclamantibus plerisque Atellam potius deferendum et in amphitheatro semiustilandum, Romam per milites deportatum est crematumque publico funere.", "st": "Tib. 75"}, {"sp": "N", "t": "Testamentum duplex ante biennium fecerat, alterum sua, alterum liberti manu, sed eodem exemplo, obsignaueratque etiam humillimorum signis. eo testamento heredes aequis partibus reliquit Gaium ex Germanico et Tiberium ex Druso nepotes substituitque in uicem; dedit et legata plerisque, inter quos uirginibus Vestalibus, sed et militibus uniuersis plebeique Romanae uiritim atque etiam separatim uicorum magistris.", "st": "Tib. 76"}], []);})();
